// Magic numbers para validação de imagens
const IMAGE_MAGIC_NUMBERS = {
  jpg: [0xff, 0xd8, 0xff],
  jpeg: [0xff, 0xd8, 0xff],
  png: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
  webp: [0x52, 0x49, 0x46, 0x46],
};

// Função para validar magic number de imagem
function validateImageMagicNumber(buffer: Buffer): boolean {
  for (const [format, signature] of Object.entries(IMAGE_MAGIC_NUMBERS)) {
    if (signature.every((byte, index) => buffer[index] === byte)) {
      return true;
    }
  }
  return false;
}

// Middleware para verificar autenticação obrigatória
async function requireAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    const logAuth = (status: "granted" | "denied", source: string, detail?: string) => {
      const requestId = String(req.headers["x-request-id"] || "");
      console.log(
        `[AUTH_TRACE] status=${status} source=${source} requestId=${requestId} path=${req.path} method=${req.method}${detail ? ` detail=${detail}` : ""}`
      );
    };

    // 🔒 PRIORIDADE 0: Dev mode — bypass RBAC apenas quando sessão dev já autenticada
    const isDevMode = isDevRequest(req);

    if (isDevMode) {
      const devUser: any = { id: 1, nome: 'Dev User', papel: 'dev' };
      const urlMatch = req.path.match(/\/api\/monitor\/([0-9]+)/);
      const targetId = urlMatch ? parseInt(urlMatch[1]) : null;
      if (targetId && !isNaN(targetId)) {
        try {
          const targetUser = await db.select().from(users).where(eq(users.id, targetId)).limit(1);
          if (targetUser?.length) {
            devUser.id = targetId;
            devUser.email = targetUser[0].email;
            devUser.nome = targetUser[0].nome || 'Dev User';
          }
          if (!devUser.email || devUser.id === 1) {
            const monitorRow = await db.select().from(monitores).where(eq(monitores.id, targetId)).limit(1);
            if (monitorRow?.length) {
              devUser.email = monitorRow[0].email;
              devUser.monitorId = monitorRow[0].id;
            }
          }
        } catch (e) { /* silently continue */ }
      }
      (req as any).user = devUser;
      (req as any).isDeveloper = true;
      logAuth("granted", "dev_session", `userId=${devUser.id}`);
      return next();
    }

    const session = req.session as any;

    // 🔒 PRIORIDADE 1: Sessão do portal do aluno (CPF canônico)
    if (
      session?.user?.id &&
      (session.user.actorType === "aluno" ||
        session.user.papel === "aluno" ||
        session.user.role === "aluno")
    ) {
      const u = session.user;
      const cpf = String(u.cpf || u.id).replace(/\D/g, "");
      if (!cpf || cpf.length !== 11) {
        logAuth("denied", "aluno_invalid_session");
        return res.status(401).json({ error: "Autenticação obrigatória" });
      }
      (req as any).user = {
        id: cpf,
        cpf,
        papel: "aluno",
        role: "aluno",
        nome: u.nome,
        actorType: "aluno",
        alunoTipo: u.alunoTipo || null,
        participanteId: u.participanteId ?? null,
      };
      logAuth("granted", "session_aluno", `cpf=${cpf.slice(0, 3)}***`);
      return next();
    }

    // 🔒 PRIORIDADE 2: Sessão de monitor/professor/usuário comum
    if (session?.user?.id) {
      const sessionUser = session.user;
      (req as any).user = {
        id: sessionUser.id,
        papel: sessionUser.role || sessionUser.papel || sessionUser.tipo,
        role: sessionUser.role || sessionUser.papel || sessionUser.tipo,
        email: sessionUser.email,
        nome: sessionUser.nome,
        telefone: sessionUser.telefone,
        monitorId: sessionUser.monitorId,
        professorId: sessionUser.professorId,
        coordenadorId: sessionUser.coordenadorId,
        programa: sessionUser.programa,
        actorType: sessionUser.actorType || sessionUser.tipo || "usuario",
      };
      logAuth("granted", "session_user", `userId=${sessionUser.id}`);
      return next();
    }

    // Portal do aluno (CPF na sessão — antes de userId/userPapel genérico)
    if (session?.alunoCpf && session?.actorType === "aluno_portal") {
      const cpf = String(session.alunoCpf).replace(/\D/g, "");
      (req as any).user = {
        id: cpf,
        cpf,
        papel: "aluno_portal",
        role: "aluno_portal",
        nome: session.alunoNome || "",
        actorType: "aluno_portal",
        alunoCpf: cpf,
        alunoTipo: session.alunoTipo || null,
      };
      logAuth("granted", "session_aluno_portal", `cpf=${cpf.slice(0, 3)}***`);
      return next();
    }

    // 🔒 PRIORIDADE 2b: Sessão simplificada (ex.: login de desenvolvedor)
    if (session?.userId && session?.userPapel) {
      (req as any).user = {
        id: session.userId,
        papel: session.userPapel,
        role: session.userPapel,
        email: session.userEmail || "",
        nome: session.userName || "",
        actorType: session.actorType || "usuario",
      };
      logAuth("granted", "session_userId", `userId=${session.userId}`);
      return next();
    }

    // 🔒 PRIORIDADE 3: Sessão de coordenador
    if (session?.isCoordinator && session?.coordenadorId) {
      const coordId = session.coordenadorId;
      const coordenador = await db
        .select()
        .from(coordenadores)
        .where(eq(coordenadores.id, coordId))
        .limit(1);

      if (coordenador && coordenador.length > 0) {
        (req as any).coordenador = coordenador[0];
        (req as any).user = {
          id: coordId,
          coordenadorId: coordId,
          papel: session.userPapel || "coordenador",
          role: session.userPapel || "coordenador",
          email: session.coordenadorEmail || session.userEmail || coordenador[0].email,
          nome: session.coordenadorNome || session.userName || coordenador[0].nome,
          actorType: "coordenador",
        };
        logAuth("granted", "session_coordenador", `userId=${coordId}`);
        return next();
      }
    }

    // Scanner de ingressos (SEC-009)
    if (session?.scannerUserId && session?.actorType === "scanner") {
      (req as any).user = {
        id: session.scannerUserId,
        papel: "scanner",
        role: "scanner",
        nome: session.scannerNome || session.userName || "",
        actorType: "scanner",
      };
      logAuth("granted", "session_scanner", `scannerId=${session.scannerUserId}`);
      return next();
    }

    if (session?.tabletChamadaUserId && session?.actorType === "tablet_chamada") {
      (req as any).user = {
        id: session.tabletChamadaUserId,
        papel: "tablet_chamada",
        role: "tablet_chamada",
        nome: session.tabletChamadaNome || session.userName || "",
        actorType: "tablet_chamada",
        vertente: session.tabletChamadaVertente || null,
      };
      logAuth("granted", "session_tablet_chamada", `tabletId=${session.tabletChamadaUserId}`);
      return next();
    }

    logAuth("denied", "no_session");
    return res.status(401).json({
      error: "Autenticação obrigatória",
    });
  } catch (error) {
    console.error("Erro no middleware de autenticação:", error);
    res.status(500).json({ error: "Erro interno do servidor" });
  }
}

// Middleware para verificar autenticação de desenvolvedor
async function requireDevAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    console.log("[requireDevAuth] Session data:", {
      hasSession: !!req.session,
      developerId: req.session?.developerId,
      userPapel: req.session?.userPapel,
      sessionID: req.sessionID,
    });

    const developerId = req.session?.developerId;
    const userPapel = req.session?.userPapel;

    if (
      !developerId ||
      (userPapel !== "dev" && userPapel !== "desenvolvedor")
    ) {
      console.log("[requireDevAuth] Auth failed - missing session data");
      return res
        .status(401)
        .json({ error: "Acesso negado - sessão de desenvolvedor requerida" });
    }

    // Anexar info do desenvolvedor ao request
    (req as any).developerId = developerId;
    console.log("[requireDevAuth] Auth successful for developer:", developerId);
    return next();
  } catch (error) {
    console.error("[requireDevAuth] Error:", error);
    return res.status(500).json({ error: "Erro ao verificar autenticação" });
  }
}

// Middleware para verificar se usuário é admin
function requireAdmin(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const user = (req as any).user;
  if (!user) {
    return res.status(401).json({ error: "Usuário não autenticado" });
  }

  const isAdmin =
    isAdminEmail(user.email) || user.role === "admin" || user.tipo === "admin";
  if (!isAdmin) {
    console.warn(
      `🚨 [SECURITY] Tentativa de acesso admin negada - Usuário ${user.id} (${user.email})`
    );
    return res.status(403).json({
      error: "Acesso negado - privilégios administrativos necessários",
    });
  }

  console.log(`✅ [ADMIN ACCESS] Admin ${user.id} (${user.email}) autorizado`);
  next();
}

function requirePrivacyAuditAccess(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const sess = req.session as any;

  // Sessão do painel /dev (developerId) tem prioridade sobre sessão de aluno no mesmo navegador
  if (
    sess?.developerId &&
    (sess.userPapel === "dev" || sess.userPapel === "desenvolvedor")
  ) {
    return next();
  }

  const user = (req as any).user;
  if (!user) {
    return res.status(401).json({ error: "Usuário não autenticado" });
  }

  const role = String(user.papel || user.role || user.tipo || "").toLowerCase();
  const allowedRoles = new Set([
    "admin",
    "super_admin",
    "leo",
    "dev",
    "desenvolvedor",
  ]);

  if (isAdminEmail(user.email) || allowedRoles.has(role)) {
    return next();
  }

  return res.status(403).json({
    error: "Acesso negado - privilégios de auditoria LGPD necessários",
  });
}

// ================ RBAC MIDDLEWARE SYSTEM ================
// Middleware para verificação de papéis específicos RBAC
function requireRole(allowedRoles: string[]) {
  return (
    req: express.Request,
    res: express.Response,
    next: express.NextFunction
  ) => {
    const user = (req as any).user;
    if (!user) {
      return res.status(401).json({ error: "Usuário não autenticado" });
    }

    // Obter papel do usuário (compatibilidade com campos existentes)
    const userRole = user.papel || user.userPapel || user.role || user.tipo;

    // SEC-013: sem bypass global para "dev" — papel deve estar em allowedRoles
    // (rotas /api/dev/* usam middleware dedicado em server/index.ts)

    // Verificar se o papel do usuário está na lista de papéis permitidos
    if (!userRole || !allowedRoles.includes(userRole)) {
      console.warn(
        `🚨 [RBAC] Acesso negado - Usuário ${user.id} (${user.email
        }) papel "${userRole}" não autorizado. Papéis permitidos: ${allowedRoles.join(
          ", "
        )}`
      );
      return res.status(403).json({
        error: "Acesso negado - papel insuficiente",
        details: `Papel "${userRole}" não autorizado para este recurso`,
      });
    }

    console.log(`✅ [RBAC] Usuário ${user.id} papel "${userRole}" autorizado`);
    next();
  };
}

// Helper para verificar acesso a recursos próprios com bypass dev mode
function ensureSelfAccess(
  user: any,
  targetId: number,
  resourceName: string = "recurso"
): { allowed: boolean; error?: any } {
  const userRole = user.papel || user.userPapel || user.role || user.tipo;
  const superRoles = ["admin", "leo", "coordenador_psico", "coordenador_pec", "coordenador_inclusao", "coordenador"];
  if (superRoles.includes(userRole)) {
    return { allowed: true };
  }

  if (user.id !== targetId) {
    console.warn(
      `🚨 [SECURITY] User ${user.id} tentou acessar ${resourceName} de user ${targetId}`
    );
    return {
      allowed: false,
      error: {
        status: 403,
        message: `Acesso negado - você só pode acessar seu próprio ${resourceName}`,
      },
    };
  }

  return { allowed: true };
}

