function assertProfessorResourceAccess(
  req: express.Request,
  professorId: number
): { allowed: boolean; status?: number; message?: string } {
  const user = (req as any).user;
  if (!user?.id) {
    return { allowed: false, status: 401, message: "Não autenticado" };
  }
  const role = String(user.papel || user.role || "").toLowerCase();
  if (
    COORDENADOR_API_ROLES.some(
      (r) => role === r || role.includes("coordenador") || role === "admin"
    )
  ) {
    return { allowed: true };
  }
  const sessionProfessorId = Number((req.session as any)?.user?.professorId);
  if (
    Number.isFinite(sessionProfessorId) &&
    sessionProfessorId === professorId
  ) {
    return { allowed: true };
  }
  if (Number(user.id) === professorId) {
    return { allowed: true };
  }
  return {
    allowed: false,
    status: 403,
    message: "Acesso negado ao recurso de outro professor",
  };
}

async function assertStripeSubscriptionOwner(
  req: express.Request,
  subscriptionId: string
): Promise<{ ok: boolean; status?: number; error?: string }> {
  const user = (req as any).user;
  if (!user?.id) {
    return { ok: false, status: 401, error: "Não autenticado" };
  }
  const role = String(user.papel || user.role || "").toLowerCase();
  if (["admin", "leo", "super_admin", "dev", "desenvolvedor"].includes(role)) {
    return { ok: true };
  }
  const [row] = await db
    .select({ stripeSubscriptionId: users.stripeSubscriptionId })
    .from(users)
    .where(eq(users.id, Number(user.id)))
    .limit(1);
  if (row?.stripeSubscriptionId === subscriptionId) {
    return { ok: true };
  }
  return {
    ok: false,
    status: 403,
    error: "Assinatura não pertence ao usuário autenticado",
  };
}

/** Sessão cookie ou userId explícito (checkout) vinculado ao stripe_subscription_id. */
async function resolveSubscriptionAccess(
  req: express.Request,
  subscriptionId: string,
  userIdHint?: unknown
): Promise<{ ok: boolean; status?: number; error?: string }> {
  const session = req.session as any;
  const sessionUserId = session?.user?.id ?? session?.userId;
  if (sessionUserId) {
    (req as any).user = {
      id: sessionUserId,
      papel: session?.user?.role || session?.userPapel,
      role: session?.user?.role || session?.userPapel,
    };
    return assertStripeSubscriptionOwner(req, subscriptionId);
  }

  const uid = userIdHint != null ? Number(userIdHint) : NaN;
  if (!Number.isFinite(uid) || uid <= 0) {
    return {
      ok: false,
      status: 401,
      error: "Autenticação necessária para acessar esta assinatura",
    };
  }

  const [row] = await db
    .select({ stripeSubscriptionId: users.stripeSubscriptionId })
    .from(users)
    .where(eq(users.id, uid))
    .limit(1);

  if (row?.stripeSubscriptionId === subscriptionId) {
    return { ok: true };
  }

  return {
    ok: false,
    status: 403,
    error: "Assinatura não pertence ao usuário informado",
  };
}

function phonesMatchLoose(a: string, b: string): boolean {
  const da = a.replace(/\D/g, "").slice(-11);
  const db = b.replace(/\D/g, "").slice(-11);
  return da.length >= 10 && da === db;
}

/** Escopo de leitura/escrita em moradas gerais (monitor vs coordenador/dev). */
function getMoradasGeraisAccess(req: express.Request) {
  const user = (req as any).user ?? {};
  const papel = String(user.papel || user.role || user.tipo || "").toLowerCase();
  const actorType = String(user.actorType || "").toLowerCase();
  const userId = user.id != null ? Number(user.id) : NaN;
  const isDev =
    !!(req as any).isDeveloper ||
    ["dev", "desenvolvedor", "dev-marketing", "admin", "leo"].includes(papel);
  const isCoord =
    actorType === "coordenador" ||
    papel.includes("coordenador") ||
    papel === "tecnica_psico";
  const isMonitorPsico = papel === "monitor_psico";
  return {
    userId: Number.isFinite(userId) ? userId : null,
    isDev,
    isCoord,
    isMonitorPsico,
    canViewAll: isDev || isCoord,
    canManageAll: isDev || isCoord,
  };
}

/** GET: monitor vê só o próprio; coord/dev vê todos ou filtra por ?monitorId= */
function resolveMoradasListMonitorId(req: express.Request): number | null {
  const access = getMoradasGeraisAccess(req);
  const queryIdRaw = req.query.monitorId ? Number(req.query.monitorId) : null;
  const queryId =
    queryIdRaw != null && Number.isFinite(queryIdRaw) && queryIdRaw > 0
      ? queryIdRaw
      : null;

  if (access.canViewAll) return queryId;
  if (access.isMonitorPsico && access.userId) return access.userId;
  return queryId;
}

/** POST/PUT: monitor grava sempre no próprio id; coord/dev exige monitorId (users.id) no body */
function resolveMoradasWriteMonitorId(
  req: express.Request,
  bodyMonitorId: unknown
): number | null {
  const access = getMoradasGeraisAccess(req);
  const bodyId = bodyMonitorId != null ? Number(bodyMonitorId) : NaN;
  const validBody =
    Number.isFinite(bodyId) && bodyId > 0 ? bodyId : null;

  if (access.isMonitorPsico && access.userId) return access.userId;
  if (access.canManageAll) return validBody;
  return validBody;
}

async function assertMoradasReformaRowAccess(
  req: express.Request,
  rowMonitorId: number
): Promise<boolean> {
  const access = getMoradasGeraisAccess(req);
  if (access.canManageAll) return true;
  if (access.isMonitorPsico && access.userId === rowMonitorId) return true;
  return false;
}

async function resolveProfessorContextByUserId(
  userId: number,
  vertente: "pec" | "inclusao"
): Promise<{ professorId: number | null; turmaTipo: "pec" | "inclusao" }> {
  const turmaTipo = vertente === "inclusao" ? "inclusao" : "pec";
  const programa = vertente === "inclusao" ? "inclusao_produtiva" : "pec";

  const userRow = await pool.query("SELECT email FROM users WHERE id = $1", [userId]);
  const email = userRow.rows?.[0]?.email;
  if (!email) return { professorId: null, turmaTipo };

  const profRow = await pool.query(
    "SELECT id FROM professores WHERE lower(email) = lower($1) AND programa = $2 LIMIT 1",
    [email, programa]
  );

  const professorId = profRow.rows?.[0]?.id ?? null;
  return { professorId, turmaTipo };
}

async function canProfessorAccessTurma(
  userId: number,
  turmaId: number,
  vertente: "pec" | "inclusao"
): Promise<boolean> {
  if (!turmaId || Number.isNaN(turmaId)) return false;
  const allowedIds = await getProfessorTurmaIdsForVertente(userId, vertente);
  return allowedIds.includes(turmaId);
}

/** Turmas que o professor pode acessar na vertente (professor_turmas + legado inclusão). */
async function getProfessorTurmaIdsForVertente(
  userId: number,
  vertente: "pec" | "inclusao"
): Promise<number[]> {
  const { professorId, turmaTipo } = await resolveProfessorContextByUserId(userId, vertente);

  if (professorId) {
    const assignments = await pool.query(
      "SELECT turma_id FROM professor_turmas WHERE professor_id = $1 AND turma_tipo = $2",
      [professorId, turmaTipo]
    );
    if (assignments.rows.length > 0) {
      return assignments.rows.map((r: { turma_id: number }) => r.turma_id);
    }
  }

  if (vertente === "inclusao") {
    const professorIdsFallback = [
      ...(professorId != null ? [professorId] : []),
      userId,
    ];
    const legacy = await db
      .select({ id: turmasInclusao.id })
      .from(turmasInclusao)
      .where(inArray(turmasInclusao.professorId, professorIdsFallback));
    return legacy.map((t) => t.id);
  }

  return [];
}

