// Middleware para verificar múltiplos papéis (permite qualquer um da lista)
function requireAnyRole(allowedRoles: string[]) {
  return requireRole(allowedRoles);
}

function requireDevApiAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const openPaths = new Set(["/login", "/status"]);
  if (openPaths.has(req.path)) return next();
  return requireAuth(req, res, () =>
    requireRole(["dev", "admin"])(req, res, next)
  );
}

// Middleware para validação de imagem com magic number
// TRECHO ALTERADO
// ✅ Versão compatível com memoryStorage
function validateImageFile(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    const f = req.file;

    if (!f) {
      return res.status(400).json({ error: "Nenhum arquivo foi enviado" });
    }

    // ✅ diskStorage: valida usando o arquivo salvo em disco
    if (!f.path) {
      return res.status(400).json({ error: "Arquivo inválido (sem caminho no disco)" });
    }

    // lê o arquivo real
    const buf = fs.readFileSync(f.path);

    if (!buf || buf.length === 0) {
      return res.status(400).json({ error: "Arquivo inválido ou vazio" });
    }

    // 1) magic number
    if (!validateImageMagicNumber(buf)) {
      return res.status(400).json({
        error: "Arquivo não é uma imagem válida ou formato não suportado",
        details: "Apenas JPEG, PNG e WEBP são permitidos",
      });
    }

    // 2) tamanho (também dá pra usar f.size, mas garantimos pelo buffer)
    if (buf.length > 5 * 1024 * 1024) {
      return res.status(400).json({
        error: "Arquivo muito grande",
        details: "Tamanho máximo permitido: 5MB",
      });
    }

    // 3) reforço por mime/extensão
    const allowedMimes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    const ext = path.extname(f.originalname || "").toLowerCase();
    const allowedExt = [".jpg", ".jpeg", ".png", ".webp"];

    if (!allowedMimes.includes(f.mimetype) || !allowedExt.includes(ext)) {
      return res.status(400).json({ error: "Formato não permitido" });
    }

    console.log(`✅ [FILE VALIDATION] Arquivo ${f.originalname || "(sem nome)"} validado com sucesso`);
    return next();
  } catch (err: any) {
    console.error("❌ [FILE VALIDATION] Erro:", err?.message || err);
    if (!res.headersSent) {
      return res.status(500).json({
        error: "Falha ao validar imagem",
        details: err?.message || String(err),
      });
    }
  }
}

function validateImageMemory(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const f = req.file;
  if (!f?.buffer?.length) {
    return res.status(400).json({ error: "Nenhum arquivo foi enviado" });
  }
  if (!validateImageMagicNumber(f.buffer)) {
    return res.status(400).json({
      error: "Arquivo não é uma imagem válida",
      details: "Apenas JPEG, PNG e WEBP são permitidos",
    });
  }
  if (f.buffer.length > 5 * 1024 * 1024) {
    return res.status(400).json({ error: "Arquivo muito grande", details: "Máximo 5MB" });
  }
  return next();
}

function validateImagesMemoryArray(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const files = (req.files as Express.Multer.File[]) || [];
  if (!files.length) {
    return res.status(400).json({ error: "Nenhum arquivo enviado" });
  }
  for (const f of files) {
    if (!f.buffer || !validateImageMagicNumber(f.buffer)) {
      return res.status(400).json({ error: "Arquivo inválido na lista de upload" });
    }
    if (f.buffer.length > 5 * 1024 * 1024) {
      return res.status(400).json({ error: "Arquivo muito grande (máx 5MB)" });
    }
  }
  return next();
}

// Configuração segura do multer com validação aprimorada
const secureUpload = multer({
  storage: storage_multer,
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB máximo para segurança
    files: 1, // Apenas um arquivo por vez
  },
  fileFilter: (req, file, cb) => {
    // Validação primária por MIME type
    const allowedMimes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    if (!allowedMimes.includes(file.mimetype)) {
      return cb(
        new Error("Formato não permitido. Use apenas JPEG, PNG ou WEBP")
      );
    }

    // Validação de extensão de arquivo
    const allowedExtensions = [".jpg", ".jpeg", ".png", ".webp"];
    const fileExtension = path.extname(file.originalname).toLowerCase();
    if (!allowedExtensions.includes(fileExtension)) {
      return cb(new Error("Extensão de arquivo não permitida"));
    }

    cb(null, true);
  },
});

