if (!process.env.OMIE_APP_KEY || !process.env.OMIE_APP_SECRET) {
  console.warn(
    "⚠️  OMIE_APP_KEY and OMIE_APP_SECRET not configured. Omie integration will be disabled."
  );
}

interface OmieApiCall {
  call: string;
  app_key: string;
  app_secret: string;
  param: any[];
}

interface OmieResponse {
  categoria_cadastro?: any[];
  categoria_busca?: any[];
  conta_pagar_list?: any[];
  conta_receber_list?: any[];
  ContaCorrente?: any[];
  resumo?: any;
  projetos?: any[];
  error?: string;
}

// Função para fazer chamadas à API do Omie
async function callOmieAPI(
  endpoint: string,
  callAction: string,
  params: any = []
): Promise<any> {
  if (!process.env.OMIE_APP_KEY || !process.env.OMIE_APP_SECRET) {
    throw new Error("Credenciais do Omie não configuradas");
  }

  const payload: OmieApiCall = {
    call: callAction,
    app_key: process.env.OMIE_APP_KEY,
    app_secret: process.env.OMIE_APP_SECRET,
    param: params,
  };

  console.log(`🔵 [OMIE] Chamando ${endpoint} → ${callAction}`);

  try {
    const response = await fetch(
      `https://app.omie.com.br/api/v1/${endpoint}/`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      }
    );

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    const data = await response.json();

    if (data.faultstring || data.error) {
      console.error(
        `❌ [OMIE] Erro em ${endpoint}:`,
        data.faultstring || data.error
      );
      return { error: data.faultstring || data.error };
    }

    console.log(`✅ [OMIE] Sucesso em ${endpoint}`);
    return data;
  } catch (error) {
    console.error(`❌ [OMIE] Falha na conexão com ${endpoint}:`, error);
    return {
      error: error instanceof Error ? error.message : "Erro desconhecido",
    };
  }
}

