  // SEC-017: uploads protegidos — arquivos locais (ex: profile-123456.jpg)
  app.get("/uploads/:filename", requireAuth, (req, res) => {
    const safe = path.basename(req.params.filename);
    if (!safe || safe.includes("..")) {
      return res.status(400).json({ error: "Nome do arquivo inválido" });
    }
    const filePath = path.resolve(process.cwd(), "uploads", safe);
    const uploadsRoot = path.resolve(process.cwd(), "uploads");
    if (!filePath.startsWith(uploadsRoot + path.sep)) {
      return res.status(400).json({ error: "Caminho inválido" });
    }
    if (!fs.existsSync(filePath)) {
      return res.sendStatus(404);
    }
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Content-Disposition", "inline");
    res.setHeader("Cache-Control", "private, max-age=3600");
    return res.sendFile(filePath);
  });

  // SEC-017: objetos no GCS referenciados por /uploads/... (ex: beneficios)
  app.get("/uploads/*", requireAuth, async (req, res) => {
    try {
      const objectName = req.path.slice(1);
      const [signedUrl] = await gcs
        .bucket(GCS_BUCKET)
        .file(objectName)
        .getSignedUrl({
          version: "v4",
          action: "read",
          expires: Date.now() + 5 * 60 * 1000,
        });
      return res.redirect(302, signedUrl);
    } catch (err) {
      console.error("❌ /uploads/* Signed URL error:", err);
      return res.status(404).send("Arquivo não encontrado");
    }
  });

