  // Create subscription for internal checkout
  app.post("/api/create-subscription", async (req, res) => {
    try {
      const { planId, customAmount, paymentMethodId, periodicity, price } =
        req.body;

      // 🔒 SECURITY: Derive userId from authenticated session, not client input
      const authenticatedUserId =
        (req as any).session?.user?.id || (req as any).user?.id;

      // 🛡️ SECURITY: Require authentication to create subscription
      if (!authenticatedUserId) {
        console.error(
          "🚨 [SECURITY] Unauthenticated subscription attempt blocked"
        );
        return res
          .status(401)
          .json({ error: "Autenticação necessária para criar assinatura" });
      }

      // Critical validation to prevent incorrect charging
      if (!planId) {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Missing planId - this could cause incorrect charging!"
        );
        return res.status(400).json({ error: "PlanId é obrigatório" });
      }

      // Validate planId against known plans
      const validPlans = ["eco", "voz", "grito", "platinum", "diamante"];
      if (!validPlans.includes(planId.toLowerCase()) && planId !== "platinum") {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Invalid planId:",
          planId,
          "Valid plans:",
          validPlans
        );
        return res.status(400).json({ error: `Plano inválido: ${planId}` });
      }

      // Create or retrieve customer using centralized function (prevents duplicates)
      const customerId = await getOrCreateStripeCustomer(authenticatedUserId);

      // Attach payment method safely (prevents duplicates)
      if (paymentMethodId) {
        const { paymentMethodId: finalPmId } = await attachPaymentMethodSafely(
          paymentMethodId,
          customerId
        );

        // Set as default payment method
        await stripe.customers.update(customerId, {
          invoice_settings: {
            default_payment_method: finalPmId,
          },
        });
      }

      let productName: string;
      let productDescription: string;
      let unitAmount: number;
      let intervalConfig: { interval: string; interval_count?: number } = {
        interval: "month",
      };

      if (planId === "platinum" && customAmount) {
        // Plano flexível - Platinum personalizado
        productName = "Platinum Personalizado";
        productDescription = "Valor personalizado escolhido pelo usuário";
        unitAmount = Math.round(customAmount * 100); // Converte para centavos
        console.log(
          "💰 [SUBSCRIPTION] Platinum custom plan:",
          unitAmount,
          "cents"
        );
      } else if (price && periodicity) {
        // NOVO: Usar preço e periodicidade específicos do frontend
        const plan = planPricing[planId as keyof typeof planPricing];
        if (!plan) {
          console.error(
            "❌ [SUBSCRIPTION ERROR] Plan not found in planPricing:",
            planId,
            "Available plans:",
            Object.keys(planPricing)
          );
          return res
            .status(400)
            .json({ error: `Plano não encontrado: ${planId}` });
        }

        productName = plan.name;
        productDescription = plan.description;
        unitAmount = Math.round(price * 100); // Frontend já enviou o preço correto

        // Configurar intervalo baseado na periodicidade
        switch (periodicity) {
          case "mensal":
            intervalConfig = { interval: "month" };
            break;
          case "trimestral":
            intervalConfig = { interval: "month", interval_count: 3 };
            break;
          case "semestral":
            intervalConfig = { interval: "month", interval_count: 6 };
            break;
          case "anual":
            intervalConfig = { interval: "month", interval_count: 12 };
            break;
          default:
            console.log(
              "⚠️ [SUBSCRIPTION] Periodicidade desconhecida, usando mensal:",
              periodicity
            );
            intervalConfig = { interval: "month" };
        }

        console.log(
          "💰 [SUBSCRIPTION] Plan with periodicity:",
          planId,
          periodicity,
          "price:",
          unitAmount,
          "cents (R$",
          (unitAmount / 100).toFixed(2),
          ")"
        );
      } else if (planPricing[planId as keyof typeof planPricing]) {
        // Fallback: Planos fixos usando apenas plano mensal (compatibilidade)
        const plan = planPricing[planId as keyof typeof planPricing];
        productName = plan.name;
        productDescription = plan.description;
        unitAmount = plan.price; // Já em centavos
        console.log(
          "💰 [SUBSCRIPTION] Fixed plan selected (mensal fallback):",
          planId,
          "price:",
          unitAmount,
          "cents (R$",
          (unitAmount / 100).toFixed(2),
          ")"
        );
      } else {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Plan not found in planPricing:",
          planId,
          "Available plans:",
          Object.keys(planPricing)
        );
        return res
          .status(400)
          .json({ error: `Plano não encontrado: ${planId}` });
      }

      // Create product first
      const product = await stripe.products.create({
        name: productName,
        description: productDescription,
      });

      // Create price for the product with correct interval
      const stripePrice = await stripe.prices.create({
        product: product.id,
        currency: "brl",
        unit_amount: unitAmount,
        recurring: intervalConfig,
      });

      // === CRIAR PAYMENTINTENT PARA PRIMEIRO PAGAMENTO ===
      // Criar PaymentIntent direto (webhook cria subscription depois)
      const paymentIntent = await stripe.paymentIntents.create({
        amount: unitAmount,
        currency: "brl",
        customer: customerId,
        payment_method_types: ["card"],
        setup_future_usage: "off_session",
        metadata: {
          planId: planId,
          authenticatedUserId: String(authenticatedUserId || ""),
          isRecurring: "true",
          priceId: stripePrice.id,
        },
      });

      console.log("✅ PAYMENTINTENT criado para subscription:", {
        paymentIntentId: paymentIntent.id,
        amount: unitAmount / 100,
        customer: customerId,
      });

      // CRITICAL: Create donor record immediately
      try {
        await db.insert(doadores).values({
          userId: authenticatedUserId || null,
          plano: planId,
          valor: (unitAmount / 100).toString(),
          stripePaymentIntentId: paymentIntent.id,
          status: "pending",
          dataDoacaoInicial: new Date(),
          ativo: true,
        });
        console.log(
          "✅ [SUBSCRIPTION] Donor record created for PaymentIntent:",
          paymentIntent.id
        );
      } catch (dbError: any) {
        console.error(
          "❌ [SUBSCRIPTION] Failed to create donor record:",
          dbError
        );
      }

      res.json({
        customerId: customer.id,
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
        requiresAction: paymentIntent.status === "requires_action",
      });
    } catch (error: any) {
      console.error("Error creating subscription:", error);
      res.status(500).json({ error: "Erro ao criar subscription" });
    }
  });

  // 🔒 WEBHOOK SEGURO - Verificação de assinatura obrigatória

  app.post("/api/webhook/stripe", async (req, res) => {
    const sig = req.headers["stripe-signature"];
    const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

    if (!endpointSecret) {
      console.error("🚨 WEBHOOK ERROR: STRIPE_WEBHOOK_SECRET não configurado");
      return res.status(500).json({ error: "Webhook endpoint secret not configured" });
    }

    if (!sig) {
      console.error("🚨 WEBHOOK ERROR: Assinatura não fornecida");
      return res.status(400).json({ error: "Missing stripe signature" });
    }

    let event: Stripe.Event;

    // ✅ 1) Verificar assinatura (obrigatório)
    try {
      const rawBody = Buffer.isBuffer(req.body)
        ? req.body
        : Buffer.from(
          typeof req.body === "string" ? req.body : JSON.stringify(req.body),
          "utf8"
        );

      event = stripe.webhooks.constructEvent(rawBody, sig as string, endpointSecret);
      console.log(`✅ [WEBHOOK SECURE] Evento ${event.type} validado com sucesso`);
    } catch (err: any) {
      console.error("🚨 [WEBHOOK SECURITY] Verificação de assinatura falhou:", err?.message);
      return res.status(400).json({
        error: `Webhook signature verification failed: ${err?.message}`,
      });
    }

    // ✅ 2) Processar (sempre responder 2xx rápido quando possível)
    try {
      switch (event.type) {
        // =====================================================
        // CHECKOUT - SESSÃO COMPLETA
        // =====================================================
        case "checkout.session.completed": {
          const session = event.data.object as Stripe.Checkout.Session;
          console.log("Checkout session completed:", session.id);

          try {
            const retrievedSession = await stripe.checkout.sessions.retrieve(session.id, {
              expand: ["subscription", "customer"],
            });

            // 🎫 Pagamento de ingresso
            if (retrievedSession.metadata?.type === "ingresso") {
              console.log("🎫 [WEBHOOK] Processando pagamento de ingresso:", session.id);

              const customer = retrievedSession.customer_details;
              const nomeComprador = customer?.name || "";
              const emailComprador = customer?.email || "";
              const telefoneComprador = customer?.phone || "";

              const ingressoData = {
                userId: null,
                nomeComprador,
                emailComprador,
                telefoneComprador,
                stripeCheckoutSessionId: session.id,
                valorPago: 1990,
                status: "ativo",
                dataCompra: new Date(),
              };

              const ingresso = await storage.createIngresso(ingressoData);
              console.log(
                `✅ [WEBHOOK] Ingresso criado com sucesso: ${ingresso.numero} (ID: ${ingresso.id})`
              );
              break;
            }

            // 💳 Subscription recorrente personalizada (fluxo custom)
            if (retrievedSession.metadata?.customSubscription === "true") {
              console.log("💰 [WEBHOOK] Processando subscription recorrente personalizada:", session.id);

              const customerId = retrievedSession.customer as string | null;
              const subscriptionId = retrievedSession.subscription as string | null;
              const customerEmail = retrievedSession.customer_details?.email || "";
              const customerName = retrievedSession.customer_details?.name || "";

              if (!customerId || !subscriptionId) {
                console.error("❌ [WEBHOOK] Customer ID ou Subscription ID ausente");
                break;
              }

              try {
                const stripeSubscription = await stripe.subscriptions.retrieve(subscriptionId);

                const tier = retrievedSession.metadata?.tier || "PLATINUM";
                const amountMonthly = parseFloat(retrievedSession.metadata?.amountMonthly || "0");
                const intervalMonths = parseInt(retrievedSession.metadata?.intervalMonths || "1");

                console.log(
                  `✅ [WEBHOOK] Subscription criada - Tier: ${tier}, Valor: R$ ${amountMonthly}, Intervalo: ${intervalMonths} meses`
                );

                // Buscar usuário pelo email
                let userId: number | null = null;
                const existingUser = await db
                  .select()
                  .from(users)
                  .where(eq(users.email, customerEmail))
                  .limit(1);

                if (existingUser.length > 0) {
                  userId = existingUser[0].id;
                  console.log(`✅ [WEBHOOK] Usuário encontrado: ${userId}`);

                  await db
                    .update(users)
                    .set({
                      stripeCustomerId: customerId,
                      stripeSubscriptionId: subscriptionId,
                      plano: tier.toLowerCase(),
                    })
                    .where(eq(users.id, userId));
                } else {
                  console.log(`⚠️ [WEBHOOK] Usuário não encontrado para email: ${customerEmail}`);
                }

                // donorSubscriptions
                let subscriptionRecord: any[] = [];
                if (userId) {
                  subscriptionRecord = await db
                    .insert(donorSubscriptions)
                    .values({
                      userId,
                      stripeSubscriptionId: subscriptionId,
                      stripeCustomerId: customerId,
                      status: stripeSubscription.status,
                      planPriceId: stripeSubscription.items.data[0]?.price?.id || "price_custom",
                      planName: tier.toLowerCase(),
                      currentPeriodStart: stripeSubscription.current_period_start,
                      currentPeriodEnd: stripeSubscription.current_period_end,
                      cancelAt: stripeSubscription.cancel_at || null,
                      canceledAt: stripeSubscription.canceled_at || null,
                      createdAt: new Date(),
                      updatedAt: new Date(),
                    })
                    .returning();
                }

                console.log(
                  `✅ [WEBHOOK] Registro criado em donorSubscriptions: ${subscriptionRecord[0]?.id}`
                );

                // billingEvents
                if (subscriptionRecord.length > 0 && userId) {
                  await db.insert(billingEvents).values({
                    userId,
                    subscriptionId: subscriptionRecord[0].id,
                    stripeSubscriptionId: subscriptionId,
                    eventType: "checkout.session.completed",
                    status: "active",
                    payloadSummary: {
                      tier,
                      amountMonthly,
                      intervalMonths,
                      customerEmail,
                      customerName,
                      checkoutSessionId: session.id,
                    },
                    processed: true,
                  });

                  console.log(`✅ [WEBHOOK] Evento de billing registrado`);
                }

                // doadores (compat antigo)
                if (userId) {
                  const existingDoador = await db
                    .select()
                    .from(doadores)
                    .where(eq(doadores.userId, userId))
                    .limit(1);

                  if (existingDoador.length === 0) {
                    await db.insert(doadores).values({
                      userId,
                      plano: tier,
                      valor: amountMonthly.toString(),
                      stripeSubscriptionId: subscriptionId,
                      status: "paid",
                      dataDoacaoInicial: new Date(),
                      ativo: true,
                    });

                    console.log(`✅ [WEBHOOK] Registro criado em doadores`);
                  } else {
                    await db
                      .update(doadores)
                      .set({
                        plano: tier,
                        valor: amountMonthly.toString(),
                        stripeSubscriptionId: subscriptionId,
                        status: "paid",
                        ultimaDoacao: new Date(),
                        ativo: true,
                      })
                      .where(eq(doadores.id, existingDoador[0].id));

                    console.log(`✅ [WEBHOOK] Doador atualizado: ${existingDoador[0].id}`);
                  }

                  // Sincronizar com Dinamize no checkout (garante envio mesmo se invoice chegar antes da URL estar configurada)
                  try {
                    const doadorParaSync = await db
                      .select({ id: doadores.id, plano: doadores.plano, valor: doadores.valor, dataDoacaoInicial: doadores.dataDoacaoInicial, stripeCustomerId: doadores.stripeCustomerId })
                      .from(doadores).where(eq(doadores.userId, userId)).limit(1).then(r => r[0]);
                    const userParaSync = existingUser[0];
                    if (doadorParaSync && userParaSync) {
                      await enviarDoadorParaDinamize({
                        id: doadorParaSync.id,
                        userId,
                        email: userParaSync.email ?? null,
                        nome: userParaSync.nome ?? null,
                        telefone: userParaSync.telefone ?? null,
                        status: 'paid',
                        plano: doadorParaSync.plano,
                        valor: doadorParaSync.valor,
                        dataDoacaoInicial: doadorParaSync.dataDoacaoInicial ?? null,
                        stripeCustomerId: customerId,
                        syncIntent: 'billing',
                      });
                    }
                  } catch (dinamizeErr: any) {
                    console.error('[DINAMIZE] Erro ao sincronizar checkout.session.completed:', dinamizeErr?.message);
                    try { const fa = (app as any)._fireTechnicalAlert; if (fa) fa("dinamize_sync_falhou", dinamizeErr, { integracao: "Dinamize", origem: "webhook/checkout.session.completed", severidade: "media" }); } catch { }
                  }
                }
              } catch (error) {
                console.error("❌ [WEBHOOK] Erro ao processar subscription personalizada:", error);
              }

              break;
            }

            // Assinatura normal (fluxo antigo)
            console.log("Customer ID:", retrievedSession.customer);
            console.log("Subscription ID:", retrievedSession.subscription);
            console.log("Plan ID:", retrievedSession.metadata?.planId);

            if (
              retrievedSession.metadata?.planId &&
              retrievedSession.customer &&
              retrievedSession.subscription
            ) {
              console.log("Atualizando dados do Stripe para o usuário...");
            }
          } catch (error) {
            console.error("Error processing checkout session:", error);
          }

          break;
        }

        // =====================================================
        // INVOICE PAYMENT SUCCEEDED (AUTO-CREATE USER/DOADOR)
        // =====================================================
        case "invoice.payment_succeeded": {
          const successInvoice = event.data.object as Stripe.Invoice;

          if (!successInvoice.customer) {
            console.log("⚠️ [WEBHOOK] invoice.payment_succeeded sem customer");
            break;
          }

          let user = await db
            .select()
            .from(users)
            .where(eq(users.stripeCustomerId, successInvoice.customer as string))
            .limit(1);

          const isNewDonor = !user[0];
          if (!user[0]) {
            console.log(
              `🆕 [WEBHOOK-AUTO-CREATE] Customer ${successInvoice.customer} não encontrado - criando automaticamente...`
            );

            try {
              const stripeCustomer = await stripe.customers.retrieve(successInvoice.customer as string);

              if (!stripeCustomer.deleted) {
                const subscription = successInvoice.subscription
                  ? await stripe.subscriptions.retrieve(successInvoice.subscription as string)
                  : null;

                const unitAmount = subscription?.items.data[0]?.price?.unit_amount || 0;

                let planName = "eco";
                let planValue = 9.9;

                if (unitAmount === 990) {
                  planName = "eco";
                  planValue = 9.9;
                } else if (unitAmount === 1990) {
                  planName = "voz";
                  planValue = 19.9;
                } else if (unitAmount === 8970) {
                  planName = "grito";
                  planValue = 89.7;
                } else if (unitAmount === 10000) {
                  planName = "platinum";
                  planValue = 100.0;
                }

                const newUser = await db
                  .insert(users)
                  .values({
                    nome: stripeCustomer.name || "Doador",
                    telefone: stripeCustomer.phone || "+5500000000000",
                    email: stripeCustomer.email || "temp@temp.com",
                    plano: planName,
                    role: "doador",
                    stripeCustomerId: successInvoice.customer as string,
                    stripeSubscriptionId: subscription?.id || null,
                    subscriptionStatus: subscription?.status || "active",
                    verificado: true,
                    ativo: true,
                    gritosTotal: 50,
                    nivelAtual: "Aliado do Grito",
                    tipo: "doador",
                    fonte: "doacao",
                  })
                  .returning();

                // ✅ evitar duplicação doador
                const existingDoador = await findExistingDonor({
                  subscriptionId: subscription?.id,
                  customerId: successInvoice.customer as string,
                });

                if (existingDoador) {
                  const interval = subscription?.items.data[0]?.price?.recurring?.interval || "month";
                  const periodicidade =
                    interval === "year" ? "anual" : interval === "month" ? "mensal" : "semestral";

                  await db
                    .update(doadores)
                    .set({
                      plano: planName,
                      valor: planValue,
                      periodicidade,
                      status: "paid",
                      ultimaDoacao: new Date(successInvoice.created * 1000),
                      userId: newUser[0].id,
                      ativo: true,
                    })
                    .where(eq(doadores.id, existingDoador.id));

                  console.log(
                    `♻️ [WEBHOOK-AUTO-CREATE] Doador existente atualizado e vinculado ao user ${newUser[0].id}`
                  );
                } else {
                  await db.insert(doadores).values({
                    userId: newUser[0].id,
                    plano: planName,
                    valor: planValue,
                    status: "paid",
                    ativo: true,
                    stripeCustomerId: successInvoice.customer as string,
                    stripeSubscriptionId: subscription?.id || null,
                    dataDoacaoInicial: new Date(successInvoice.created * 1000),
                    ultimaDoacao: new Date(successInvoice.created * 1000),
                  });
                }

                console.log(
                  `✅ [WEBHOOK-AUTO-CREATE] Usuário criado: ${newUser[0].nome} (ID: ${newUser[0].id}) - Plano: ${planName} - 50 Gritos creditados`
                );

                // 🔗 Criar link de marketing
                try {
                  const linkSlug = newUser[0].nome
                    .toLowerCase()
                    .normalize("NFD")
                    .replace(/[̀-ͯ]/g, "")
                    .replace(/[^a-z0-9\s-]/g, "")
                    .trim()
                    .replace(/\s+/g, "-");

                  const linkCode = `${linkSlug}-${newUser[0].id}`;

                  await db.insert(marketingLinks).values({
                    campaignId: 1,
                    code: linkCode,
                    medium: "marketing",
                    source: "dev-marketing",
                    utmSource: "marketing",
                    utmMedium: "marketing",
                    utmCampaign: "Indique e Ganhe - IV ENCONTRO DO GRITO",
                    rewardToUserId: newUser[0].id,
                    metadata: { targetUrl: "/" },
                    isActive: true,
                  });

                  console.log(`🔗 [WEBHOOK-AUTO-CREATE] Link de marketing criado: ${linkCode}`);
                } catch (linkError) {
                  console.error("⚠️ [WEBHOOK-AUTO-CREATE] Erro ao criar link de marketing:", linkError);
                }

                user = newUser;
              }
            } catch (createError) {
              console.error("❌ [WEBHOOK-AUTO-CREATE] Erro ao criar usuário:", createError);
            }
          }

          // indicação + marca evento
          if (user[0]) {
            try {
              const jaProcessado = await storage.isStripeEventProcessed(event.id);

              if (!jaProcessado) {
                const indicacao = await storage.getIndicacaoByIndicado(user[0].id);

                if (indicacao && indicacao.status === "PENDENTE") {
                  const agora = new Date();
                  const validade = new Date(indicacao.validade);
                  let podeConfirmar = true;

                  if (agora <= validade) {
                    const marketingLink = await storage.getMarketingLinkByCode(indicacao.refCode);

                    if (marketingLink) {
                      if (!marketingLink.isActive) podeConfirmar = false;
                      if (marketingLink.expiresAt && new Date(marketingLink.expiresAt) < agora)
                        podeConfirmar = false;

                      if (marketingLink.maxConversions !== null && marketingLink.maxConversions > 0) {
                        const stats = await storage.getMarketingLinkStats(marketingLink.id);
                        if (stats.conversoes >= marketingLink.maxConversions) podeConfirmar = false;
                      }
                    }

                    if (podeConfirmar) {
                      await storage.confirmarIndicacao(indicacao.id);
                      console.log(
                        `✅ [WEBHOOK-INDICAÇÃO] Indicação ${indicacao.id} confirmada - ${indicacao.indicouId} ganhou 1 ponto!`
                      );
                    }
                  }
                }

                try {
                  await storage.linkUserToActiveCampaign(user[0].id);
                } catch (linkError) {
                  console.error(
                    `⚠️ [WEBHOOK-AUTO-LINK] Erro ao vincular usuário ${user[0].id} à campanha:`,
                    linkError
                  );
                }

                await storage.markStripeEventProcessed(event.id, event.type);
              }
            } catch (error) {
              console.error(`❌ [WEBHOOK-INDICAÇÃO] Erro ao processar indicação para usuário ${user[0].id}:`, error);
            }
          }

          // Atualizar ultima_doacao para doadores existentes a cada cobrança
          if (user && user[0]) {
            try {
              await db
                .update(doadores)
                .set({ ultimaDoacao: new Date(successInvoice.created * 1000) })
                .where(eq(doadores.userId, user[0].id));
              console.log(`✅ [WEBHOOK] ultima_doacao atualizada para user ${user[0].id}: ${new Date(successInvoice.created * 1000).toISOString()}`);
            } catch (updateErr: any) {
              console.error('[WEBHOOK] Erro ao atualizar ultima_doacao:', updateErr?.message);
            }
          }

          // Sincronizar com Dinamize após invoice.payment_succeeded
          if (user && user[0]) {
            try {
              // Anti-duplicata: pula se este event.id já foi processado
              const dinamizeJaProcessado = await storage.isStripeEventProcessed(event.id);
              if (dinamizeJaProcessado) {
                console.log(`[DINAMIZE] ⚠️ Evento ${event.id} já processado — sync ignorado para evitar duplicata`);
              } else {
                const stripeCustomerIdInvoice = successInvoice.customer as string;
                const stripeSubscriptionIdInvoice = successInvoice.subscription as string | null;

                // Determinar tipo de evento: primeiro pagamento ou renovação mensal
                const billingReason = (successInvoice as any).billing_reason as string | null;
                const tipoEvento = billingReason === 'subscription_create' ? 'primeiro_pagamento' : 'pagamento_mensal';
                const dataPagamentoAtual = new Date(successInvoice.created * 1000).toISOString().slice(0, 10);

                // Busca robusta: por userId OU stripeCustomerId OU stripeSubscriptionId
                const doadorRow = await db
                  .select({ id: doadores.id, plano: doadores.plano, valor: doadores.valor, dataDoacaoInicial: doadores.dataDoacaoInicial, stripeCustomerId: doadores.stripeCustomerId })
                  .from(doadores)
                  .where(
                    or(
                      eq(doadores.userId, user[0].id),
                      eq(doadores.stripeCustomerId, stripeCustomerIdInvoice),
                      ...(stripeSubscriptionIdInvoice ? [eq(doadores.stripeSubscriptionId, stripeSubscriptionIdInvoice)] : [])
                    )
                  )
                  .limit(1)
                  .then(r => r[0]);

                if (doadorRow) {
                  console.log(`[DINAMIZE] Enviando doador ${doadorRow.id} (${user[0].email}) via invoice.payment_succeeded — tipo: ${tipoEvento}, data: ${dataPagamentoAtual}...`);
                  await enviarDoadorParaDinamize({
                    id: doadorRow.id,
                    userId: user[0].id,
                    email: user[0].email ?? null,
                    nome: user[0].nome ?? null,
                    telefone: user[0].telefone ?? null,
                    status: 'paid',
                    plano: doadorRow.plano,
                    valor: doadorRow.valor,
                    dataDoacaoInicial: doadorRow.dataDoacaoInicial ?? null,
                    stripeCustomerId: stripeCustomerIdInvoice,
                    tipoEvento,
                    dataPagamentoAtual,
                    syncIntent: 'billing',
                  });
                } else {
                  console.warn(`[DINAMIZE] ⚠️ Doador não encontrado para user ${user[0].id} / customer ${stripeCustomerIdInvoice} — sync ignorado`);
                }
              }
            } catch (dinamizeErr: any) {
              console.error('[DINAMIZE] Erro ao sincronizar invoice.payment_succeeded:', dinamizeErr?.message);
              try { const fa = (app as any)._fireTechnicalAlert; if (fa) fa("dinamize_sync_falhou", dinamizeErr, { integracao: "Dinamize", origem: "webhook/invoice.payment_succeeded", severidade: "media" }); } catch { }
            }
          }

          // Push: doação confirmada
          if (user && user[0]) {
            try {
              const fr = (app as any)._firePushRulesByTrigger;
              if (fr) {
                if (isNewDonor) fr("doador_cadastrado", { nome: user[0].nome || "" }, undefined, user[0].id);
                fr("doacao_confirmada", { nome: user[0].nome || "", plano: user[0].plano || "" }, undefined, user[0].id);
                fr("gritos_doacao_confirmada", { nome: user[0].nome || "" }, undefined, user[0].id);
              }
            } catch { }
          }

          break;
        }



        // =====================================================
        // SUBSCRIPTION UPDATED
        // =====================================================
        case "customer.subscription.updated": {
          const subscription = event.data.object as Stripe.Subscription;
          console.log("Subscription updated:", subscription.id);
          try {
            const stripeCustomerId = subscription.customer as string;

            const userToUpdate = await db
              .select()
              .from(users)
              .where(
                or(
                  eq(users.stripeSubscriptionId, subscription.id),
                  eq(users.stripeCustomerId, stripeCustomerId)
                )
              )
              .limit(1)
              .then((r) => r[0]);

            if (!userToUpdate) {
              console.log(
                `⚠️ [WEBHOOK] Nenhum user encontrado para sub=${subscription.id} customer=${stripeCustomerId}`
              );
              break;
            }

            let planFromStripe = userToUpdate.plano || "eco";
            const priceAmount = subscription.items?.data?.[0]?.price?.unit_amount || 0;

            if (priceAmount) {
              const amountReais = priceAmount / 100;
              if (amountReais > 30) planFromStripe = "platinum";
              else if (amountReais >= 30) planFromStripe = "grito";
              else if (amountReais >= 20) planFromStripe = "voz";
              else if (amountReais >= 10) planFromStripe = "eco";
              else planFromStripe = "eco";
            }

            const paused = !!(subscription as any).pause_collection;
            const activeLike = ["active", "trialing"].includes(subscription.status);
            const shouldBeActive = activeLike && !paused;

            await db.update(users).set({ plano: planFromStripe }).where(eq(users.id, userToUpdate.id));

            const dbSub = await db
              .select()
              .from(donorSubscriptions)
              .where(eq(donorSubscriptions.stripeSubscriptionId, subscription.id))
              .limit(1)
              .then((r) => r[0]);

            if (dbSub) {
              await db
                .update(donorSubscriptions)
                .set({
                  status: subscription.status,
                  currentPeriodStart: subscription.current_period_start,
                  currentPeriodEnd: subscription.current_period_end,
                  cancelAt: subscription.cancel_at,
                  canceledAt: subscription.canceled_at,
                  updatedAt: new Date(),
                })
                .where(eq(donorSubscriptions.id, dbSub.id));

              await db.insert(billingEvents).values({
                userId: userToUpdate.id,
                subscriptionId: dbSub.id,
                stripeSubscriptionId: subscription.id,
                eventType: "customer.subscription.updated",
                status: subscription.status,
                payloadSummary: {
                  status: subscription.status,
                  plan: planFromStripe,
                  paused,
                },
                processed: true,
              });
            }

            await db.insert(billingEvents).values({
              userId: userToUpdate.id,
              subscriptionId: dbSub.id,
              stripeSubscriptionId: subscription.id,
              eventType: "customer.subscription.updated",
              status: subscription.status,
              payloadSummary: {
                status: subscription.status,
                plan: planFromStripe,
                paused,
              },
              processed: true,
            });

            await db
              .update(doadores)
              .set({
                plano: planFromStripe,
                status: shouldBeActive ? "paid" : subscription.status,
                ativo: shouldBeActive,
                stripeCustomerId,
                stripeSubscriptionId: subscription.id,
                ultimaDoacao: shouldBeActive ? new Date() : undefined,
              } as any)
              .where(
                or(
                  eq(doadores.userId, userToUpdate.id),
                  eq(doadores.stripeSubscriptionId, subscription.id),
                  eq(doadores.stripeCustomerId, stripeCustomerId)
                )
              );

            console.log(
              `✅ [WEBHOOK] Usuário ${userToUpdate.id} atualizado - Status: ${subscription.status}, Plano: ${planFromStripe}, Ativo=${shouldBeActive}`
            );

            // Sincronizar com Dinamize
            try {
              await enviarDoadorParaDinamize({
                id: (await db.select({ id: doadores.id }).from(doadores).where(
                  or(eq(doadores.userId, userToUpdate.id), eq(doadores.stripeSubscriptionId, subscription.id), eq(doadores.stripeCustomerId, stripeCustomerId))
                ).limit(1).then(r => r[0]))?.id || 0,
                userId: userToUpdate.id,
                email: userToUpdate.email ?? null,
                nome: userToUpdate.nome ?? null,
                telefone: userToUpdate.telefone ?? null,
                status: shouldBeActive ? 'paid' : subscription.status,
                plano: planFromStripe,
                valor: subscription.items.data[0]?.price?.unit_amount ? subscription.items.data[0].price.unit_amount / 100 : 0,
                dataDoacaoInicial: new Date(subscription.created * 1000),
                stripeCustomerId,
                syncIntent: 'subscription_status',
              });
            } catch (dinamizeErr: any) {
              console.error('[DINAMIZE] Erro ao sincronizar subscription.updated:', dinamizeErr?.message);
              try { const fa = (app as any)._fireTechnicalAlert; if (fa) fa("dinamize_sync_falhou", dinamizeErr, { integracao: "Dinamize", origem: "webhook/subscription.updated", severidade: "media" }); } catch { }
            }
          } catch (error) {
            console.error("Error processing subscription update:", error);
          }

          // Push: plano alterado
          try {
            const fr = (app as any)._firePushRulesByTrigger;
            if (fr) {
              const subUpdated = event.data.object as Stripe.Subscription;
              const uToNotify = await db.select({ id: users.id, nome: users.nome }).from(users).where(or(eq(users.stripeSubscriptionId, subUpdated.id), eq(users.stripeCustomerId, subUpdated.customer as string))).limit(1).then(r => r[0]);
              if (uToNotify) fr("plano_alterado", { nome: uToNotify.nome || "" }, undefined, uToNotify.id);
            }
          } catch { }

          break;
        }

        // =====================================================
        // SUBSCRIPTION DELETED (✅ corrigido: variáveis/escopo/chaves)
        // =====================================================
        case "customer.subscription.deleted": {
          const sub = event.data.object as Stripe.Subscription;
          const customerId = sub.customer as string;

          console.log("Subscription deleted:", sub.id);

          try {
            const userToUpdate = await db
              .select()
              .from(users)
              .where(or(eq(users.stripeSubscriptionId, sub.id), eq(users.stripeCustomerId, customerId)))
              .limit(1)
              .then((r) => r[0]);

            if (!userToUpdate) {
              console.log(`⚠️ [CANCEL] Nenhum user encontrado para sub=${sub.id} customer=${customerId}`);
              break;
            }

            // ✅ Se houver outra assinatura ativa no mesmo customer, NÃO derrubar acesso
            const best = await findBestActiveSubscription(stripe, customerId);

            if (best.ok && best.sub && best.sub.id !== sub.id) {
              console.log(
                `🛡️ [CANCEL] Ignorado: há outra assinatura ativa no customer. ativa=${best.sub.id}`
              );
              break; // <- MUITO IMPORTANTE
            }

            // alinhar donorSubscriptions (se existir)
            const dbSub = await db
              .select()
              .from(donorSubscriptions)
              .where(eq(donorSubscriptions.stripeSubscriptionId, sub.id))
              .limit(1)
              .then((r) => r[0]);

            if (dbSub) {
              await db
                .update(donorSubscriptions)
                .set({
                  status: "canceled",
                  canceledAt: sub.canceled_at || null,
                  updatedAt: new Date(),
                } as any)
                .where(eq(donorSubscriptions.id, dbSub.id));

              await db.insert(billingEvents).values({
                userId: userToUpdate.id,
                subscriptionId: dbSub.id,
                stripeSubscriptionId: sub.id,
                eventType: "customer.subscription.deleted",
                status: "canceled",
                processed: true,
              });
            }

            // user inativo
            await db.update(users).set({ ativo: false } as any).where(eq(users.id, userToUpdate.id));
            console.log(`🔴 [CANCEL] User ${userToUpdate.id} marcado como inativo`);
            try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("usuario_bloqueado", { nome: userToUpdate.nome || userToUpdate.email || String(userToUpdate.id), perfil: userToUpdate.role || userToUpdate.papel || "user", data: new Date().toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" }) }); } catch { }

            // doador inativo/canceled
            await db
              .update(doadores)
              .set({
                ativo: false,
                status: "canceled",
              } as any)
              .where(or(eq(doadores.userId, userToUpdate.id), eq(doadores.stripeCustomerId, customerId)));

            console.log(`🔴 [CANCEL] Doador do user ${userToUpdate.id} marcado como inativo`);

            // Sincronizar com Dinamize
            try {
              await enviarDoadorParaDinamize({
                id: (await db.select({ id: doadores.id }).from(doadores).where(
                  or(eq(doadores.userId, userToUpdate.id), eq(doadores.stripeCustomerId, customerId))
                ).limit(1).then(r => r[0]))?.id || 0,
                userId: userToUpdate.id,
                email: userToUpdate.email ?? null,
                nome: userToUpdate.nome ?? null,
                telefone: userToUpdate.telefone ?? null,
                status: 'canceled',
                plano: userToUpdate.plano ?? 'eco',
                valor: 0,
                dataDoacaoInicial: null,
                stripeCustomerId: customerId,
                syncIntent: 'subscription_status',
              });
            } catch (dinamizeErr: any) {
              console.error('[DINAMIZE] Erro ao sincronizar subscription.deleted:', dinamizeErr?.message);
              try { const fa = (app as any)._fireTechnicalAlert; if (fa) fa("dinamize_sync_falhou", dinamizeErr, { integracao: "Dinamize", origem: "webhook/subscription.deleted", severidade: "media" }); } catch { }
            }
          } catch (error) {
            console.error("Error processing subscription deletion:", error);
          }

          // Push: assinatura cancelada
          try {
            const fr = (app as any)._firePushRulesByTrigger;
            if (fr) {
              const subDel = event.data.object as Stripe.Subscription;
              const uToCancelNotify = await db.select({ id: users.id, nome: users.nome }).from(users).where(or(eq(users.stripeSubscriptionId, subDel.id), eq(users.stripeCustomerId, subDel.customer as string))).limit(1).then(r => r[0]);
              if (uToCancelNotify) fr("assinatura_cancelada", { nome: uToCancelNotify.nome || "" }, undefined, uToCancelNotify.id);
            }
          } catch { }

          break;
        }

        // =====================================================
        // INVOICE PAYMENT FAILED
        // =====================================================
        case "invoice.payment_failed": {
          const failedInvoice = event.data.object as Stripe.Invoice;
          if (!failedInvoice.customer) break;
          try {
            const failedUser = await db.select({ id: users.id, nome: users.nome }).from(users).where(eq(users.stripeCustomerId, failedInvoice.customer as string)).limit(1).then(r => r[0]);
            if (failedUser) {
              const fr = (app as any)._firePushRulesByTrigger;
              if (fr) fr("doacao_recusada", { nome: failedUser.nome || "" }, undefined, failedUser.id);
            }
          } catch (e: any) {
            console.error("[WEBHOOK] invoice.payment_failed push error:", e?.message);
          }
          break;
        }

        // =====================================================
        // DEFAULT
        // =====================================================
        default:
          console.log(`Unhandled event type ${event.type}`);
          break;
      }

      // ✅ Retornar 200 rapidamente para Stripe
      return res.status(200).json({ received: true, processed: true });
    } catch (err) {
      console.error("❌ [STRIPE WEBHOOK] Error geral:", err);
      try { const fa = (app as any)._fireTechnicalAlert; if (fa) fa("webhook_falhou", err, { integracao: "Stripe", origem: "webhook/stripe-main", endpoint: "/api/webhook/stripe", severidade: "alta" }); } catch { }
      return res.status(500).json({ error: "Internal server error" });
    }
  });


