  // Endpoint para agendar mudança de plano no próximo ciclo de cobrança
  app.post("/api/schedule-plan-change", async (req, res) => {
    try {
      const { subscriptionId, newPlanId, periodicity, userId, customAmount } = req.body;

      if (!subscriptionId || !newPlanId || !userId) {
        return res.status(400).json({ error: "subscriptionId, newPlanId e userId são obrigatórios" });
      }

      const planAmounts: Record<string, Record<string, number>> = {
        eco: { mensal: 990, trimestral: 2970, semestral: 5940, anual: 11880 },
        voz: { mensal: 1990, trimestral: 5970, semestral: 11940, anual: 23880 },
        grito: { mensal: 2990, trimestral: 8970, semestral: 17940, anual: 35880 },
        diamante: { mensal: 10000, trimestral: 30000, semestral: 60000, anual: 120000 },
      };

      const planNames: Record<string, string> = {
        eco: "Plano Eco - Clube do Grito",
        voz: "Plano Voz - Clube do Grito",
        grito: "Plano Grito - Clube do Grito",
        platinum: "Plano Platinum - Clube do Grito",
        diamante: "Plano Diamante - Clube do Grito",
      };

      const intervalMap: Record<string, { interval: "month" | "year"; interval_count: number }> = {
        mensal: { interval: "month", interval_count: 1 },
        trimestral: { interval: "month", interval_count: 3 },
        semestral: { interval: "month", interval_count: 6 },
        anual: { interval: "month", interval_count: 12 },
      };

      const periodoKey = periodicity || "mensal";
      const intervalConfig = intervalMap[periodoKey] || intervalMap.mensal;

      let unitAmount: number;
      if (newPlanId === "platinum") {
        if (!customAmount || customAmount < 1) {
          return res.status(400).json({ error: "customAmount é obrigatório para o plano Platinum" });
        }
        unitAmount = Math.round(customAmount);
      } else {
        const planAmountMap = planAmounts[newPlanId];
        if (!planAmountMap) {
          return res.status(400).json({ error: `Plano inválido: ${newPlanId}` });
        }
        unitAmount = planAmountMap[periodoKey] || planAmountMap.mensal;
      }

      const planName = planNames[newPlanId] || `Plano ${newPlanId}`;

      // Buscar assinatura atual no Stripe
      const subscription = await stripe.subscriptions.retrieve(subscriptionId);
      const currentItem = subscription.items.data[0];
      if (!currentItem) {
        return res.status(400).json({ error: "Assinatura não possui itens válidos" });
      }

      // Buscar produto existente para o novo plano, ou criar um novo
      let productId: string;
      const existingProducts = await stripe.products.list({ active: true, limit: 100 });
      const matchingProduct = existingProducts.data.find(
        (p) => p.name === planName || p.metadata?.planId === newPlanId
      );
      if (matchingProduct) {
        productId = matchingProduct.id;
      } else {
        const newProduct = await stripe.products.create({
          name: planName,
          metadata: { planId: newPlanId },
        });
        productId = newProduct.id;
      }

      // Criar novo preço para o produto do novo plano
      const newPrice = await stripe.prices.create({
        currency: "brl",
        unit_amount: unitAmount,
        recurring: {
          interval: intervalConfig.interval,
          interval_count: intervalConfig.interval_count,
        },
        product: productId,
        metadata: { planId: newPlanId, periodicity: periodoKey },
      });

      // Atualizar assinatura com o novo preço (sem proration imediata)
      const updatedSubscription = await stripe.subscriptions.update(subscriptionId, {
        items: [{ id: currentItem.id, price: newPrice.id }],
        proration_behavior: "none",
        metadata: {
          newPlanId,
          periodicity: periodoKey,
          changedByUserId: String(userId),
          changedAt: new Date().toISOString(),
        },
      });

      // Atualizar plano do usuário no banco de dados
      await db.update(users)
        .set({ plano: newPlanId } as any)
        .where(eq(users.id, Number(userId)));

      // Calcular data efetiva (fim do ciclo atual)
      const effectiveTimestamp = updatedSubscription.current_period_end;
      let changeEffectiveDateFormatted: string;
      if (effectiveTimestamp && typeof effectiveTimestamp === "number" && effectiveTimestamp > 0) {
        const effectiveDate = new Date(effectiveTimestamp * 1000);
        changeEffectiveDateFormatted = effectiveDate.toLocaleDateString("pt-BR", {
          day: "2-digit", month: "long", year: "numeric",
        });
      } else {
        // Fallback: próximo mês
        const nextMonth = new Date();
        nextMonth.setMonth(nextMonth.getMonth() + 1);
        changeEffectiveDateFormatted = nextMonth.toLocaleDateString("pt-BR", {
          day: "2-digit", month: "long", year: "numeric",
        });
      }

      console.log("✅ [SCHEDULE-PLAN-CHANGE] Plano alterado para " + newPlanId + " (userId=" + userId + "), efetivo em " + changeEffectiveDateFormatted);

      res.json({
        success: true,
        newPlanId,
        periodicity: periodoKey,
        changeEffectiveDateFormatted,
        subscriptionId: updatedSubscription.id,
      });
    } catch (error: any) {
      console.error("❌ [SCHEDULE-PLAN-CHANGE] Erro:", error);
      res.status(500).json({
        error: "Erro ao agendar mudança de plano",
        message: error.message,
      });
    }
  });

