  // Register user
  app.post("/api/register", async (req, res) => {
    try {
      const userData = postPaymentRegisterSchema.parse(req.body);

      // Check if this user is coming from a payment flow (has plano)
      const isDoador =
        userData.plano &&
        ["eco", "voz", "grito", "platinum"].includes(userData.plano);

      // 🔗 VERIFICAR REFERRAL: Se tem código de convite na requisição
      let referralData = null;
      if (req.body.referralCode) {
        try {
          const referral = await db
            .select()
            .from(referrals)
            .where(eq(referrals.codigoConvite, req.body.referralCode))
            .limit(1);

          if (referral[0] && referral[0].status === "pendente") {
            // Verificar se não expirou
            if (
              !referral[0].expiradoEm ||
              new Date() <= new Date(referral[0].expiradoEm)
            ) {
              referralData = referral[0];
              console.log(
                `🎯 [REFERRAL] Novo usuário via referral: ${req.body.referralCode} de usuário ${referralData.referrerUserId}`
              );
            } else {
              console.log(
                `⚠️ [REFERRAL] Link expirado: ${req.body.referralCode}`
              );
            }
          }
        } catch (error) {
          console.error("Erro ao verificar referral:", error);
        }
      }

      // CONSOLIDAÇÃO AUTOMÁTICA: Garantir que vire um user na tabela principal
      const { consolidateUser } = await import("./userConsolidation");
      const consolidatedUser = await consolidateUser({
        nome: `${userData.nome} ${userData.sobrenome || ""}`.trim(),
        telefone: userData.telefone,
        email: userData.email,
        tipo: isDoador ? "doador" : "doador", // Always doador for this endpoint
        fonte: referralData ? "referral" : "doacao", // Marcar como referral se veio de convite
        plano: userData.plano || "eco",
      });

      console.log(
        `✅ [CONSOLIDAÇÃO] Usuário registrado: ${consolidatedUser.nome} (${consolidatedUser.telefone}) como ${consolidatedUser.tipo} via ${consolidatedUser.fonte}`
      );
      try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("usuario_cadastrado", { nome: consolidatedUser.nome || "", perfil: consolidatedUser.tipo || "doador", data: new Date().toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" }) }); } catch { }

      // 🔗 SISTEMA DE INDICAÇÃO (novo): ref_code pode vir de user ou marketing_link
      if (req.body.referralCode) {
        try {
          const refCode = req.body.referralCode;

          // Verificar se é um link de marketing
          const marketingLink = await storage.getMarketingLinkByCode(refCode);

          if (marketingLink && marketingLink.isActive) {
            // Link de marketing encontrado
            console.log(
              `🔗 [MARKETING] Cadastro via link de marketing: ${refCode}`
            );

            // Verificar expiração
            const now = new Date();
            if (
              marketingLink.expiresAt &&
              new Date(marketingLink.expiresAt) < now
            ) {
              console.log(`⏰ [MARKETING] Link expirado: ${refCode}`);
            } else {
              // Criar indicação com marketing link
              const indicouId = marketingLink.rewardToUserId || null; // Pode ser NULL
              await storage.createIndicacao(
                indicouId,
                consolidatedUser.id,
                refCode
              );
              console.log(
                `✅ [MARKETING-INDICAÇÃO] Indicação criada: link ${refCode} -> user ${consolidatedUser.id}`
              );
            }
          } else {
            // Não é marketing link, verificar se é ref_slug de usuário
            const indicador = await storage.getUserByRefSlug(refCode);

            if (indicador) {
              // Bloquear autoindicação
              if (indicador.id === consolidatedUser.id) {
                console.log(
                  `⚠️ [INDICAÇÃO] Bloqueada autoindicação: user ${consolidatedUser.id}`
                );
              } else {
                await storage.createIndicacao(
                  indicador.id,
                  consolidatedUser.id,
                  refCode
                );
                console.log(
                  `✅ [INDICAÇÃO] Criada indicação: user ${indicador.id} indicou ${consolidatedUser.id}`
                );
              }
            } else {
              console.log(
                `❌ [INDICAÇÃO] Código de indicação não encontrado: ${refCode}`
              );
            }
          }
        } catch (error) {
          console.error("❌ [INDICAÇÃO] Erro ao processar ref_code:", error);
        }
      }

      // Generate verification code
      const verificationCode = Math.floor(
        100000 + Math.random() * 900000
      ).toString();

      try {
        // Try to send SMS via Twilio
        const client = getTwilioClient();
        await client.messages.create({
          body: `Seu código de verificação do Clube do Grito é: ${verificationCode}`,
          from: process.env.TWILIO_PHONE_NUMBER,
          to: `+55${userData.telefone.replace(/\D/g, "")}`,
        });

        console.log(
          `SMS enviado para ${userData.telefone}: ${verificationCode}`
        );
      } catch (twilioError: any) {
        // If Twilio fails (trial account, unverified number, etc.), log the code for development
        console.log(
          `DESENVOLVIMENTO - Código para ${userData.telefone}: ${verificationCode}`
        );
        console.log("Erro Twilio:", twilioError.message);
      }

      // Store verification code (in production, use a proper cache like Redis)
      verificationCodes.set(userData.telefone, verificationCode);

      // 🎯 PROCESSAR REFERRAL: Se veio de convite, guardar para processar na verificação
      if (referralData) {
        // Armazenar dados do referral para processar quando verificar o código
        verificationCodes.set(
          `referral_${userData.telefone}`,
          JSON.stringify({
            referralId: referralData.id,
            referrerUserId: referralData.referrerUserId,
            missaoId: referralData.missaoId,
            gritosRecompensa: referralData.gritosRecompensa,
          })
        );
        console.log(
          `💾 [REFERRAL] Dados salvos para processar na verificação: ${userData.telefone}`
        );
      }

      res.json({
        userId: consolidatedUser.id,
        message: "Código de verificação enviado via SMS",
        // In development, return the code for testing
        ...(process.env.NODE_ENV === "development" && {
          devCode: verificationCode,
        }),
      });
    } catch (error: any) {
      console.error("Error registering user:", error);
      if (error instanceof z.ZodError) {
        return res
          .status(400)
          .json({ error: "Dados inválidos", details: error.errors });
      }
      res.status(500).json({ error: "Erro ao registrar usuário" });
    }
  });

  app.get("/api/admin/check-all-subscriptions", async (req, res) => {
    try {
      // Buscar todos os doadores com subscriptions
      const doadoresList = await db
        .select({
          id: doadores.id,
          nome: users.nome,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
          stripeCustomerId: doadores.stripeCustomerId,
        })
        .from(doadores)
        .leftJoin(users, eq(doadores.userId, users.id))
        .where(ne(doadores.stripeSubscriptionId, null));

      const results = [];

      for (const doador of doadoresList) {
        if (!doador.stripeSubscriptionId) continue;

        try {
          const subscription = await stripe.subscriptions.retrieve(
            doador.stripeSubscriptionId
          );

          results.push({
            doadorId: doador.id,
            nome: doador.nome,
            stripeSubId: doador.stripeSubscriptionId,
            status: subscription.status,
            currentPeriodStart: new Date(
              subscription.current_period_start * 1000
            ),
            currentPeriodEnd: new Date(subscription.current_period_end * 1000),
            nextBillingDate: new Date(subscription.current_period_end * 1000),
            amount: subscription.items.data[0]?.price?.unit_amount
              ? subscription.items.data[0].price.unit_amount / 100
              : 0,
            interval: subscription.items.data[0]?.price?.recurring?.interval,
            intervalCount:
              subscription.items.data[0]?.price?.recurring?.interval_count,
            cancelAtPeriodEnd: subscription.cancel_at_period_end,
          });
        } catch (error: any) {
          results.push({
            doadorId: doador.id,
            nome: doador.nome,
            stripeSubId: doador.stripeSubscriptionId,
            error: error.message,
          });
        }
      }

      res.json({ total: results.length, subscriptions: results });
    } catch (error: any) {
      console.error("Error checking subscriptions:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post(
    "/api/admin/create-manual-subscription",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { userId, monthlyAmount, intervalMonths } = req.body;

        if (!userId || !monthlyAmount) {
          return res
            .status(400)
            .json({ error: "userId e monthlyAmount são obrigatórios" });
        }

        const interval = intervalMonths || 1;
        if (![1, 3, 6, 12].includes(interval)) {
          return res
            .status(400)
            .json({ error: "intervalMonths deve ser 1, 3, 6 ou 12" });
        }

        const [user] = await db
          .select()
          .from(users)
          .where(eq(users.id, userId))
          .limit(1);
        if (!user) {
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        console.log(
          `🔧 [MANUAL SUB] Criando subscription manual para ${user.nome} (ID: ${userId})`
        );
        console.log(
          `💰 Valor: R$ ${monthlyAmount}/mês | Intervalo: ${interval} meses`
        );

        const [doador] = await db
          .select()
          .from(doadores)
          .where(eq(doadores.userId, userId))
          .orderBy(doadores.dataDoacaoInicial)
          .limit(1);

        if (!doador?.stripePaymentIntentId) {
          return res.status(404).json({
            error:
              "Usuário não tem payment intent registrado. É necessário que ele tenha feito pelo menos um pagamento anteriormente.",
          });
        }

        console.log(
          `🔍 [MANUAL SUB] Payment Intent: ${doador.stripePaymentIntentId}`
        );

        const paymentIntent = await stripe.paymentIntents.retrieve(
          doador.stripePaymentIntentId
        );

        if (!paymentIntent.customer) {
          return res.status(400).json({
            error: "Payment Intent não tem customer associado",
          });
        }

        const customerId =
          typeof paymentIntent.customer === "string"
            ? paymentIntent.customer
            : paymentIntent.customer.id;

        console.log(`✅ [MANUAL SUB] Customer ID: ${customerId}`);

        const customer = await stripe.customers.retrieve(customerId);
        if (customer.deleted) {
          return res
            .status(400)
            .json({ error: "Customer foi deletado no Stripe" });
        }

        const paymentMethods = await stripe.paymentMethods.list({
          customer: customerId,
          type: "card",
        });

        if (paymentMethods.data.length === 0) {
          return res.status(400).json({
            error:
              "Usuário não tem método de pagamento salvo. É necessário que ele adicione um cartão através da página de planos.",
          });
        }

        const defaultPaymentMethod = paymentMethods.data[0].id;
        console.log(`💳 [MANUAL SUB] Payment Method: ${defaultPaymentMethod}`);

        const priceData: Stripe.SubscriptionCreateParams.Item.PriceData = {
          currency: "brl",
          product_data: {
            name: `Contribuição Mensal - ${user.nome}`,
            description: `Assinatura recorrente de R$ ${monthlyAmount.toFixed(
              2
            )} a cada ${interval} ${interval === 1 ? "mês" : "meses"}`,
          },
          unit_amount: Math.round(monthlyAmount * 100),
          recurring: {
            interval: "month",
            interval_count: interval,
          },
        };

        const subscription = await stripe.subscriptions.create({
          customer: customerId,
          items: [{ price_data: priceData }],
          default_payment_method: defaultPaymentMethod,
          metadata: {
            userId: userId.toString(),
            tier:
              monthlyAmount <= 10
                ? "eco"
                : monthlyAmount <= 30
                  ? "bronze"
                  : monthlyAmount <= 60
                    ? "prata"
                    : monthlyAmount <= 100
                      ? "ouro"
                      : "platinum",
            amountMonthly: monthlyAmount.toString(),
            intervalMonths: interval.toString(),
            manuallyCreated: "true",
          },
        });

        console.log(`✅ [MANUAL SUB] Subscription criada: ${subscription.id}`);
        console.log(`📊 Status: ${subscription.status}`);

        await db.update(users)
          .set({
            stripeCustomerId: customerId,
            stripeSubscriptionId: subscription.id
          })
          .where(eq(users.id, userId));

        await db.update(doadores)
          .set({
            stripeCustomerId: customerId,
            stripeSubscriptionId: subscription.id,
            status: subscription.status === 'active' ? 'paid' : 'pending',
            ativo: subscription.status === 'active',
          })
          .where(eq(doadores.id, doador.id));

        await db.insert(donorSubscriptions).values({
          userId,
          stripeCustomerId: customerId,
          stripeSubscriptionId: subscription.id,
          status: subscription.status,
          billingCycleAnchor: subscription.billing_cycle_anchor,
          currentPeriodStart: subscription.current_period_start,
          currentPeriodEnd: subscription.current_period_end,
          planPriceId: subscription.items.data[0].price.id,
          planName: `R$ ${monthlyAmount} / ${interval === 1 ? "mês" : `${interval} meses`
            }`,
          defaultPaymentMethod: defaultPaymentMethod,
        });

        res.json({
          success: true,
          subscription: {
            id: subscription.id,
            status: subscription.status,
            customerId,
            amount: monthlyAmount,
            interval,
            currentPeriodEnd: new Date(subscription.current_period_end * 1000),
            nextBillingDate: new Date(subscription.current_period_end * 1000),
          },
          message: `Subscription criada com sucesso! Próxima cobrança: ${new Date(
            subscription.current_period_end * 1000
          ).toLocaleDateString("pt-BR")}`,
        });
      } catch (error: any) {
        console.error("❌ [MANUAL SUB] Error:", error);
        res.status(500).json({
          error: error.message,
          details: error.raw?.message || error.toString(),
        });
      }
    }
  );

  // Force immediate billing for a subscription
  app.post("/api/admin/force-billing/:doadorId", async (req, res) => {
    try {
      const { doadorId } = req.params;

      // Buscar doador e usuário separadamente (apenas campos que existem)
      const [doador] = await db
        .select({
          id: doadores.id,
          userId: doadores.userId,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
        })
        .from(doadores)
        .where(eq(doadores.id, parseInt(doadorId)))
        .limit(1);

      if (!doador || !doador.stripeSubscriptionId) {
        return res.status(404).json({ error: "Doador sem subscription ID" });
      }

      const [user] = await db
        .select()
        .from(users)
        .where(eq(users.id, doador.userId))
        .limit(1);

      console.log(
        `💳 [FORCE BILLING] Cobrando doador ${user?.nome} (${doador.id})...`
      );

      // Fetch subscription from Stripe to get the correct customer ID and billing info
      const subscription = await stripe.subscriptions.retrieve(
        doador.stripeSubscriptionId
      );
      const correctCustomerId =
        typeof subscription.customer === "string"
          ? subscription.customer
          : subscription.customer.id;

      console.log(
        `🔍 [FORCE BILLING] Customer correto do Stripe: ${correctCustomerId}`
      );
      console.log(
        `🔍 [FORCE BILLING] Status da subscription: ${subscription.status}`
      );

      // Check if subscription is active
      if (subscription.status !== "active") {
        return res.status(400).json({
          error: `Subscription está ${subscription.status}, não pode ser cobrada.`,
          status: subscription.status,
        });
      }

      // Validação de ciclo de cobrança
      const currentPeriodEnd = subscription.current_period_end * 1000; // Convert to milliseconds
      const now = Date.now();
      const intervalCount =
        subscription.items.data[0]?.plan.interval_count || 1;
      const interval = subscription.items.data[0]?.plan.interval || "month";

      // Calcular meses do intervalo
      let intervalMonths = intervalCount;
      if (interval === "year") {
        intervalMonths = intervalCount * 12;
      } else if (interval === "month") {
        intervalMonths = intervalCount;
      }

      const cicloNome =
        intervalMonths === 1
          ? "Mensal"
          : intervalMonths === 3
            ? "Trimestral"
            : intervalMonths === 6
              ? "Semestral"
              : intervalMonths === 12
                ? "Anual"
                : `${intervalMonths} meses`;

      console.log(
        `📅 [FORCE BILLING] Ciclo: ${cicloNome} (${intervalMonths} meses)`
      );
      console.log(
        `📅 [FORCE BILLING] Próximo pagamento: ${new Date(
          currentPeriodEnd
        ).toLocaleDateString("pt-BR")}`
      );
      console.log(
        `📅 [FORCE BILLING] Hoje: ${new Date(now).toLocaleDateString("pt-BR")}`
      );

      // Bloquear cobrança antecipada para ciclos maiores que mensal
      if (intervalMonths > 1 && now < currentPeriodEnd) {
        const diasRestantes = Math.ceil(
          (currentPeriodEnd - now) / (1000 * 60 * 60 * 24)
        );
        return res.status(400).json({
          error: `Cobrança bloqueada: ciclo ${cicloNome} ainda não terminou.`,
          ciclo: cicloNome,
          proximoPagamento: new Date(currentPeriodEnd).toLocaleDateString(
            "pt-BR"
          ),
          diasRestantes: diasRestantes,
          mensagem: `Só é possível cobrar após ${new Date(
            currentPeriodEnd
          ).toLocaleDateString("pt-BR")} (faltam ${diasRestantes} dias)`,
        });
      }

      // Create an invoice for the subscription and charge immediately
      const invoice = await stripe.invoices.create({
        customer: correctCustomerId,
        subscription: doador.stripeSubscriptionId,
        auto_advance: true, // Automatically finalize and pay
      });

      console.log(`📄 [FORCE BILLING] Invoice criada: ${invoice.id}`);

      const paidInvoice = await stripe.invoices.pay(invoice.id);

      console.log(`✅ [FORCE BILLING] Invoice paga: ${paidInvoice.status}`);

      res.json({
        success: true,
        doadorId: doador.id,
        nome: user?.nome,
        ciclo: cicloNome,
        invoiceId: paidInvoice.id,
        amount: paidInvoice.amount_paid ? paidInvoice.amount_paid / 100 : 0,
        status: paidInvoice.status,
      });
    } catch (error: any) {
      console.error("❌ [FORCE BILLING] Erro:", error);
      res
        .status(500)
        .json({ error: error.message, details: error.raw?.message });
    }
  });

