  // Get user by ID (com /users/:id) - ENDPOINT para change-plan
  // Retorna dados completos incluindo valor personalizado e periodicidade
  app.get("/api/users/:id", async (req, res) => {

    try {
      const userId = parseInt(req.params.id);
      console.log(`📥 [GET /api/users/${userId}] Iniciando busca...`);

      // Buscar usuário do Digital Ocean (banco principal)
      const userResult = await pool.query(
        `SELECT id, nome, sobrenome, telefone, email, plano, foto_perfil, role, verificado, ativo,
                stripe_customer_id, stripe_subscription_id, subscription_status, gritos_total,
                nivel_atual, dias_consecutivos, ultimo_checkin
         FROM users WHERE id = $1`,
        [userId]
      );

      if (!userResult.rows[0]) {
        console.log(
          `❌ [GET /api/users/${userId}] Usuário não encontrado no Digital Ocean`
        );
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      const userRow = userResult.rows[0];
      const user = {
        id: userRow.id,
        nome: userRow.nome,
        sobrenome: userRow.sobrenome,
        telefone: userRow.telefone,
        email: userRow.email,
        plano: userRow.plano,
        fotoPerfil: userRow.foto_perfil,
        role: userRow.role,
        verificado: userRow.verificado,
        ativo: userRow.ativo,
        stripeCustomerId: userRow.stripe_customer_id,
        stripeSubscriptionId: userRow.stripe_subscription_id,
        subscriptionStatus: userRow.subscription_status,
        gritosTotal: userRow.gritos_total,
        nivelAtual: userRow.nivel_atual,
        diasConsecutivos: userRow.dias_consecutivos,
        ultimoCheckin: userRow.ultimo_checkin,
      };

      console.log(`✅ [GET /api/users/${userId}] Usuário encontrado (DO):`, {
        id: user.id,
        nome: user.nome,
        plano: user.plano,
        stripeCustomerId: user.stripeCustomerId,
        stripeSubscriptionId: user.stripeSubscriptionId,
      });

      // Buscar dados de doação para obter valor personalizado
      let doadorData = null;
      let hasActiveSubscription = false;

      try {
        const doadorQuery = await db
          .select()
          .from(doadores)
          .where(eq(doadores.userId, userId))
          .orderBy(desc(doadores.ativo), desc(doadores.createdAt))
          .limit(1);

        doadorData = doadorQuery[0] || null;

        hasActiveSubscription =
          !!(
            user.subscriptionStatus &&
            ["active", "trialing"].includes(String(user.subscriptionStatus))
          ) ||
          !!(
            doadorData &&
            doadorData.ativo === true &&
            ["paid", "active", "trialing"].includes(String(doadorData.status))
          );

        console.log(`💰 [GET /api/users/${userId}] Dados de doação:`, {
          encontrado: !!doadorData,
          valor: doadorData?.valor,
          plano: doadorData?.plano,
          stripeSubscriptionId: doadorData?.stripeSubscriptionId,
        });
      } catch (dbError: any) {
        console.error(
          `❌ [GET /api/users/${userId}] Erro ao buscar doador:`,
          dbError.message
        );
      }

      // Preparar resposta
      const response = {
        id: user.id,
        nome: user.nome,
        sobrenome: user.sobrenome || "",
        telefone: user.telefone,
        email: user.email || null,
        plano: user.plano,
        fotoPerfil: user.fotoPerfil || null,
        role: user.role || "user",
        isVerified: user.verificado || false,
        valorPersonalizado: doadorData?.valor || null,
        periodoDoacao: "mensal", // Por padrão é mensal (custom subscriptions são sempre mensais)
        // PRIORIZAR subscription da tabela users (mais atualizada)
        stripeSubscriptionId:
          user.stripeSubscriptionId || doadorData?.stripeSubscriptionId || null,
        stripeCustomerId: user.stripeCustomerId || null,
        hasActiveSubscription,
        subscriptionStatus:
          user.subscriptionStatus || doadorData?.status || null
      };

      console.log(`📤 [GET /api/users/${userId}] Resposta:`, {
        plano: response.plano,
        valorPersonalizado: response.valorPersonalizado,
        periodoDoacao: response.periodoDoacacao,
        stripeSubscriptionId: response.stripeSubscriptionId,
      });

      res.json(response);
    } catch (error: any) {
      const idParam = req.params.id;
      console.error(`❌ [GET /api/users/${idParam}] ERRO CRÍTICO:`, {
        message: error.message,
        stack: error.stack,
      });
      res
        .status(500)
        .json({ error: "Erro ao buscar usuário", details: error.message });
    }
  });

