  // 🔄 MIGRATE: Migrar doadores antigos para assinaturas recorrentes
  app.post(
    "/api/admin/migrate-donors",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        console.log(
          "🔄 [MIGRATE] Iniciando migração de doadores para assinaturas recorrentes..."
        );

        if (!stripe) {
          return res.status(500).json({ error: "Stripe não configurado" });
        }

        // Buscar todos os doadores sem subscription_id mas com plano
        const doadoresSemSubscription = await db
          .select()
          .from(doadores)
          .where(
            and(
              isNull(doadores.stripeSubscriptionId),
              isNotNull(doadores.plano),
              eq(doadores.status, "paid")
            )
          );

        console.log(
          `🔍 [MIGRATE] Encontrados ${doadoresSemSubscription.length} doadores sem subscription`
        );

        const results = {
          total: doadoresSemSubscription.length,
          migrated: 0,
          errors: 0,
          skipped: 0,
          details: [] as any[],
        };

        for (const doador of doadoresSemSubscription) {
          try {
            console.log(`\n🔍 [MIGRATE] Processando doador ID ${doador.id}...`);

            // 1. Buscar customer_id pelo payment_intent
            let customerId: string | null = null;

            if (doador.stripePaymentIntentId) {
              console.log(
                `   Buscando payment intent: ${doador.stripePaymentIntentId}`
              );
              const paymentIntent = await stripe.paymentIntents.retrieve(
                doador.stripePaymentIntentId
              );

              if (paymentIntent.customer) {
                customerId =
                  typeof paymentIntent.customer === "string"
                    ? paymentIntent.customer
                    : paymentIntent.customer.id;
                console.log(`   ✅ Customer ID encontrado: ${customerId}`);
              }
            }

            // Se não tem customer_id, não pode criar subscription
            if (!customerId) {
              console.log(
                `   ⚠️ Sem customer_id - impossível criar subscription`
              );
              results.skipped++;
              results.details.push({
                doadorId: doador.id,
                plano: doador.plano,
                valor: doador.valor,
                status: "skipped",
                reason: "Sem customer_id no Stripe",
              });
              continue;
            }

            // 2. Verificar se customer tem payment method
            const paymentMethods = await stripe.paymentMethods.list({
              customer: customerId,
              type: "card",
            });

            if (paymentMethods.data.length === 0) {
              console.log(`   ⚠️ Customer ${customerId} sem cartão salvo`);
              results.skipped++;
              results.details.push({
                doadorId: doador.id,
                plano: doador.plano,
                valor: doador.valor,
                customerId: customerId,
                status: "skipped",
                reason: "Sem cartão salvo no Stripe",
              });
              continue;
            }

            const defaultPaymentMethod = paymentMethods.data[0].id;
            console.log(
              `   ✅ Payment method encontrado: ${defaultPaymentMethod}`
            );

            // 3. Mapear periodicidade para interval do Stripe
            let interval: "month" | "year" = "month";
            let intervalCount = 1;

            // Usar periodicidade do banco ou padrão 'mensal'
            const periodicidade = (
              doador.periodicidade || "mensal"
            ).toLowerCase();

            if (
              periodicidade.includes("ano") ||
              periodicidade.includes("anual")
            ) {
              interval = "year";
              intervalCount = 1;
            } else if (periodicidade.includes("semest")) {
              interval = "month";
              intervalCount = 6;
            } else if (periodicidade.includes("trimest")) {
              interval = "month";
              intervalCount = 3;
            } else {
              // mensal (padrão)
              interval = "month";
              intervalCount = 1;
            }

            console.log(
              `   📅 Periodicidade: ${periodicidade} → ${intervalCount} ${interval}`
            );

            // 4. Criar produto e preço no Stripe
            const valorCentavos = Math.round(
              parseFloat(doador.valor.toString()) * 100
            );

            const product = await stripe.products.create({
              name: `Plano ${doador.plano.toUpperCase()} - Migrado`,
              description: `Assinatura ${periodoNormalizado} do plano ${doador.plano}`,
            });

            console.log(`   ✅ Produto criado: ${product.id}`);

            const price = await stripe.prices.create({
              currency: "brl",
              unit_amount: valorCentavos,
              recurring: {
                interval: interval,
                interval_count: intervalCount,
              },
              product: product.id,
            });

            console.log(
              `   ✅ Preço criado: ${price.id} (R$ ${(
                valorCentavos / 100
              ).toFixed(2)})`
            );

            // 5. Criar subscription no Stripe
            const subscription = await stripe.subscriptions.create({
              customer: customerId,
              items: [{ price: price.id }],
              default_payment_method: defaultPaymentMethod,
              metadata: {
                doador_id: doador.id.toString(),
                migrated_from: "one_time_payment",
                migration_date: new Date().toISOString(),
              },
            });

            console.log(`   ✅ Subscription criada: ${subscription.id}`);

            // 6. Atualizar banco de dados
            await db.update(doadores)
              .set({
                stripeSubscriptionId: subscription.id,
                stripeCustomerId: customerId,
                updatedAt: new Date(),
              })
              .where(eq(doadores.id, doador.id));

            console.log(`   ✅ Banco atualizado para doador ID ${doador.id}`);

            results.migrated++;
            results.details.push({
              doadorId: doador.id,
              plano: doador.plano,
              valor: doador.valor,
              customerId: customerId,
              subscriptionId: subscription.id,
              periodicidade: `${intervalCount} ${interval}`,
              status: "success",
            });
          } catch (error: any) {
            results.errors++;
            console.error(
              `   ❌ Erro ao processar doador ${doador.id}:`,
              error.message
            );
            results.details.push({
              doadorId: doador.id,
              plano: doador.plano,
              valor: doador.valor,
              status: "error",
              error: error.message,
            });
          }
        }

        console.log(`\n✅ [MIGRATE] Migração concluída:`);
        console.log(`   Total processados: ${results.total}`);
        console.log(`   ✅ Migrados: ${results.migrated}`);
        console.log(`   ⚠️ Pulados: ${results.skipped}`);
        console.log(`   ❌ Erros: ${results.errors}`);

        res.json(results);
      } catch (error: any) {
        console.error("❌ [MIGRATE] Erro na migração:", error);
        res
          .status(500)
          .json({ error: "Erro ao migrar doadores: " + error.message });
      }
    }
  );

  // ✅ NOVO: Endpoint para estatísticas do usuário (gritos, níveis, etc.)
  app.get("/api/users/:id/stats", async (req, res) => {
    try {
      const userId = parseInt(req.params.id);
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Calcular gritos baseado nas doações realizadas e bonificações
      let gritos = user.gritos || 0; // Valor base do banco

      // Adicionar gritos por doações recorrentes mensais
      const currentPlan = await storage.getUserActiveDonationPlan(userId);

      let monthlyGritos = 0;
      if (currentPlan === "platinum") {
        // Para Platinum: buscar valor real e multiplicar por 3
        const platinumDonation = await db
          .select({
            valor: doadores.valor,
          })
          .from(doadores)
          .where(
            and(
              eq(doadores.userId, userId),
              eq(doadores.plano, "platinum"),
              eq(doadores.status, "paid")
            )
          )
          .orderBy(desc(doadores.createdAt))
          .limit(1);

        if (platinumDonation.length > 0) {
          const valorDoacao = parseFloat(platinumDonation[0].valor);
          monthlyGritos = Math.round(valorDoacao * 3);
        } else {
          monthlyGritos = 93; // Mínimo R$ 31 x 3
        }
      } else {
        // Planos fixos: valor x 3
        const planMultipliers: Record<string, number> = {
          eco: 30, // R$ 10 x 3
          voz: 60, // R$ 20 x 3
          grito: 90, // R$ 30 x 3
        };
        monthlyGritos =
          planMultipliers[currentPlan as keyof typeof planMultipliers] || 30;
      }

      // Se tem plano ativo, assumir que acumula gritos mensalmente
      if (currentPlan && monthlyGritos > 0) {
        gritos = Math.max(gritos, monthlyGritos);
      }

      // Determinar níveis baseado nos gritos
      const niveis = [
        { nome: "Aliado do Grito", gritos: 0, proximo: "Eco do Bem" },
        { nome: "Eco do Bem", gritos: 300, proximo: "Voz Ativa" },
        { nome: "Voz Ativa", gritos: 600, proximo: "Transformador" },
        { nome: "Transformador", gritos: 1000, proximo: "Guerreiro do Grito" },
        { nome: "Guerreiro do Grito", gritos: 1500, proximo: "Máximo" },
      ];

      let nivel_atual = niveis[0];
      let proximo_nivel = niveis[1]?.nome || "Máximo";
      let gritos_proximo_nivel = niveis[1]?.gritos || 300;

      for (let i = 0; i < niveis.length; i++) {
        if (gritos >= niveis[i].gritos) {
          nivel_atual = niveis[i];
          proximo_nivel = niveis[i + 1]?.nome || "Máximo";
          gritos_proximo_nivel = niveis[i + 1]?.gritos || niveis[i].gritos;
        }
      }

      const stats = {
        gritos,
        nivel_atual: nivel_atual.nome,
        proximo_nivel,
        gritos_proximo_nivel,
        plano_atual: currentPlan || "eco",
      };

      res.json(stats);
    } catch (error: any) {
      console.error("Error fetching user stats:", error);
      res.status(500).json({
        error: "Erro ao buscar estatísticas do usuário: " + error.message,
      });
    }
  });

  // Update user data (PUT)
  app.put("/api/users/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const { nome, telefone, email, plano, tipo, conselhoStatus } = req.body;

      if (!nome && !telefone && !email && !plano && !tipo && conselhoStatus === undefined) {
        return res.status(400).json({ error: "Pelo menos um campo deve ser fornecido" });
      }

      const existingUser = await storage.getUser(parseInt(id));
      if (!existingUser) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      const updateData: any = {};
      if (nome) updateData.nome = nome;
      if (telefone) updateData.telefone = telefone;
      if (email) updateData.email = email;
      if (plano) updateData.plano = plano;
      if (tipo) updateData.tipo = tipo;
      if (conselhoStatus !== undefined) updateData.conselhoStatus = conselhoStatus;

      const updatedUser = await storage.updateUser(parseInt(id), updateData);

      // Verificar automaticamente se perfil está completo e completar missão
      await storage.checkAndCompleteProfileMission(parseInt(id));

      console.log(`✅ Dados atualizados para usuário ${id}:`, updateData);

      // alteracao_sensivel + permissao_alterada — só dispara quando tipo/papel for alterado
      if (tipo) {
        try {
          const fr = (app as any)._firePushRulesByTrigger;
          if (fr) {
            fr("alteracao_sensivel", {
              nome: existingUser.nome || String(id),
              campo: "tipo/papel",
              valor_novo: tipo,
              alterado_por: String((req as any).user?.id || "admin"),
              data: new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" }),
            });
            const adminUser = (req as any).user;
            const adminNome = adminUser?.nome || adminUser?.name || `ID ${adminUser?.id || "admin"}`;
            fr("permissao_alterada", {
              admin: adminNome,
              usuario: existingUser.nome || String(id),
              papel_anterior: existingUser.tipo || existingUser.papel || existingUser.role || "sem papel",
              papel_novo: tipo,
              data: new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" }),
            });
          }
        } catch { }
      }

      res.json(updatedUser);
    } catch (error: any) {
      console.error("Error updating user:", error);
      res
        .status(500)
        .json({ error: "Erro ao atualizar usuário: " + error.message });
    }
  });

