  // Record attendance for students in a lesson
  app.post("/api/professor/attendance", async (req, res) => {
    try {
      const { attendanceRecords } = req.body;

      if (!attendanceRecords || !Array.isArray(attendanceRecords)) {
        return res
          .status(400)
          .json({ error: "Registros de chamada são obrigatórios" });
      }

      const chamadaGroups: { [key: string]: any } = {};
      for (const record of attendanceRecords) {
        const key = `${record.classId}-${record.date}`;
        if (!chamadaGroups[key]) {
          chamadaGroups[key] = {
            turmaId: record.classId,
            data: record.date,
            professorId: record.professorId,
            records: [],
          };
        }
        chamadaGroups[key].records.push(record);
      }

      const results = [];

      for (const group of Object.values(chamadaGroups) as any[]) {
        const existingChamadas = await db.select().from(chamada)
          .where(and(
            eq(chamada.turmaId, group.turmaId),
            eq(chamada.data, group.data)
          ))
          .limit(1);

        let chamadaRecord;
        if (existingChamadas.length > 0) {
          chamadaRecord = existingChamadas[0];
          await db.delete(chamadaAluno).where(eq(chamadaAluno.chamadaId, chamadaRecord.id));
        } else {
          chamadaRecord = await storage.createChamada({
            turmaId: group.turmaId,
            data: group.data,
            professorId: group.professorId,
          });
          try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("chamada_aberta", { turma: String(group.turmaId), data: group.data || "" }, undefined, undefined, undefined, { vertente: "pec" }); } catch { }
        }

        for (const record of group.records) {
          const chamadaAlunoRecord = await storage.createChamadaAluno({
            chamadaId: chamadaRecord.id,
            alunoCpf: record.studentCpf,
            status: record.status,
            justificativa: record.justificativa || '',
          });
          results.push(chamadaAlunoRecord);
          // Push por aluno (CPF canônico em fcm_tokens)
          try {
            const fr = (app as any)._firePushRulesByTrigger;
            const alunoTarget = fr && record.studentCpf ? resolveAlunoPushTarget({ studentCpf: record.studentCpf }) : null;
            if (alunoTarget) {
              const turmaVar = { turma: group.turmaId ? String(group.turmaId) : "" };
              const cpfKey = alunoTarget.targetUserKey;
              if (record.status === 'presente') {
                fr("presenca_confirmada_aluno", turmaVar, undefined, undefined, cpfKey);
              } else {
                fr("falta_registrada_aluno", turmaVar, undefined, undefined, cpfKey);
                if (!record.justificativa && group.turmaId) {
                  const staffKeys = await resolveStaffUserKeysForTurma(pool, "pec", Number(group.turmaId));
                  if (staffKeys.length > 0) {
                    fr("justificativa_pendente", { ...turmaVar, aluno: cpfKey }, undefined, undefined, undefined, {
                      vertente: "pec",
                      targetUserKeys: staffKeys,
                    });
                  }
                }
              }
            }
          } catch { }
        }
      }

      res.json({
        success: true,
        message: `${results.length} registros de presença salvos com sucesso`,
        records: results,
      });
    } catch (error: any) {
      console.error("Error recording attendance:", error);
      res
        .status(500)
        .json({ error: "Erro ao registrar chamada: " + error.message });
    }
  });

