      await db.delete(atividadesMonitor)
        .where(eq(atividadesMonitor.id, atividadeId));

      console.log(`[RBAC MONITOR] Atividade ${atividadeId} excluída por monitor ${user.id}`);
      res.json({ success: true, message: "Atividade excluída com sucesso" });
