  app.post("/api/presencas-inclusao/foto", requireAuth, requireAnyRole(CHAMADA_FOTO_ROLES), photoUpload.array("foto", 10), validateImagesMemoryArray, async (req, res) => {
    try {
      const { turmaId, data } = req.body;
      const files = (req as any).files as Express.Multer.File[];
      console.log(`[FOTO-INCLUSAO] turmaId=${JSON.stringify(turmaId)} data=${JSON.stringify(data)} files=${files?.length}`);
      if (!files || files.length === 0 || !turmaId || !data) {
        return res.status(400).json({ error: "Foto, turmaId e data são obrigatórios" });
      }
      // Upload each file to GCS
      const newUrls: string[] = [];
      for (const file of files) {
        const fileName = `chamadas/foto_inclusao_${turmaId}_${data}_${Date.now()}_${newUrls.length}.${file.originalname.split('.').pop()}`;
        const url = await uploadToGCS(file.buffer, fileName, file.mimetype);
        newUrls.push(url);
      }
      // Append to existing URLs (supports JSON array or legacy single string)
      const turmaIdInt = parseInt(turmaId);
      const dataYMD = String(data).split('T')[0];
      const existing = await db.select({ fotoComprovante: presencasInclusao.fotoComprovante })
        .from(presencasInclusao)
        .where(and(
          eq(presencasInclusao.turmaId, turmaIdInt),
          sql`${presencasInclusao.data} = ${dataYMD}::date`,
          sql`${presencasInclusao.fotoComprovante} IS NOT NULL`
        ))
        .limit(1);
      let existingUrls: string[] = [];
      if (existing[0]?.fotoComprovante) {
        try { existingUrls = JSON.parse(existing[0].fotoComprovante); }
        catch { existingUrls = [existing[0].fotoComprovante]; }
      }
      const allUrls = [...existingUrls, ...newUrls];
      const result = await db.update(presencasInclusao)
        .set({ fotoComprovante: JSON.stringify(allUrls) })
        .where(and(
          eq(presencasInclusao.turmaId, turmaIdInt),
          sql`${presencasInclusao.data} = ${dataYMD}::date`
        ));
      console.log(`[FOTO-INCLUSAO] DB update result:`, (result as any)?.rowCount, `turmaId=${turmaIdInt} data="${dataYMD}"`);
      res.json({ success: true, urls: allUrls });
    } catch (error: any) {
      console.error("Error uploading inclusao foto:", error);
      res.status(500).json({ error: "Erro ao fazer upload da foto" });
    }
  });

