  // PUT /api/chamada/:chamadaId/editar - Editar chamada PEC (chamada + chamada_aluno)
  app.put("/api/chamada/:chamadaId/editar", requireAuth, requireAnyRole([
    "professor",
    "professor_pec",
    "professor_inclusao",
    "professor_psico",
    "monitor",
    "monitor_pec",
    "monitor_inclusao",
    "monitor_psico",
    "coordenador",
    "coordenador_pec",
    "coordenador_inclusao",
    "coordenador_psico",
    "admin",
    "leo",
    "dev",
  ]), async (req, res) => {
    try {
      const user = (req as any).user;
      const userRole = user?.papel || user?.userPapel || user?.role || user?.tipo;
      const chamadaId = parseInt(req.params.chamadaId);
      const { observacoes, presencas } = req.body;
      if (Number.isNaN(chamadaId)) {
        return res.status(400).json({ error: "chamadaId inválido" });
      }

      if (String(userRole || "").startsWith("professor")) {
        const chamadaRow = await db
          .select({ turmaId: chamada.turmaId })
          .from(chamada)
          .where(eq(chamada.id, chamadaId))
          .limit(1);

        if (!chamadaRow.length) {
          return res.status(404).json({ error: "Chamada não encontrada" });
        }

        const allowed = await canProfessorAccessTurma(Number(user.id), Number(chamadaRow[0].turmaId), "pec");
        if (!allowed) {
          return res.status(403).json({ error: "Acesso negado para editar chamada desta turma" });
        }
      }

      if (observacoes !== undefined) {
        await db.update(chamada).set({ observacoes }).where(eq(chamada.id, chamadaId));
      }

      if (presencas && Array.isArray(presencas)) {
        await db.delete(chamadaAluno).where(eq(chamadaAluno.chamadaId, chamadaId));
        for (const p of presencas) {
          await db.insert(chamadaAluno).values({
            chamadaId,
            alunoCpf: p.alunoCpf || p.cpf,
            status: p.justificativa && p.justificativa !== 'Sem justificativa' ? 'falta_justificada' : (p.presente ? 'presente' : 'falta'),
            observacoes: p.observacoes || null,
            justificativa: p.justificativa || null,
          });
        }
      }

      try {
        const fr = (app as any)._firePushRulesByTrigger;
        if (fr) {
          const chamadaInfo = await db
            .select({ turmaId: chamada.turmaId, professorId: chamada.professorId })
            .from(chamada)
            .where(eq(chamada.id, chamadaId))
            .limit(1);
          const turmaId = chamadaInfo[0]?.turmaId;
          if (turmaId) {
            const staffKeys = await resolveStaffUserKeysForTurma(pool, "pec", Number(turmaId));
            if (staffKeys.length > 0) {
              fr(
                "chamada_editada_manual",
                { chamada: String(chamadaId), editor: String((req as any).user?.nome || "") },
                undefined,
                undefined,
                undefined,
                { vertente: "pec", targetUserKeys: staffKeys }
              );
            } else {
              console.warn(`[Push] chamada_editada_manual: turma ${turmaId} sem equipe vinculada`);
            }
          }
        }
      } catch { }
      res.json({ success: true, message: "Chamada atualizada com sucesso" });
    } catch (error: any) {
      console.error("Error updating chamada:", error);
      res.status(500).json({ error: "Erro ao atualizar chamada" });
    }
  });

