  app.get("/api/dev/enrolled-count", async (req, res) => {
    try {
      const { Pool } = await import("pg");
      const pool = new Pool({
        host: process.env.DO_DB_HOST,
        port: 5433,
        user: process.env.DO_DB_USER,
        password: process.env.DO_DB_PASSWORD,
        database: process.env.DO_DB_NAME,
        ssl: false,
      });
      const [pecRes, inclusaoRes] = await Promise.all([
        pool.query("SELECT COUNT(DISTINCT REGEXP_REPLACE(student_cpf, '[^0-9]', '', 'g')) as count FROM instance_enrollments WHERE evadido = false"),
        pool.query("SELECT COUNT(DISTINCT pt.participante_id) as count FROM participantes_turmas pt WHERE pt.status = 'ativo'"),
      ]);
      await pool.end();
      const pec = parseInt(pecRes.rows[0].count || "0");
      const inclusao = parseInt(inclusaoRes.rows[0].count || "0");
      res.json({ pec, inclusao, total: pec + inclusao });
    } catch (err: any) {
      console.error("[dev/enrolled-count]", err.message);
      res.status(500).json({ pec: 0, inclusao: 0, total: 0 });
    }
  });

