  // Cache populado uma vez na primeira chamada
  const gitDateCache: Record<string, string> = {};
  let gitCacheReady = false;

  function buildGitDateCache() {
    if (gitCacheReady) return;
    for (const [nome, filePath] of Object.entries(TELA_FILE_MAP)) {
      try {
        const result = execSync(
          `git --no-optional-locks log -1 --format="%ai" -- "${filePath}"`,
          { encoding: "utf8", timeout: 3000 }
        ).trim();
        if (result) gitDateCache[nome] = result;
      } catch (_) { /* arquivo sem histórico — mantém hardcoded */ }
    }
    gitCacheReady = true;
    console.log("[dev/telas] Git date cache built for", Object.keys(gitDateCache).length, "telas");
  }
