  async function runTelaHealthChecks() {
    if (healthCheckRunning) return;
    healthCheckRunning = true;
    console.log("[health] Iniciando verificação de saúde das telas...");
    try {
      await Promise.all(SISTEMA_TELAS_DEF.map(async (tela) => {
        try {
          const start = Date.now();
          const controller = new AbortController();
          const tid = setTimeout(() => controller.abort(), 7000);
          const port = Number(process.env.PORT) || 5000;
          const res = await fetch(`http://localhost:${port}${tela.rota}`, {
            signal: controller.signal,
            headers: { 'x-dev-health-check': '1' }
          });
          clearTimeout(tid);
          const ms = Date.now() - start;
          let status = "OK";
          if (res.status >= 500) status = "Erro";
          else if (res.status >= 400) status = "Em atenção";
          else if (ms > 4000) status = "Em atenção";
          telaHealthCache.set(tela.nome, { status, responseMs: ms, checkedAt: new Date() });
        } catch (e: any) {
          telaHealthCache.set(tela.nome, {
            status: e.name === 'AbortError' ? "Em atenção" : "Erro",
            responseMs: e.name === 'AbortError' ? 7000 : 0,
            checkedAt: new Date()
          });
        }
      }));
      console.log("[health] Verificação concluída para", SISTEMA_TELAS_DEF.length, "telas");
    } finally {
      healthCheckRunning = false;
      if (!healthCheckScheduled) {
        healthCheckScheduled = true;
        setInterval(runTelaHealthChecks, 30 * 60 * 1000);
      }
    }
  }

  // Primeira verificação após o servidor estabilizar (pode desligar com SKIP_TELA_HEALTH_CHECK=true)
  if (process.env.SKIP_TELA_HEALTH_CHECK !== "true") {
    setTimeout(runTelaHealthChecks, 3000);
  }

  // ────────────────────────────────────────────────────────────────────────────

