  // LGPD — Verificar se usuário aceitou a versão atual dos Termos
  app.get("/api/termos/status", async (req, res) => {
    try {
      const tipo = (req.query.tipo as string) || "user";
      const userId = parseInt(req.query.userId as string);
      if (tipo !== "aluno" && (!userId || isNaN(userId))) return res.status(400).json({ error: "userId obrigatório" });
      let row: any = null;
      if (tipo === "aluno") {
        const cpf = req.query.cpf as string;
        if (!cpf) return res.status(400).json({ error: "cpf obrigatório para aluno" });
        const { row: termosRow, knownStudent } = await fetchAlunoTermosByCpf(pool, cpf);
        if (!knownStudent) return res.status(404).json({ error: "Aluno não encontrado" });
        row = termosRow;
      } else if (tipo === "monitor") {
        const result = await pool.query(
          `SELECT termos_uso_versao, termos_uso_aceito_em FROM monitores WHERE id = $1`,
          [userId]
        );
        row = result.rows[0] || null;
      } else if (tipo === "professor") {
        const result = await pool.query(
          `SELECT termos_uso_versao, termos_uso_aceito_em FROM professores WHERE id = $1`,
          [userId]
        );
        row = result.rows[0] || null;
      } else {
        const tabela = tipo === "coordenador" ? "coordenadores" : "users";
        const result = await pool.query(
          `SELECT termos_uso_versao, termos_uso_aceito_em FROM ${tabela} WHERE id = $1`,
          [userId]
        );
        row = result.rows[0] || null;
      }
      if (tipo === "aluno" && row === null) {
        return res.json({
          aceitou: false,
          versao: null,
          aceitoEm: null,
        });
      }
      if (!row) return res.status(404).json({ error: "Usuário não encontrado" });
      res.json({
        aceitou: row.termos_uso_versao === TERMS_VERSION_REQUIRED,
        versao: row.termos_uso_versao || null,
        aceitoEm: row.termos_uso_aceito_em || null,
      });
    } catch (error: any) {
      console.error("Erro ao verificar termos:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // LGPD — Registrar aceite dos Termos de Uso
  app.post("/api/aceitar-termos", async (req, res) => {
    try {
      const { userId, versao, tipo, cpf } = req.body;
      if (!userId && tipo !== "aluno") return res.status(400).json({ error: "userId obrigatório" });
      if (tipo === "aluno" && !cpf) return res.status(400).json({ error: "cpf obrigatório para aluno" });
      const versaoFinal = versao || "2026-04-01";
      const ip = (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.socket?.remoteAddress || null;
      const userAgent = (req.headers["user-agent"] as string) || null;
      if (tipo === "aluno") {
        const { cpf } = req.body;
        if (!cpf) throw new Error("cpf obrigatório para aluno");
        const persistido = await persistAlunoTermosAceiteByCpf(pool, cpf, versaoFinal, {
          ip,
          userAgent,
        });
        if (persistido === "not_found") {
          return res.status(404).json({ error: "Aluno não encontrado" });
        }
        if (persistido === "inserted_from_inclusao") {
          console.log(`[termos] Aceite Inclusão espelhado em aluno (CPF) para termos/push`);
        }
      } else if (tipo === "monitor") {
        await pool.query(
          `UPDATE monitores SET termos_uso_aceito_em = NOW(), termos_uso_versao = $1, termos_ip = $3, termos_user_agent = $4 WHERE id = $2`,
          [versaoFinal, userId, ip, userAgent]
        );
      } else if (tipo === "professor") {
        await pool.query(
          `UPDATE professores SET termos_uso_aceito_em = NOW(), termos_uso_versao = $1, termos_ip = $3, termos_user_agent = $4 WHERE id = $2`,
          [versaoFinal, userId, ip, userAgent]
        );
      } else {
        const tabela = tipo === "coordenador" ? "coordenadores" : "users";
        await pool.query(
          `UPDATE ${tabela} SET termos_uso_aceito_em = NOW(), termos_uso_versao = $1, termos_ip = $3, termos_user_agent = $4 WHERE id = $2`,
          [versaoFinal, userId, ip, userAgent]
        );
        if (tabela === "users" && userId != null) {
          try {
            await recordLegalAcceptance(pool, {
              userId: Number(userId),
              documentType: "terms",
              documentVersion: versaoFinal,
              ip,
              userAgent,
            });
          } catch (legalErr: unknown) {
            const msg = legalErr instanceof Error ? legalErr.message : String(legalErr);
            console.warn("[meus-dados] Falha ao espelhar aceite de termos:", msg);
          }
        }
      }
      try {
        const fr = (app as any)._firePushRulesByTrigger;
        if (fr) {
          const nomeRef = tipo === "aluno" ? req.body.cpf : String(userId);
          fr("termos_aceitos", { nome: nomeRef || "", data: new Date().toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" }), versao: versaoFinal, perfil: tipo || "user" });
        }
      } catch { }
      try {
        await mirrorTermosAceiteToPrivacyConsent({
          tipo: tipo || "user",
          userId: userId != null ? Number(userId) : null,
          cpf: tipo === "aluno" ? req.body.cpf : undefined,
          ip,
          ua: userAgent,
        });
      } catch (mirrorErr: any) {
        console.warn("[LGPD] Espelho termos → privacy_consents:", mirrorErr?.message || mirrorErr);
      }
      res.json({ success: true, versao: versaoFinal });
    } catch (error: any) {
      console.error("Erro ao registrar aceite de termos:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

