  app.get("/api/admin/privacy-consents", requireAuth, requireAnyRole([
    "admin", "leo", "dev", "desenvolvedor", "super_admin",
  ]), async (req: any, res) => {
    try {
      const page = Math.max(1, Number(req.query.page) || 1);
      const pageSize = Math.min(200, Math.max(1, Number(req.query.pageSize) || 50));
      const offset = (page - 1) * pageSize;

      const consentArea = typeof req.query.consentArea === "string" ? req.query.consentArea.trim() : "";
      const source = typeof req.query.source === "string" ? req.query.source.trim() : "";
      const status = typeof req.query.status === "string" ? req.query.status.trim() : "";
      const from = typeof req.query.from === "string" ? req.query.from.trim() : "";
      const to = typeof req.query.to === "string" ? req.query.to.trim() : "";
      const q = typeof req.query.q === "string" ? req.query.q.trim() : "";
      const format = typeof req.query.format === "string" ? req.query.format.trim().toLowerCase() : "";
      const analyticsFilter = typeof req.query.analytics === "string" ? req.query.analytics.trim().toLowerCase() : "";
      const functionalFilter = typeof req.query.functional === "string" ? req.query.functional.trim().toLowerCase() : "";
      const marketingFilter = typeof req.query.marketing === "string" ? req.query.marketing.trim().toLowerCase() : "";
      const imageUseFilter = typeof req.query.image_use === "string" ? req.query.image_use.trim().toLowerCase() : "";
      const communicationsFilter = typeof req.query.communications === "string" ? req.query.communications.trim().toLowerCase() : "";
      const sortByRaw = typeof req.query.sortBy === "string" ? req.query.sortBy.trim() : "updated_at";
      const sortDirRaw = typeof req.query.sortDir === "string" ? req.query.sortDir.trim().toLowerCase() : "desc";

      const sortByMap: Record<string, string> = {
        updated_at: "pc.updated_at",
        source: "pc.source",
        consent_area: "pc.consent_area",
        status_rank: "(pc.analytics::int + pc.functional::int + pc.marketing::int + pc.image_use::int + pc.communications::int)",
      };
      const sortBy = sortByMap[sortByRaw] || sortByMap.updated_at;
      const sortDir = sortDirRaw === "asc" ? "ASC" : "DESC";

      const where: string[] = [];
      const params: any[] = [];
      let idx = 1;

      if (consentArea) {
        where.push(`pc.consent_area = $${idx++}`);
        params.push(consentArea);
      }
      if (source) {
        where.push(`pc.source = $${idx++}`);
        params.push(source);
      }
      if (status === "accepted") {
        where.push(`(pc.analytics = TRUE OR pc.functional = TRUE OR pc.marketing = TRUE OR pc.image_use = TRUE OR pc.communications = TRUE)`);
      } else if (status === "rejected") {
        where.push(`(pc.analytics = FALSE AND pc.functional = FALSE AND pc.marketing = FALSE AND pc.image_use = FALSE AND pc.communications = FALSE)`);
      } else if (status === "partial") {
        where.push(`(
          (pc.analytics::int + pc.functional::int + pc.marketing::int + pc.image_use::int + pc.communications::int) BETWEEN 1 AND 4
        )`);
      }
      if (from) {
        where.push(`pc.updated_at >= $${idx++}::timestamptz`);
        params.push(from);
      }
      if (to) {
        where.push(`pc.updated_at <= $${idx++}::timestamptz`);
        params.push(to);
      }
      if (q) {
        where.push(`(
          CAST(COALESCE(pc.user_id, 0) AS TEXT) ILIKE $${idx}
          OR COALESCE(pc.anonymous_consent_id, '') ILIKE $${idx}
          OR COALESCE(pc.role, '') ILIKE $${idx}
          OR COALESCE(pc.source, '') ILIKE $${idx}
          OR COALESCE(u.nome, '') ILIKE $${idx}
          OR COALESCE(u.sobrenome, '') ILIKE $${idx}
          OR COALESCE(u.email, '') ILIKE $${idx}
        )`);
        params.push(`%${q}%`);
        idx++;
      }
      if (analyticsFilter === "true" || analyticsFilter === "false") {
        where.push(`pc.analytics = $${idx++}`);
        params.push(analyticsFilter === "true");
      }
      if (functionalFilter === "true" || functionalFilter === "false") {
        where.push(`pc.functional = $${idx++}`);
        params.push(functionalFilter === "true");
      }
      if (marketingFilter === "true" || marketingFilter === "false") {
        where.push(`pc.marketing = $${idx++}`);
        params.push(marketingFilter === "true");
      }
      if (imageUseFilter === "true" || imageUseFilter === "false") {
        where.push(`pc.image_use = $${idx++}`);
        params.push(imageUseFilter === "true");
      }
      if (communicationsFilter === "true" || communicationsFilter === "false") {
        where.push(`pc.communications = $${idx++}`);
        params.push(communicationsFilter === "true");
      }

      const fromJoin = `FROM privacy_consents pc LEFT JOIN users u ON u.id = pc.user_id`;
      const whereSql = where.length ? `WHERE ${where.join(" AND ")}` : "";

      const baseSelect = `
        SELECT
          pc.id,
          pc.user_id,
          TRIM(CONCAT(COALESCE(u.nome, ''), ' ', COALESCE(u.sobrenome, ''))) AS user_name,
          u.email AS user_email,
          pc.anonymous_consent_id,
          pc.role,
          pc.consent_area,
          pc.consent_version,
          pc.privacy_policy_version,
          pc.cookie_policy_version,
          pc.terms_version,
          pc.image_policy_version,
          pc.policy_hash,
          pc.consent_hmac,
          pc.policy_bundle_id,
          pc.client_policy_hash,
          pc.necessary,
          pc.analytics,
          pc.functional,
          pc.marketing,
          pc.image_use,
          pc.communications,
          pc.source,
          pc.ip_address,
          pc.user_agent,
          pc.accepted_at_client,
          pc.created_at,
          pc.updated_at
        ${fromJoin}
        ${whereSql}
      `;

      if (format === "csv") {
        const csvRows = await pool.query(`${baseSelect} ORDER BY ${sortBy} ${sortDir}, pc.updated_at DESC LIMIT 5000`, params);
        const headers = [
          "id",
          "user_id",
          "user_name",
          "user_email",
          "anonymous_consent_id",
          "role",
          "consent_area",
          "consent_version",
          "privacy_policy_version",
          "cookie_policy_version",
          "terms_version",
          "image_policy_version",
          "necessary",
          "analytics",
          "functional",
          "marketing",
          "image_use",
          "communications",
          "source",
          "ip_address",
          "user_agent",
          "accepted_at_client",
          "created_at",
          "updated_at",
        ];
        const escapeCsv = (value: any) => {
          if (value === null || value === undefined) return "";
          const str = String(value);
          if (str.includes('"') || str.includes(",") || str.includes("\n")) {
            return `"${str.replace(/"/g, '""')}"`;
          }
          return str;
        };
        const csvContent = [
          headers.join(","),
          ...csvRows.rows.map((row: any) => headers.map((h) => escapeCsv(row[h])).join(",")),
        ].join("\n");
        res.setHeader("Content-Type", "text/csv; charset=utf-8");
        res.setHeader(
          "Content-Disposition",
          `attachment; filename="privacy-consents-${new Date().toISOString().slice(0, 10)}.csv"`
        );
        return res.status(200).send(csvContent);
      }

      const countResult = await pool.query(
        `SELECT COUNT(*)::int AS total ${fromJoin} ${whereSql}`,
        params
      );
      const summaryResult = await pool.query(
        `SELECT
           COUNT(*)::int AS total,
           COUNT(*) FILTER (
             WHERE (pc.analytics::int + pc.functional::int + pc.marketing::int + pc.image_use::int + pc.communications::int) = 0
           )::int AS rejected_count,
           COUNT(*) FILTER (
             WHERE (pc.analytics::int + pc.functional::int + pc.marketing::int + pc.image_use::int + pc.communications::int) = 5
           )::int AS accepted_count,
           COUNT(*) FILTER (
             WHERE (pc.analytics::int + pc.functional::int + pc.marketing::int + pc.image_use::int + pc.communications::int) BETWEEN 1 AND 4
           )::int AS partial_count
         ${fromJoin}
         ${whereSql}`,
        params
      );
      const dataResult = await pool.query(
        `${baseSelect} ORDER BY ${sortBy} ${sortDir}, pc.updated_at DESC LIMIT $${idx++} OFFSET $${idx++}`,
        [...params, pageSize, offset]
      );

      const summary = summaryResult.rows[0] || {
        total: 0,
        accepted_count: 0,
        rejected_count: 0,
        partial_count: 0,
      };

      res.json({
        page,
        pageSize,
        total: countResult.rows[0]?.total || 0,
        sortBy: sortByRaw,
        sortDir: sortDirRaw === "asc" ? "asc" : "desc",
        summary,
        consents: dataResult.rows,
      });
    } catch (error: any) {
      console.error("Erro GET /api/admin/privacy-consents:", error);
      res.status(500).json({ error: "Erro interno" });
    }
  });

  app.get("/api/admin/staff-area-consents", requireAuth, requireAnyRole([
    "admin", "leo", "dev", "desenvolvedor", "super_admin",
  ]), async (req: any, res) => {
    try {
      const page = Math.max(1, Number(req.query.page) || 1);
      const pageSize = Math.min(200, Math.max(1, Number(req.query.pageSize) || 20));
      const offset = (page - 1) * pageSize;
      const consentArea = typeof req.query.consentArea === "string" ? req.query.consentArea.trim() : "";
      const staffKind = typeof req.query.staffKind === "string" ? req.query.staffKind.trim().toLowerCase() : "";
      const from = typeof req.query.from === "string" ? req.query.from.trim() : "";
      const to = typeof req.query.to === "string" ? req.query.to.trim() : "";
      const q = typeof req.query.q === "string" ? req.query.q.trim() : "";

      const where: string[] = [];
      const params: any[] = [];
      let idx = 1;

      if (consentArea) {
        where.push(`sac.consent_area = $${idx++}`);
        params.push(consentArea);
      }
      if (staffKind && ["professor", "monitor", "coordenador"].includes(staffKind)) {
        where.push(`sac.staff_kind = $${idx++}`);
        params.push(staffKind);
      }
      if (from) {
        where.push(`sac.accepted_at >= $${idx++}::timestamptz`);
        params.push(from);
      }
      if (to) {
        where.push(`sac.accepted_at <= $${idx++}::timestamptz`);
        params.push(to);
      }
      if (q) {
        where.push(`(
          CAST(sac.staff_id AS TEXT) ILIKE $${idx}
          OR COALESCE(p.nome, '') ILIKE $${idx}
          OR COALESCE(m.nome, '') ILIKE $${idx}
          OR COALESCE(c.nome, '') ILIKE $${idx}
          OR COALESCE(sac.source, '') ILIKE $${idx}
        )`);
        params.push(`%${q}%`);
        idx++;
      }

      const fromJoin = `
        FROM staff_area_consents sac
        LEFT JOIN professores p ON sac.staff_kind = 'professor' AND sac.staff_id = p.id
        LEFT JOIN monitores m ON sac.staff_kind = 'monitor' AND sac.staff_id = m.id
        LEFT JOIN coordenadores c ON sac.staff_kind = 'coordenador' AND sac.staff_id = c.id`;
      const whereSql = where.length ? `WHERE ${where.join(" AND ")}` : "";
      const baseSelect = `
        SELECT
          sac.id,
          sac.staff_kind,
          sac.staff_id,
          COALESCE(p.nome, m.nome, c.nome) AS staff_name,
          sac.consent_area,
          sac.policy_bundle_id,
          sac.privacy_policy_version,
          sac.terms_version,
          sac.image_use,
          sac.communications,
          sac.marketing,
          sac.source,
          sac.ip_address,
          sac.user_agent,
          sac.accepted_at
        ${fromJoin}
        ${whereSql}`;

      const countResult = await pool.query(
        `SELECT COUNT(*)::int AS total ${fromJoin} ${whereSql}`,
        params
      );
      const dataResult = await pool.query(
        `${baseSelect} ORDER BY sac.accepted_at DESC LIMIT $${idx++} OFFSET $${idx++}`,
        [...params, pageSize, offset]
      );

      res.json({
        page,
        pageSize,
        total: countResult.rows[0]?.total || 0,
        consents: dataResult.rows,
      });
    } catch (error: any) {
      console.error("Erro GET /api/admin/staff-area-consents:", error);
      res.status(500).json({ error: "Erro interno" });
    }
  });

