  // PATCH /api/meus-dados — atualiza dados básicos do usuário logado
  app.patch("/api/meus-dados", requireAuth, async (req: any, res) => {
    try {
      const ctx = await resolveMeusDadosContext(req);
      if (!ctx?.usersId) {
        return res.status(400).json({
          error: ctx?.cpf
            ? "Atualização pelo app não disponível para este perfil. Fale com a secretaria."
            : "Não autenticado",
        });
      }
      const { nome, email, telefone } = req.body;
      const updates: string[] = [];
      const values: any[] = [];
      let idx = 1;
      if (nome !== undefined) { updates.push(`nome = $${idx++}`); values.push(nome); }
      if (email !== undefined) { updates.push(`email = $${idx++}`); values.push(email); }
      if (telefone !== undefined) { updates.push(`telefone = $${idx++}`); values.push(telefone); }
      if (updates.length === 0) return res.status(400).json({ error: "Nenhum dado para atualizar" });
      updates.push(`updated_at = NOW()`);
      values.push(ctx.usersId);
      await pool.query(`UPDATE users SET ${updates.join(", ")} WHERE id = $${idx}`, values);
      res.json({ success: true });
    } catch (error: any) {
      console.error("Erro PATCH /api/meus-dados:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

