  // Login para desenvolvedores
  // TRECHO ALTERADO
  app.post("/api/dev/login", express.json(), passwordLoginLimiter, async (req, res) => {
    try {
      const { usuario, senha } = (req.body ?? {}) as {
        usuario?: string;
        senha?: string;
      };

      if (!usuario || !senha) {
        return res
          .status(400)
          .json({ error: "Usuário e senha são obrigatórios" });
      }

      // busca pelo campo correto
      const rows = await db
        .select()
        .from(developers)
        .where(eq(developers.usuario, usuario))
        .limit(1);

      const devUser = rows[0];
      if (!devUser)
        return res.status(401).json({ error: "Credenciais inválidas" });

      if (devUser.ativo === false)
        return res.status(401).json({ error: "Usuário desativado" });

      // validação de senha (bcrypt ou texto puro para compatibilidade antiga)
      const saved = String(devUser.senha ?? "");
      const looksLikeBcrypt = /^$2[aby]$/.test(saved);

      // Debug específico para devfull
      if (usuario === "devfull") {
      }

      let ok = false;
      if (looksLikeBcrypt) {
        try {
          ok = await bcrypt.compare(senha, saved);
        } catch (bcryptError: any) {
          console.error(
            `❌ [DEV LOGIN DEBUG] Erro no bcrypt.compare:`,
            bcryptError.message
          );
          ok = false;
        }
      } else {
        ok = senha === saved;
      }

      if (!ok) {
        return res.status(401).json({ error: "Credenciais inválidas" });
      }

      // ✅ Configurar sessão APÓS validação bem-sucedida
      if (req.session) {
        clearCrossActorSessionFields(req.session as Record<string, unknown>);
        req.session.developerId = devUser.id;
        req.session.actorType = "desenvolvedor";
        req.session.userPapel =
          devUser.tipo === "admin"
            ? "dev-admin"
            : devUser.tipo === "marketing"
              ? "dev-marketing"
              : "dev";
        req.session.telefone = devUser.usuario;
        req.session.userId = devUser.id;
        req.session.nome = devUser.nome;

        // 🔐 SALVAR SESSÃO EXPLICITAMENTE para garantir persistência
        await new Promise<void>((resolve, reject) => {
          req.session.save((err) => {
            if (err) {
              console.error("[DEV LOGIN] Erro ao salvar sessão:", err);
              reject(err);
            } else {
              console.log("[DEV LOGIN] Sessão salva com sucesso:", {
                developerId: req.session.developerId,
                userPapel: req.session.userPapel,
                tipo: devUser.tipo,
                sessionID: req.sessionID,
              });
              resolve();
            }
          });
        });
      }

      // atualiza último acesso (sem depender do schema TS)
      try {
        await db.execute(
          sql`UPDATE developers SET ultimo_acesso = NOW() WHERE id = ${devUser.id}`
        );
      } catch (e) {
        console.warn("[DEV LOGIN] Falha ao atualizar ultimo_acesso:", e);
        // não interrompe login
      }

      return res.json({
        success: true,
        developer: {
          id: devUser.id,
          usuario: devUser.usuario,
          nome: devUser.nome,
          email: devUser.email,
          tipo: devUser.tipo ?? "dev",
          ativo: devUser.ativo,
          ultimo_acesso: new Date().toISOString(),
        },
      });
    } catch (error) {
      console.error("Error in developer login:", error);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Alterar senha do desenvolvedor
  app.post(
    "/api/dev/alterar-senha",
    express.json(),
    requireDevAuth,
    async (req, res) => {
      try {
        console.log("[ALTERAR SENHA] Rota executada, body:", req.body);
        console.log("[ALTERAR SENHA] Session data:", req.session);
        console.log("[ALTERAR SENHA] Developer ID:", (req as any).developerId);

        const { senhaAtual, novaSenha } = req.body;

        // Validar senha atual
        if (!senhaAtual || typeof senhaAtual !== "string") {
          return res.status(400).json({ error: "Senha atual é obrigatória" });
        }

        if (!novaSenha || typeof novaSenha !== "string") {
          return res.status(400).json({ error: "Nova senha é obrigatória" });
        }

        if (novaSenha.length < 8) {
          return res
            .status(400)
            .json({ error: "A senha deve ter no mínimo 8 caracteres" });
        }

        // 🔒 VALIDAÇÃO DE COMPLEXIDADE DE SENHA
        if (!/[A-Z]/.test(novaSenha)) {
          return res.status(400).json({
            error: "Senha deve conter pelo menos uma letra maiúscula",
          });
        }

        if (!/[0-9]/.test(novaSenha)) {
          return res.status(400).json({
            error: "Senha deve conter pelo menos um número",
          });
        }

        // Pegar ID do desenvolvedor da sessão
        const developerId = (req as any).developerId;

        // Buscar desenvolvedor
        const rows = await db
          .select()
          .from(developers)
          .where(eq(developers.id, developerId))
          .limit(1);

        const devUser = rows[0];
        if (!devUser) {
          return res
            .status(404)
            .json({ error: "Desenvolvedor não encontrado" });
        }

        // Verificar senha atual
        const senhaValida = await bcrypt.compare(senhaAtual, devUser.senha);
        if (!senhaValida) {
          return res.status(401).json({ error: "Senha atual incorreta" });
        }

        // Hash da nova senha com bcrypt
        const hashedPassword = await bcrypt.hash(novaSenha, 10);

        // Atualizar senha no banco
        await db.execute(
          sql`UPDATE developers SET senha = ${hashedPassword} WHERE id = ${developerId}`
        );

        const devUserId = devUser.email
          ? await resolveUsersIdByEmail(pool, devUser.email)
          : await resolveUsersIdByDeveloperId(pool, developerId);
        if (devUserId) {
          firePushRulesByTrigger("senha_alterada", senhaAlteradaVars(), undefined, devUserId).catch(() => { });
        }

        return res.json({
          success: true,
          message: "Senha alterada com sucesso",
        });
      } catch (error) {
        console.error("Error changing developer password:", error);
        return res.status(500).json({ error: "Erro ao alterar senha" });
      }
    }
  );

  // ================ COORDENADORES - LOGIN ================

  // Login para coordenadores (apenas com email)

  // ================= AUTH COORDENADOR (INLINE) =================
  function requireCoordinatorAuth(req: any, res: any, next: any) {
    const sess = req.session as any;

    // 0) Dev mode bypass — permite acesso total quando logado como desenvolvedor
    if (sess?.developerId && (sess?.userPapel === "dev" || sess?.userPapel === "desenvolvedor")) {
      req.user = {
        id: sess.developerId,
        role: "dev",
        papel: "dev",
        actorType: "coordenador",
        actorId: sess.developerId,
        email: sess.userEmail || "",
        name: sess.userName || "Dev",
      };
      return next();
    }

    // 1) via sessão (normal)
    if (sess?.coordenadorId && sess?.actorType === "coordenador") {
      req.user = {
        id: sess.coordenadorId,
        papel: sess.userPapel,
        role: sess.userPapel,
        actorType: "coordenador",
        actorId: sess.coordenadorId,
        email: sess.coordenadorEmail,
        name: sess.coordenadorNome,
        setor: sess.coordenadorSetor,
      };
      return next();
    }

    return res.status(401).json({ error: "Não autenticado como coordenador" });
  }

  /** Coordenador (sessão dedicada) tem prioridade; senão cai no requireAuth geral (leo, admin, etc.). */
  function requireCoordinatorOrGeneralAuth(req: any, res: any, next: any) {
    const sess = req.session as any;

    if (sess?.developerId && (sess?.userPapel === "dev" || sess?.userPapel === "desenvolvedor")) {
      req.user = {
        id: sess.developerId,
        papel: sess.userPapel,
        role: sess.userPapel,
        actorType: "coordenador",
        actorId: sess.developerId,
        email: sess.userEmail || "",
        nome: sess.userName || "Dev",
      };
      return next();
    }

    if (sess?.coordenadorId && sess?.actorType === "coordenador") {
      req.user = {
        id: sess.coordenadorId,
        papel: sess.userPapel,
        role: sess.userPapel,
        actorType: "coordenador",
        actorId: sess.coordenadorId,
        email: sess.coordenadorEmail,
        nome: sess.coordenadorNome,
        setor: sess.coordenadorSetor,
      };
      return next();
    }

    return requireAuth(req, res, next);
  }

  // Rastreador em memória de tentativas de senha incorreta por login (reseta com reinício)
