  // Alterar senha do coordenador
  app.post(
    "/api/coordenador/alterar-senha",
    requireCoordinatorAuth, // ✅ TROCOU AQUI
    express.json(),
    async (req: any, res) => {
      try {
        const { senhaAtual, novaSenha } = req.body;

        const coordenadorId = req.user.id; // ✅ vem da sessão

        if (!senhaAtual || !senhaAtual.trim()) {
          return res.status(400).json({ error: "Senha atual é obrigatória" });
        }

        if (!novaSenha || !novaSenha.trim()) {
          return res.status(400).json({ error: "Nova senha é obrigatória" });
        }

        if (novaSenha.length < 8) {
          return res.status(400).json({ error: "Senha deve ter no mínimo 8 caracteres" });
        }
        if (!/[A-Z]/.test(novaSenha)) {
          return res.status(400).json({ error: "Senha deve conter pelo menos uma letra maiúscula" });
        }
        if (!/[0-9]/.test(novaSenha)) {
          return res.status(400).json({ error: "Senha deve conter pelo menos um número" });
        }

        // ✅ buscar o coordenador REAL no banco (pra pegar passwordHash)
        const coordData = await db
          .select()
          .from(coordenadores)
          .where(eq(coordenadores.id, coordenadorId))
          .limit(1);

        if (!coordData || coordData.length === 0) {
          return res.status(404).json({ error: "Coordenador não encontrado" });
        }

        const coord = coordData[0];

        const senhaValida = await bcrypt.compare(senhaAtual, coord.passwordHash);
        if (!senhaValida) {
          return res.status(401).json({ error: "Senha atual incorreta" });
        }

        const novoHash = bcrypt.hashSync(novaSenha, 10);

        await db
          .update(coordenadores)
          .set({ passwordHash: novoHash })
          .where(eq(coordenadores.id, coordenadorId));

        console.log(`✅ [COORD SENHA] Senha alterada: coordId=${coordenadorId}`);
        const coordUserId = await resolveUsersIdByCoordenadorId(pool, coordenadorId);
        if (coordUserId) {
          firePushRulesByTrigger("senha_alterada", senhaAlteradaVars(), undefined, coordUserId).catch(() => { });
        }

        res.json({ success: true, message: "Senha alterada com sucesso" });
      } catch (error: any) {
        console.error("❌ [COORD SENHA] Erro:", error);
        res.status(500).json({ error: "Erro interno do servidor" });
      }
    }
  );
