  // PUT /api/coordenador/me - Atualizar dados do coordenador autenticado
  app.put(
    "/api/coordenador/me",
    requireCoordinatorAuth, // ✅ TROCOU AQUI
    express.json(),
    async (req: any, res) => {
      try {
        const coordenadorId = req.user.id;
        const coordenadorEmailAtual = req.user.email;

        const { nome, email, telefone } = req.body;

        if (!nome || !nome.trim()) {
          return res.status(400).json({ error: "Nome é obrigatório" });
        }

        if (!email || !email.trim()) {
          return res.status(400).json({ error: "Email é obrigatório" });
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
          return res.status(400).json({ error: "Email inválido" });
        }

        // Verificar se o email já existe (em outro coordenador)
        if (email.trim().toLowerCase() !== coordenadorEmailAtual?.toLowerCase()) {
          const emailExiste = await db
            .select()
            .from(coordenadores)
            .where(
              and(
                eq(coordenadores.email, email.trim().toLowerCase()),
                not(eq(coordenadores.id, coordenadorId))
              )
            )
            .limit(1);

          if (emailExiste && emailExiste.length > 0) {
            return res.status(400).json({
              error: "Este email já está em uso por outro coordenador",
            });
          }
        }

        await db
          .update(coordenadores)
          .set({
            nome: nome.trim(),
            email: email.trim().toLowerCase(),
            telefone: telefone?.trim() || null,
            updatedAt: new Date(),
          })
          .where(eq(coordenadores.id, coordenadorId));

        // (Opcional) atualizar users se existir
        const oldEmail = coordenadorEmailAtual;
        if (email.trim().toLowerCase() !== oldEmail?.toLowerCase()) {
          const userToUpdate = await db
            .select()
            .from(users)
            .where(eq(users.email, oldEmail))
            .limit(1);

          if (userToUpdate && userToUpdate.length > 0) {
            await db
              .update(users)
              .set({
                nome: nome.trim(),
                email: email.trim().toLowerCase(),
              })
              .where(eq(users.id, userToUpdate[0].id));
          }
        }

        const coordAtualizado = await db
          .select()
          .from(coordenadores)
          .where(eq(coordenadores.id, coordenadorId))
          .limit(1);

        const { passwordHash, ...coordSemSenha } = coordAtualizado[0];

        res.json({
          success: true,
          message: "Perfil atualizado com sucesso",
          data: coordSemSenha,
        });
      } catch (error: any) {
        console.error("❌ [PUT /api/coordenador/me] Erro:", error);
        res.status(500).json({ error: "Erro interno do servidor" });
      }
    }
  );

