  app.post("/api/login/monitor", express.json(), passwordLoginLimiter, async (req, res) => {
    try {
      const { email, senha } = req.body;

      if (!email || !email.trim()) return res.status(400).json({ error: "Email é obrigatório" });
      if (!senha || !senha.trim()) return res.status(400).json({ error: "Senha é obrigatória" });

      const normalizedEmail = email.toLowerCase().trim();

      console.log(`🔑 [MONITOR LOGIN] Tentativa de login: ${normalizedEmail}`);

      const monitorResult = await db
        .select()
        .from(monitores)
        .where(eq(monitores.email, normalizedEmail))
        .limit(1);

      if (!monitorResult?.length) {
        console.log(`❌ [MONITOR LOGIN] Monitor não encontrado: ${normalizedEmail}`);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }

      const monitor = monitorResult[0];

      if (!monitor.ativo) {
        console.log(`❌ [MONITOR LOGIN] Monitor desativado: ${normalizedEmail}`);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }

      if (!monitor.passwordHash) {
        console.log(`❌ [MONITOR LOGIN] Monitor sem passwordHash: ${normalizedEmail}`);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }

      const senhaValida = await bcrypt.compare(senha, monitor.passwordHash);
      if (!senhaValida) {
        console.log(`❌ [MONITOR LOGIN] Senha incorreta para: ${normalizedEmail}`);
        const _cnt = (_failedLoginAttempts.get(normalizedEmail) || 0) + 1;
        _failedLoginAttempts.set(normalizedEmail, _cnt);
        if (_cnt >= 3) _failedLoginAttempts.delete(normalizedEmail);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }
      _failedLoginAttempts.delete(normalizedEmail);

      let role = "monitor";
      switch (monitor.programa) {
        case "pec": role = "monitor_pec"; break;
        case "inclusao_produtiva": role = "monitor_inclusao"; break;
        case "psicossocial": role = "monitor_psico"; break;
      }

      const existingUser = await db
        .select()
        .from(users)
        .where(eq(users.email, normalizedEmail))
        .limit(1);

      let userId: number;

      if (existingUser?.length) {
        await db
          .update(users)
          .set({ nome: monitor.nome, role, ativo: true, tipo: "monitor" })
          .where(eq(users.id, existingUser[0].id));
        try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("usuario_desbloqueado", { nome: monitor.nome || normalizedEmail, perfil: "monitor", data: new Date().toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" }), alterado_por: "admin" }); } catch { }

        userId = existingUser[0].id;
      } else {
        const newUser = await db
          .insert(users)
          .values({
            email: normalizedEmail,
            nome: monitor.nome,
            telefone: monitor.telefone || "",
            role,
            ativo: true,
            tipo: "monitor",
            verificado: true,
          })
          .returning();

        userId = newUser[0].id;
      }

      /** ✅ CRIA/ATUALIZA SESSÃO DE MONITOR (ISOLA DE COORDENADOR) **/
      clearCrossActorSessionFields(req.session as Record<string, unknown>);
      (req.session as any).user = {
        id: userId,                 // users.id
        role,                       // monitor_inclusao | monitor_pec | monitor
        tipo: "monitor",
        email: normalizedEmail,
        nome: monitor.nome,
        monitorId: monitor.id,      // monitores.id
        programa: monitor.programa, // pec | inclusao_produtiva | psicossocial
        actorType: "monitor",
      };
      (req.session as any).actorType = "monitor";

      console.log(
        `🔐 [MONITOR SESSION] Sessão criada: userId=${userId} role=${role} monitorId=${monitor.id}`
      );

      // ✅ Garante persistência do cookie de sessão antes de responder
      await new Promise<void>((resolve, reject) => {
        req.session.save((err) => (err ? reject(err) : resolve()));
      });

      let redirectPath = "/monitor";

      if (role === "monitor_pec") redirectPath = "/monitor/pec";
      if (role === "monitor_inclusao") redirectPath = "/monitor/inclusao";
      if (role === "monitor_psico") redirectPath = "/monitor/psico";

      // ✅ se você quiser respeitar a coluna do banco quando existir:
      const dbRedirect =
        (monitor as any).redirect_path || (monitor as any).redirectPath;

      redirectPath = dbRedirect || redirectPath;

      return res.json({
        success: true,
        monitor: {
          id: monitor.id,
          nome: monitor.nome,
          email: monitor.email,
          programa: monitor.programa,
          role,
          redirectPath, // ✅ agora sempre vem preenchido
        },
        userId,
      });
    } catch (error: any) {
      console.error("❌ [MONITOR LOGIN] Erro:", error?.stack || error);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

