  app.post("/api/login/professor", express.json(), passwordLoginLimiter, async (req, res) => {
    try {
      const { email, senha } = req.body;

      if (!email || !email.trim()) {
        return res.status(400).json({ error: "Email é obrigatório" });
      }
      if (!senha || !senha.trim()) {
        return res.status(400).json({ error: "Senha é obrigatória" });
      }

      const emailNorm = email.toLowerCase().trim();

      console.log(`🔑 [PROFESSOR LOGIN] Tentativa de login: ${emailNorm}`);

      // Buscar professor por email (SEM programa)
      const professorResult = await pool.query(
        "SELECT * FROM professores WHERE lower(email) = $1 LIMIT 2",
        [emailNorm]
      );

      if (!professorResult.rows || professorResult.rows.length === 0) {
        console.log(`❌ [PROFESSOR LOGIN] Professor não encontrado: ${emailNorm}`);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }

      // Proteção contra duplicidade de email
      if (professorResult.rows.length > 1) {
        console.log(`❌ [PROFESSOR LOGIN] Email duplicado em professores: ${emailNorm}`);
        return res.status(409).json({ error: "Cadastro duplicado. Contate o Admin." });
      }

      const professor = professorResult.rows[0];

      // Verificar se professor está ativo
      if (!professor.ativo) {
        console.log(`❌ [PROFESSOR LOGIN] Professor desativado: ${emailNorm}`);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }

      // Validar senha
      const senhaValida = await bcrypt.compare(senha.trim(), professor.password_hash);
      if (!senhaValida) {
        console.log(`❌ [PROFESSOR LOGIN] Senha incorreta: ${emailNorm}`);
        const _cnt = (_failedLoginAttempts.get(emailNorm) || 0) + 1;
        _failedLoginAttempts.set(emailNorm, _cnt);
        if (_cnt >= 3) _failedLoginAttempts.delete(emailNorm);
        return res.status(401).json({ error: "Email ou senha incorretos" });
      }
      _failedLoginAttempts.delete(emailNorm);

      // ✅ NOVA REGRA:
      // role e redirectPath devem vir do CADASTRO (feito pelo coordenador)
      // Se não tiver role na tabela professores ainda, cai no fallback por programa.
      const role =
        professor.role ||
        (professor.programa === "pec"
          ? "professor_pec"
          : professor.programa === "inclusao_produtiva"
            ? "professor_inclusao"
            : professor.programa === "psicossocial"
              ? "professor_psico"
              : "professor");

      const redirectPath =
        professor.redirect_path ||
        (role === "professor_pec"
          ? "/professor/pec"
          : role === "professor_inclusao"
            ? "/professor/inclusao"
            : role === "professor_psico"
              ? "/professor"
              : "/professor");

      // (Opcional) manter user espelho em users — SEM TELEFONE!
      // Importante: NUNCA inserir "" em telefone se houver unique.
      const existingUser = await db
        .select()
        .from(users)
        .where(and(eq(users.email, professor.email), eq(users.role, role)))
        .limit(1);

      let userId: number;

      if (existingUser && existingUser.length > 0) {
        await db
          .update(users)
          .set({
            nome: professor.nome,
            role,
            ativo: true,
            tipo: "professor",
          })
          .where(eq(users.id, existingUser[0].id));

        userId = existingUser[0].id;
        console.log(`✅ [PROFESSOR LOGIN] Usuário atualizado (users): ${professor.nome} (ID: ${userId})`);
      } else {
        const newUser = await db
          .insert(users)
          .values({
            email: professor.email,
            nome: professor.nome,
            telefone: null, // ✅ CRÍTICO: não usar ""!
            role,
            ativo: true,
            tipo: "professor",
            verificado: true,
          })
          .returning();

        userId = newUser[0].id;
        console.log(`✅ [PROFESSOR LOGIN] Usuário criado (users): ${professor.nome} (ID: ${userId})`);
      }

      console.log(`✅ [PROFESSOR LOGIN] Login OK: ${professor.nome} (userId: ${userId})`);

      /** ✅ CRIA/ATUALIZA SESSÃO DE PROFESSOR **/
      clearCrossActorSessionFields(req.session as Record<string, unknown>);
      (req.session as any).user = {
        id: userId,                  // users.id
        role,                        // professor_inclusao | professor_pec | professor_psico | professor
        tipo: "professor",
        email: emailNorm,
        nome: professor.nome,
        professorId: professor.id,   // professores.id
        programa: professor.programa,
        actorType: "professor",
      };
      (req.session as any).actorType = "professor";

      console.log(
        `🔐 [PROFESSOR SESSION] Sessão criada: userId=${userId} role=${role} professorId=${professor.id}`
      );

      // Garante persistência da sessão antes da resposta
      await new Promise<void>((resolve, reject) => {
        req.session.save((err) => (err ? reject(err) : resolve()));
      });

      return res.json({
        success: true,
        userId,
        professor: {
          id: professor.id,
          nome: professor.nome,
          email: professor.email,
          programa: professor.programa,
          role,
          redirectPath,
        },
      });
    } catch (error: any) {
      console.error("❌ [PROFESSOR LOGIN] Erro:", error);
      return res.status(500).json({ error: "Erro interno no servidor" });
    }
  });

  app.post("/api/login/developer", express.json(), passwordLoginLimiter, async (req, res) => {
    try {
      const { usuario, senha } = req.body;

      if (!usuario || !usuario.trim()) {
        return res.status(400).json({ error: "Usuário é obrigatório" });
      }

      if (!senha || !senha.trim()) {
        return res.status(400).json({ error: "Senha é obrigatória" });
      }

      console.log(`🔑 [DEV LOGIN] Tentativa de login: ${usuario}`);

      // Buscar desenvolvedor por usuário no banco Digital Ocean
      const developerResult = await db
        .select()
        .from(developers)
        .where(eq(developers.usuario, usuario.toLowerCase().trim()))
        .limit(1);

      if (!developerResult || developerResult.length === 0) {
        console.log(`❌ [DEV LOGIN] Desenvolvedor não encontrado: ${usuario}`);
        return res.status(401).json({ error: "Usuário ou senha incorretos" });
      }

      const dev = developerResult[0];

      // Verificar se desenvolvedor está ativo
      if (!dev.ativo) {
        console.log(`❌ [DEV LOGIN] Desenvolvedor desativado: ${usuario}`);
        return res.status(401).json({ error: "Acesso desativado" });
      }

      // Validar senha - pode ser texto plano (legado) ou bcrypt hash
      let senhaValida = false;

      // Verificar se é hash bcrypt (começa com $2a$, $2b$ ou $2y$)
      if (
        dev.senha.startsWith("$2a$") ||
        dev.senha.startsWith("$2b$") ||
        dev.senha.startsWith("$2y$")
      ) {
        senhaValida = await bcrypt.compare(senha, dev.senha);
      } else {
        // Senha em texto plano (legado)
        senhaValida = senha === dev.senha;
      }

      if (!senhaValida) {
        console.log(`❌ [DEV LOGIN] Senha incorreta para: ${usuario}`);
        const _cnt = (_failedLoginAttempts.get(usuario) || 0) + 1;
        _failedLoginAttempts.set(usuario, _cnt);
        if (_cnt >= 3) _failedLoginAttempts.delete(usuario);
        return res.status(401).json({ error: "Usuário ou senha incorretos" });
      }
      _failedLoginAttempts.delete(usuario);

      console.log(`✅ [DEV LOGIN] Login bem-sucedido: ${dev.nome}`);

      const devEmail = dev.email || `${dev.usuario}@dev.clubedogrito.com`;
      const devTelefone = `+5599${String(900000000 + dev.id).slice(-9)}`;

      // 🔥 Define o papel do dev com base no cadastro
      // ajuste aqui conforme o campo que você tiver (tipo / role / usuario)
      const devRole =
        dev.tipo === "marketing" ||
          dev.role === "dev-marketing" ||
          dev.usuario === "marketing"
          ? "dev-marketing"
          : "dev";

      const existingUser = await db
        .select()
        .from(users)
        .where(or(eq(users.email, devEmail), eq(users.telefone, devTelefone)))
        .limit(1);

      let userId: number;

      if (existingUser && existingUser.length > 0) {
        await db
          .update(users)
          .set({
            nome: dev.nome,
            email: devEmail,
            telefone: devTelefone,
            role: devRole, // 👈 usa o papel calculado
            ativo: true,
            tipo: "desenvolvedor",
          })
          .where(eq(users.id, existingUser[0].id));

        userId = existingUser[0].id;
        console.log(
          `✅ [DEV LOGIN] Usuário atualizado: ${dev.nome} (ID: ${userId})`
        );
      } else {
        const newUser = await db
          .insert(users)
          .values({
            email: devEmail,
            nome: dev.nome,
            telefone: devTelefone,
            role: devRole, // 👈 usa o papel calculado
            ativo: true,
            tipo: "desenvolvedor",
            verificado: true,
          })
          .returning();

        userId = newUser[0].id;
        console.log(
          `✅ [DEV LOGIN] Novo usuário criado: ${dev.nome} (ID: ${userId})`
        );
      }

      // Atualizar último acesso
      await db
        .update(developers)
        .set({
          ultimoAcesso: new Date()
        })
        .where(eq(developers.id, dev.id));

      // Salvar na sessão
      const session = req.session as any;
      clearCrossActorSessionFields(session);
      session.isDeveloper = true;
      session.developerId = dev.id;
      session.userId = userId;
      session.userPapel = devRole; // 👈 salva 'dev' ou 'dev-marketing'
      session.telefone = "";
      session.userName = dev.nome;
      session.actorType = "desenvolvedor";

      // opcional: marca sessão ativa de dev pro front usar
      session.devSession = true;

      console.log(
        `✅ [DEV LOGIN] Sessão criada para ${dev.nome} (devId=${dev.id}, userId=${userId}, role=${devRole})`
      );

      await new Promise<void>((resolve, reject) => {
        session.save((err: Error | null) => (err ? reject(err) : resolve()));
      });

      // Retornar dados do desenvolvedor
      res.json({
        success: true,
        developer: {
          id: dev.id,
          nome: dev.nome,
          usuario: dev.usuario,
          email: dev.email,
          role: devRole, // 👈 front agora sabe o papel
        },
        userId: userId,
      });
    } catch (error: any) {
      console.error("❌ [DEV LOGIN] Erro:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Alterar senha do monitor
  app.post(
    "/api/monitor/alterar-senha",
    requireAuth,
    express.json(),
    async (req, res) => {
      try {
        const { senhaAtual, novaSenha } = req.body;

        // 🔒 SEGURANÇA: Obter monitorId da sessão autenticada
        const user = (req as any).user;
        if (!user || !user.id) {
          console.warn(
            `🚨 [SECURITY] Tentativa de alteração de senha sem autenticação`
          );
          return res.status(401).json({ error: "Não autenticado" });
        }

        const userId = user.id;

        // Validar campos obrigatórios
        if (!senhaAtual || !senhaAtual.trim()) {
          return res.status(400).json({ error: "Senha atual é obrigatória" });
        }

        if (!novaSenha || !novaSenha.trim()) {
          return res.status(400).json({ error: "Nova senha é obrigatória" });
        }

        // 🔒 VALIDAÇÃO DE COMPLEXIDADE DE SENHA
        if (novaSenha.length < 8) {
          return res.status(400).json({
            error: "Senha deve ter no mínimo 8 caracteres",
          });
        }

        if (!/[A-Z]/.test(novaSenha)) {
          return res.status(400).json({
            error: "Senha deve conter pelo menos uma letra maiúscula",
          });
        }

        if (!/[0-9]/.test(novaSenha)) {
          return res.status(400).json({
            error: "Senha deve conter pelo menos um número",
          });
        }

        // Buscar email do usuário autenticado na tabela users
        const userResult = await db
          .select()
          .from(users)
          .where(eq(users.id, userId))
          .limit(1);

        if (!userResult || userResult.length === 0) {
          console.log(`❌ [MONITOR SENHA] Usuário não encontrado: ${userId}`);
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        const userEmail = userResult[0].email;

        // 🔒 LOG DE SEGURANÇA
        console.log(
          `🔑 [MONITOR SENHA] Tentativa de alteração de senha: userId=${userId}, email=${userEmail}, timestamp=${new Date().toISOString()}`
        );

        // Buscar monitor por email na tabela monitores
        const monitorResult = await db
          .select()
          .from(monitores)
          .where(eq(monitores.email, userEmail))
          .limit(1);

        if (!monitorResult || monitorResult.length === 0) {
          console.log(
            `❌ [MONITOR SENHA] Monitor não encontrado para email: ${userEmail}`
          );
          return res.status(404).json({ error: "Monitor não encontrado" });
        }

        const monitor = monitorResult[0];

        // Validar senha atual com bcrypt
        const senhaValida = await bcrypt.compare(
          senhaAtual,
          monitor.passwordHash
        );
        if (!senhaValida) {
          console.log(
            `❌ [MONITOR SENHA] Senha atual incorreta para monitor ${monitor.id} (${monitor.email})`
          );
          return res.status(401).json({ error: "Senha atual incorreta" });
        }

        // Gerar novo hash com bcrypt
        const novoHash = bcrypt.hashSync(novaSenha, 10);

        // Atualizar monitor com novo password_hash
        await db
          .update(monitores)
          .set({ passwordHash: novoHash })
          .where(eq(monitores.id, monitor.id));

        console.log(
          `✅ 🔑 [MONITOR SENHA] Senha alterada com sucesso para monitor ${monitor.nome
          } (${monitor.email}), timestamp=${new Date().toISOString()}`
        );

        firePushRulesByTrigger("senha_alterada", senhaAlteradaVars(), undefined, userId).catch(() => { });

        res.json({
          success: true,
          message: "Senha alterada com sucesso",
        });
      } catch (error: any) {
        console.error("❌ [MONITOR SENHA] Erro:", error);
        res.status(500).json({ error: "Erro interno do servidor" });
      }
    }
  );

