  // Criar novo sorteio (admin only)
  app.post("/api/sorteio/criar", async (req, res) => {
    try {
      const sorteioData = req.body;

      // Validação básica
      if (
        !sorteioData.nome ||
        !sorteioData.premio ||
        !sorteioData.dataSorteio
      ) {
        return res
          .status(400)
          .json({ error: "Dados obrigatórios não fornecidos" });
      }

      // Verificar se já existe sorteio para o mesmo mês
      const dataSorteio = new Date(sorteioData.dataSorteio);
      const primeiroDiaDoMes = new Date(
        dataSorteio.getFullYear(),
        dataSorteio.getMonth(),
        1
      );
      const ultimoDiaDoMes = new Date(
        dataSorteio.getFullYear(),
        dataSorteio.getMonth() + 1,
        0
      );

      const sorteioExistente = await db
        .select()
        .from(sorteios)
        .where(
          and(
            sql`${sorteios.dataSorteio} >= ${primeiroDiaDoMes.toISOString()}`,
            sql`${sorteios.dataSorteio} <= ${ultimoDiaDoMes.toISOString()}`,
            eq(sorteios.ativo, true),
            eq(sorteios.status, "ativo")
          )
        )
        .limit(1);

      if (sorteioExistente.length > 0) {
        return res.status(400).json({
          error: `Já existe um sorteio ativo para ${dataSorteio.toLocaleDateString(
            "pt-BR",
            { month: "long", year: "numeric" }
          )}`,
        });
      }

      // Desativar sorteios anteriores se necessário
      await db.update(sorteios).set({ ativo: false }).where(eq(sorteios.ativo, true));

      const sorteio = await storage.createSorteio({
        nome: sorteioData.nome,
        descricao: sorteioData.descricao,
        premio: sorteioData.premio,
        dataInicio: new Date(),
        dataFim: new Date(sorteioData.dataSorteio),
        dataSorteio: new Date(sorteioData.dataSorteio),
        regras:
          sorteioData.regras ||
          "Participação automática para doadores ativos. Chances: Eco=1, Voz=2, O Grito=3, Platinum=5.",
        status: "ativo",
        tipoSorteio: "mensal",
        ativo: true,
      });

      res.json({ message: "Sorteio criado com sucesso!", sorteio });
    } catch (error) {
      console.error("Error creating sorteio:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // API para realizar sorteio de forma transparente
  app.post("/api/sorteio/:id/realizar", async (req, res) => {
    try {
      const sorteioId = parseInt(req.params.id);
      const { metodo = "automatico" } = req.body; // 'automatico' ou 'manual'

      // Verificar se sorteio existe e está ativo
      const sorteio = await storage.getSorteioById(sorteioId);
      if (!sorteio || sorteio.status !== "ativo") {
        return res
          .status(404)
          .json({ error: "Sorteio não encontrado ou inativo" });
      }

      // Buscar todas as participações confirmadas
      const participacoes = await storage.getParticipacoesPorSorteio(sorteioId);
      if (!participacoes.length) {
        return res
          .status(400)
          .json({ error: "Nenhuma participação confirmada encontrada" });
      }

      // Gerar números para cada participante baseado nas chances do plano
      let numerosDisponiveis: Array<{
        numero: number;
        userId: number;
        nome: string;
        plano: string;
      }> = [];
      let numeroAtual = 1;

      // Mapear participantes com seus números
      const participantesComNumeros = participacoes.map((participacao) => {
        const chances = participacao.numeroChances;
        const numerosParticipante = [];

        for (let i = 0; i < chances; i++) {
          numerosParticipante.push(numeroAtual);
          numerosDisponiveis.push({
            numero: numeroAtual,
            userId: participacao.userId,
            nome: participacao.nome || `Usuário ${participacao.userId}`,
            plano: participacao.planoAtual,
          });
          numeroAtual++;
        }

        return {
          ...participacao,
          numerosAtribuidos: numerosParticipante,
        };
      });

      // SORTEIO TRANSPARENTE:
      // Usar timestamp atual + Math.random() para garantir aleatoriedade
      const timestampSorteio = Date.now();
      const seed = timestampSorteio % 1000000; // Usar apenas 6 últimos dígitos para simplicidade

      // Gerar número aleatório baseado no timestamp
      const numeroSorteado =
        Math.floor(Math.random() * numerosDisponiveis.length) + 1;
      const numeroEscolhido = numerosDisponiveis[numeroSorteado - 1];

      if (!numeroEscolhido) {
        return res
          .status(500)
          .json({ error: "Erro no sorteio: número inválido" });
      }

      // Registrar resultado
      const resultado = await storage.createResultadoSorteio({
        sorteioId,
        vencedorId: numeroEscolhido.userId,
        numeroSorteado,
        planoVencedor: numeroEscolhido.plano,
        valorPremio: sorteio.valorPremio,
        dataSorteio: new Date(),
        observacoes: `Sorteio realizado ${metodo === "manual" ? "manualmente" : "automaticamente"
          } em ${new Date().toLocaleString("pt-BR")}. Seed: ${seed}`,
      });

      // Atualizar status do sorteio
      await storage.updateSorteio(sorteioId, { status: "finalizado" });

      res.json({
        message: "Sorteio realizado com sucesso!",
        resultado: {
          vencedor: numeroEscolhido.nome,
          numeroSorteado,
          totalNumeros: numerosDisponiveis.length,
          planoVencedor: numeroEscolhido.plano,
          timestampSorteio,
          seed,
          transparencia: {
            metodo: metodo,
            participantes: participantesComNumeros.length,
            totalChances: numerosDisponiveis.length,
            detalhesParticipantes: participantesComNumeros.map((p) => ({
              nome: p.nome || `Usuário ${p.userId}`,
              plano: p.planoAtual,
              chances: p.numeroChances,
              numeros: p.numerosAtribuidos,
            })),
          },
        },
      });
    } catch (error) {
      console.error("Error performing sorteio:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Buscar payment methods do usuário
  app.get("/api/users/:userId/payment-methods", async (req, res) => {
    try {
      const { userId } = req.params;

      console.log(
        `🔍 [PM ENDPOINT] Buscando payment methods para user ${userId}`
      );

      // Buscar usuário no banco para pegar stripeCustomerId
      const user = await storage.getUser(parseInt(userId));
      if (!user) {
        console.log(`❌ [PM ENDPOINT] User ${userId} não encontrado no banco`);
        return res.json({ paymentMethods: [] });
      }

      console.log(`📋 [PM ENDPOINT] User ${userId} encontrado:`, {
        nome: user.nome,
        stripeCustomerId: user.stripeCustomerId,
        stripeSubscriptionId: user.stripeSubscriptionId,
      });

      let customerId = user.stripeCustomerId;
      console.log(`🎯 [PM ENDPOINT] Customer ID inicial: ${customerId}`);

      // 🔧 FALLBACK: Se não tem customer ID mas tem subscription, buscar customer pela subscription
      if (!customerId && user.stripeSubscriptionId) {
        try {
          console.log(
            `🔄 [FALLBACK] User ${userId} sem customer ID, buscando pela subscription ${user.stripeSubscriptionId}`
          );
          const subscription = await stripe.subscriptions.retrieve(
            user.stripeSubscriptionId
          );
          customerId = subscription.customer as string;

          if (customerId) {
            // Atualizar banco com customer ID descoberto
            await storage.updateUser(parseInt(userId), {
              stripeCustomerId: customerId,
            });
            console.log(
              `✅ [FALLBACK] Customer ID ${customerId} atualizado no banco para user ${userId}`
            );
          }
        } catch (err) {
          console.log(`❌ [FALLBACK] Erro ao buscar subscription:`, err);
        }
      }

      // Se ainda não tem customer ID, retornar vazio
      if (!customerId) {
        console.log(
          `❌ [PM ENDPOINT] User ${userId} não tem customer ID após fallback`
        );
        return res.json({ paymentMethods: [] });
      }

      console.log(
        `🔍 [PM ENDPOINT] Prestes a buscar customer do Stripe: ${customerId}`
      );
      console.log(`🔍 [PM ENDPOINT] Tipo do customerId: ${typeof customerId}`);
      console.log(`🔍 [PM ENDPOINT] customerId.length: ${customerId?.length}`);

      // Buscar customer no Stripe para obter o cartão padrão
      const customer = await stripe.customers.retrieve(customerId);
      const defaultPaymentMethodId = (customer as any).invoice_settings
        ?.default_payment_method;

      console.log(
        `✅ [PM ENDPOINT] Customer ${customerId} recuperado com sucesso do Stripe`
      );
      console.log(
        `🎯 [DEFAULT CARD] Customer ${customerId} tem cartão padrão: ${defaultPaymentMethodId}`
      );

      // Buscar payment methods do cliente no Stripe
      const paymentMethods = await stripe.paymentMethods.list({
        customer: customerId,
        type: "card",
      });

      // NOVO: Se usuário tem subscription, buscar payment method da subscription também
      const allPaymentMethods = [...paymentMethods.data];

      if (user.stripeSubscriptionId) {
        try {
          const subscription = await stripe.subscriptions.retrieve(
            user.stripeSubscriptionId
          );
          const subscriptionPmId =
            subscription.default_payment_method as string;

          if (subscriptionPmId) {
            // Verificar se já está na lista
            const alreadyHas = allPaymentMethods.some(
              (pm) => pm.id === subscriptionPmId
            );

            if (!alreadyHas) {
              console.log(
                `💳 [SUBSCRIPTION PM] Encontrado payment method da subscription: ${subscriptionPmId}`
              );
              const subscriptionPm = await stripe.paymentMethods.retrieve(
                subscriptionPmId
              );
              allPaymentMethods.push(subscriptionPm);
            }
          }
        } catch (err) {
          console.log(
            `⚠️ [SUBSCRIPTION PM] Erro ao buscar payment method da subscription:`,
            err
          );
        }
      }

      // Filtrar duplicatas com prioridade para o cartão padrão
      const seenCards = new Map();
      const sortedPaymentMethods = [...allPaymentMethods].sort((a, b) => {
        // Priorizar cartão padrão
        if (a.id === defaultPaymentMethodId) return -1;
        if (b.id === defaultPaymentMethodId) return 1;
        return 0;
      });

      const uniquePaymentMethods = sortedPaymentMethods.filter((pm) => {
        const visualKey = `${pm.card?.brand}-${pm.card?.last4}-${pm.card?.exp_month}-${pm.card?.exp_year}`;

        if (seenCards.has(visualKey)) {
          const isDefault = pm.id === defaultPaymentMethodId;
          console.log(
            `🚫 [DUPLICATA] ${isDefault ? "PADRÃO" : "Normal"
            } cartão visual duplicado removido: ${visualKey} (ID: ${pm.id})`
          );
          return false;
        }

        seenCards.set(visualKey, pm.id);
        return true;
      });

      // Garantir que cartão padrão fica na primeira posição
      const reorderedCards = uniquePaymentMethods.sort((a, b) => {
        if (a.id === defaultPaymentMethodId) return -1;
        if (b.id === defaultPaymentMethodId) return 1;
        return 0;
      });

      console.log(
        `📊 [PAYMENT METHODS] Total do Stripe: ${allPaymentMethods.length}, Únicos visualmente: ${uniquePaymentMethods.length}`
      );

      if (allPaymentMethods.length !== uniquePaymentMethods.length) {
        console.log(
          `⚠️ [PAYMENT METHODS] ${allPaymentMethods.length - uniquePaymentMethods.length
          } duplicatas visuais encontradas e removidas no backend`
        );
      }

      reorderedCards.forEach((pm, index) => {
        const isDefault = pm.id === defaultPaymentMethodId;
        console.log(
          `${isDefault ? "👑" : "✅"} [${index + 1}°] ${pm.card?.brand} ••••${pm.card?.last4
          } ${pm.card?.exp_month}/${pm.card?.exp_year} (ID: ${pm.id}) ${isDefault ? "(PADRÃO)" : ""
          }`
        );
      });

      res.json({
        paymentMethods: reorderedCards.map((pm) => ({
          id: pm.id,
          brand: pm.card?.brand,
          last4: pm.card?.last4,
          exp_month: pm.card?.exp_month,
          exp_year: pm.card?.exp_year,
          funding: pm.card?.funding,
          isDefault: pm.id === defaultPaymentMethodId,
        })),
      });
    } catch (error: any) {
      res
        .status(500)
        .json({ message: "Error fetching payment methods: " + error.message });
    }
  });

