  app.post("/api/beneficios", async (req, res) => {
    try {
      const {
        titulo,
        descricao,
        icone,
        imagem, // <- URL retornada do upload
        planosDisponiveis,
        ciclosPagamento,
        pontosNecessarios,
        ativo = true,
        ordem,
        inicioLeilao,
        prazoLances,
      } = req.body;

      const pontosOk = Number.parseInt(pontosNecessarios as any, 10);
      const ordemOk = ordem == null ? 0 : Number(ordem);

      if (
        !titulo ||
        !imagem ||
        !Array.isArray(planosDisponiveis) ||
        planosDisponiveis.length === 0 ||
        Number.isNaN(pontosOk) ||
        pontosOk < 0 ||
        ordemOk < 0
      ) {
        return res.status(400).json({
          error:
            "Campos obrigatórios: titulo, imagem, planosDisponiveis[], pontosNecessarios>=0, ordem>=0",
        });
      }

      const novo = await storage.createBeneficio({
        titulo,
        descricao: descricao || "",
        icone: icone || "Package",
        imagem, // mantém para compatibilidade
        categoria: "geral",
        planosDisponiveis,
        ciclosPagamento: ciclosPagamento || ["mensal"],
        pontosNecessarios: pontosOk,
        ativo,
        ordem: ordemOk,
        inicioLeilao: inicioLeilao ? (typeof inicioLeilao === "string" ? new Date(inicioLeilao) : inicioLeilao) : null,
        prazoLances: prazoLances ? (typeof prazoLances === "string" ? new Date(prazoLances) : prazoLances) : null,
      });

      // grava também na beneficio_imagens (tipo "card")
      const imagemKey = (imagem as string).startsWith("http")
        ? extractFilePathFromUrl(imagem as string)
        : (imagem as string);
      const fileName = imagemKey.split("/").pop() || "unknown";
      await storage.createBeneficioImagem({
        beneficioId: novo.id,
        tipo: "card",
        nomeArquivo: fileName,
        caminhoCompleto: imagemKey, // URL completa do GCS
        nomeOriginal: fileName,
        tipoMime: "image/jpeg",
        tamanhoBytes: 0,
        largura: null,
        altura: null,
        ativo: true,
      });

      // Disparar notificação push automática para doadores
      try {
        const fireRules = (app as any)._firePushRulesByTrigger;
        if (fireRules) {
          fireRules("novo_beneficio", { titulo: novo.titulo || "" });
        }
      } catch (e) { /* silencioso */ }

      res.status(201).json(novo);
    } catch (error) {
      console.error("Error creating beneficio:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

