  // ✅ PRODUCTION-SAFE: Lance em benefício com TODAS as validações críticas implementadas
  app.post("/api/beneficios/:id/lance", requireAuth, async (req, res) => {
    const userAuth = (req as any).user;
    // ✅ declare fora pra não quebrar no catch
    let beneficioId: number | undefined;
    let userIdForLog: number | undefined;

    const transacaoId =
      (req.headers["x-transaction-id"] as string) ||
      req.body.transacaoId ||
      `tx_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    try {
      beneficioId = parseInt(req.params.id);
      userIdForLog = userAuth?.id || req.body.userId;

      // ✅ CRÍTICO 1: VALIDAÇÃO ZOD OBRIGATÓRIA - previne dados inválidos
      const validationResult = validarLanceSchema.safeParse({
        beneficioId,
        valorLance: req.body.pontosOfertados || req.body.valorLance,
        userId: userIdForLog,
      });

      if (!validationResult.success) {
        return res.status(400).json({
          success: false,
          message: "Dados de entrada inválidos",
          errors: validationResult.error.errors,
        });
      }

      const { valorLance, userId } = validationResult.data;
      userIdForLog = userId; // ✅ garante que no catch fica preenchido
      const { aumentarLance } = req.body;


      // ✅ CRÍTICO 2: TRANSAÇÃO ATÔMICA COM STATE MACHINE E CONCORRÊNCIA SEGURA
      const result = await db.transaction(async (tx) => {
        console.log("🔄 [PRODUCTION-SAFE-TX] Iniciando transação crítica:", {
          beneficioId,
          userId,
          valorLance,
          transacaoId,
        });

        // ✅ CRÍTICO 3: VERIFICAÇÃO DE DUPLICATAS (previne lances múltiplos do mesmo usuário)
        const existingLance = await tx
          .select()
          .from(beneficioLances)
          .where(
            and(
              eq(beneficioLances.userId, userId),
              eq(beneficioLances.beneficioId, beneficioId)
            )
          )
          .limit(1);

        if (existingLance.length > 0 && !aumentarLance) {
          console.log(
            "✅ [DUPLICATE-PROTECTION] Lance já existe para este usuário/benefício"
          );
          return {
            success: false,
            message: "Você já deu seu lance neste benefício",
          };
        }

        // ✅ CRÍTICO 4: VERIFICAR BENEFÍCIO COM LOCK + STATE MACHINE
        const [beneficio] = await tx
          .select()
          .from(beneficios)
          .where(eq(beneficios.id, beneficioId))
          .for("update") // SELECT FOR UPDATE previne race conditions
          .limit(1);

        if (!beneficio) {
          throw new Error("Benefício não encontrado");
        }

        // ✅ CRÍTICO 5: VERIFICAR SE BENEFÍCIO ESTÁ ATIVO
        console.log(
          `🔍 [LANCE] Benefício ${beneficioId} - ativo: ${beneficio.ativo}`
        );

        if (!beneficio.ativo) {
          console.log(`❌ [LANCE] Benefício ${beneficioId} não está ativo`);
          throw new Error("Benefício não está disponível para lances");
        }

        // ✅ CRÍTICO 6: VERIFICAR PRAZO DE LANCES
        const agora = new Date();
        const prazoLances = beneficio.prazoLances
          ? new Date(beneficio.prazoLances)
          : null;

        if (prazoLances && agora >= prazoLances) {
          console.log(
            `❌ [LANCE] Prazo expirado - agora: ${agora.toISOString()}, prazo: ${prazoLances.toISOString()}`
          );
          throw new Error("Prazo para lances já expirou");
        }

        console.log(
          `✅ [LANCE] Benefício ${beneficioId} está disponível para lances`
        );

        // ✅ CRÍTICO 7: USUÁRIO COM LOCK ATÔMICO
        const [user] = await tx
          .select()
          .from(users)
          .where(eq(users.id, userId))
          .for("update"); // FOR UPDATE para lock
        if (!user) {
          throw new Error("Usuário não encontrado");
        }

        // ✅ CRÍTICO 7.5: VERIFICAR ELEGIBILIDADE DO PLANO + PERIODICIDADE
        const planoUsuario = user.plano || "eco";
        const periodicidadeUsuario = user.periodicity || "mensal";
        // Normalizar para lowercase
        const userPlan = (planoUsuario || "").toLowerCase();
        const userPeriodicidade = (periodicidadeUsuario || "").toLowerCase();

        // Normalizar arrays do benefício (suportar ambos os formatos)
        const planosBeneficio = (
          (beneficio as any).planosDisponiveis ||
          (beneficio as any).planos_disponiveis ||
          []
        ).map((p: string) => p.toLowerCase());
        const ciclosBeneficio = (
          (beneficio as any).ciclosPagamento ||
          (beneficio as any).ciclos_pagamento || ["mensal"]
        ).map((c: string) => c.toLowerCase());

        // Verificar se o plano do usuário está nos planos permitidos (platinum vê tudo)
        const planAllowed =
          userPlan === "platinum" || planosBeneficio.includes(userPlan);
        if (!planAllowed) {
          console.log(
            `❌ [LANCE] Plano ${userPlan} não permitido para este prêmio. Planos: ${planosBeneficio}`
          );
          throw new Error(
            `Seu plano (${planoUsuario}) não tem acesso a este prêmio. Faça upgrade para participar!`
          );
        }

        // Verificar se a periodicidade do usuário está nos ciclos permitidos
        if (!ciclosBeneficio.includes(userPeriodicidade)) {
          console.log(
            `❌ [LANCE] Periodicidade ${userPeriodicidade} não permitida para este prêmio. Ciclos: ${ciclosBeneficio}`
          );
          throw new Error(
            `Sua periodicidade (${periodicidadeUsuario}) não permite acesso a este prêmio. Considere mudar para ${ciclosBeneficio[0]} ou superior!`
          );
        }

        console.log(
          `✅ [LANCE] Usuário elegível: plano=${planoUsuario}, periodicidade=${periodicidadeUsuario}`
        );

        // ✅ CRÍTICO 8: VERIFICAÇÕES DE NEGÓCIO ATÔMICAS
        const gritosAtuais = user.gritosTotal || 0;
        if (gritosAtuais < valorLance) {
          throw new Error(
            `Gritos insuficientes. Você tem ${gritosAtuais} gritos, mas precisa de ${valorLance}`
          );
        }

        // Verificar lance mínimo
        const lanceMinimo = beneficio.gritosMinimos || 1;
        if (valorLance < lanceMinimo) {
          throw new Error(`Lance deve ser no mínimo ${lanceMinimo} gritos`);
        }

        // ✅ CRÍTICO 9: PROCESSAMENTO BASEADO EM aumentarLance
        if (aumentarLance) {
          console.log("📈 [PRODUCTION-SAFE-TX] Processando aumento de lance");
          // Buscar lance existente COM LOCK
          const lanceExistente = await tx
            .select()
            .from(beneficioLances)
            .where(
              and(
                eq(beneficioLances.userId, userId),
                eq(beneficioLances.beneficioId, beneficioId),
                eq(beneficioLances.status, "ativo")
              )
            )
            .for("update")
            .limit(1);

          if (!lanceExistente.length) {
            throw new Error("Você não possui lance ativo neste benefício");
          }

          const pontosAnteriores = lanceExistente[0].pontosOfertados;

          if (valorLance <= pontosAnteriores) {
            throw new Error(
              `Novo lance deve ser maior que ${pontosAnteriores} pontos`
            );
          }

          // Calcular diferença de pontos
          const diferencaPontos = valorLance - pontosAnteriores;

          if (gritosAtuais < diferencaPontos) {
            throw new Error(
              `Gritos insuficientes para aumentar lance. Precisa de ${diferencaPontos} gritos adicionais`
            );
          }

          // ✅ CRÍTICO 10: ATUALIZAÇÃO ATÔMICA COM TIMESTAMP UTC
          await tx
            .update(beneficioLances)
            .set({
              pontosOfertados: valorLance,
              updatedAt: sql`NOW() AT TIME ZONE 'UTC'`,
            })
            .where(eq(beneficioLances.id, lanceExistente[0].id));

          // Descontar apenas a diferença
          const novosGritos = gritosAtuais - diferencaPontos;
          await tx
            .update(users)
            .set({
              gritosTotal: novosGritos
            })
            .where(eq(users.id, userId));

          // Registrar no histórico (valor negativo para desconto da diferença)
          await tx.insert(gritosHistorico).values({
            userId,
            tipo: "aumento_lance",
            gritosGanhos: -diferencaPontos,
            descricao: `Aumento de lance no benefício: ${beneficio.titulo}`,
            dataGanho: new Date(),
          });

          console.log(
            `✅ [PRODUCTION-SAFE-TX] Lance aumentado: ${pontosAnteriores} → ${valorLance} (diferença: ${diferencaPontos}, registrado no histórico)`
          );

          return {
            success: true,
            message: `Lance aumentado com sucesso! ${pontosAnteriores} → ${valorLance} pontos`,
            lanceId: lanceExistente[0].id,
            gritosRestantes: novosGritos,
            pontosOfertados: valorLance,
            transacaoId,
          };
        } else {
          console.log("🆕 [PRODUCTION-SAFE-TX] Processando novo lance");

          // Verificar se já tem lance ativo COM LOCK
          const lanceExistente = await tx
            .select()
            .from(beneficioLances)
            .where(
              and(
                eq(beneficioLances.userId, userId),
                eq(beneficioLances.beneficioId, beneficioId),
                eq(beneficioLances.status, "ativo")
              )
            )
            .for("update")
            .limit(1);

          if (lanceExistente.length > 0) {
            throw new Error(
              "Você já tem um lance ativo neste benefício. Use 'aumentarLance' para modificar."
            );
          }

          // ✅ CRÍTICO 11: CRIAR LANCE COM VALIDAÇÕES COMPLETAS
          const [novoLance] = await tx
            .insert(beneficioLances)
            .values({
              userId,
              beneficioId,
              pontosOfertados: valorLance,
              status: "ativo",
              createdAt: sql`NOW() AT TIME ZONE 'UTC'`,
              updatedAt: sql`NOW() AT TIME ZONE 'UTC'`,
            })
            .returning();

          // Descontar gritos COM VERIFICAÇÃO ATÔMICA
          const novosGritos = gritosAtuais - valorLance;
          await tx
            .update(users)
            .set({
              gritosTotal: novosGritos
            })
            .where(eq(users.id, userId));

          // Registrar no histórico (valor negativo para desconto)
          await tx.insert(gritosHistorico).values({
            userId,
            tipo: "lance_beneficio",
            gritosGanhos: -valorLance,
            descricao: `Lance no benefício: ${beneficio.titulo}`,
            dataGanho: new Date(),
          });

          console.log(
            `✅ [PRODUCTION-SAFE] Novo lance criado: ${valorLance} pontos (descontado do histórico)`
          );

          return {
            success: true,
            message: `Lance realizado com sucesso! ${valorLance} pontos ofertados`,
            lanceId: novoLance.id,
            gritosRestantes: novosGritos,
            pontosOfertados: valorLance,
            transacaoId,
          };
        }
      });

      console.log("✅ [PRODUCTION-SAFE] Transação crítica concluída:", result);

      // Disparar notificação push automática para doadores (novo lance)
      if (result?.success) {
        try {
          const fireRules = (app as any)._firePushRulesByTrigger;
          if (fireRules) {
            const tituloBeneficioRes = await pool
              .query<{ titulo: string }>("SELECT titulo FROM beneficios WHERE id = $1 LIMIT 1", [beneficioId])
              .catch(() => ({ rows: [] as { titulo: string }[] }));
            const tituloBeneficio = tituloBeneficioRes.rows[0]?.titulo || "";
            const valorStr = String(result.pontosOfertados || 0);
            // Broadcast aos demais doadores, exceto quem deu o lance (3º arg = excludeUserKey)
            fireRules("novo_lance_leilao", { titulo: tituloBeneficio, valor: valorStr }, String(userId));
            fireRules(
              "lance_recebido",
              { valor: valorStr, leilao: tituloBeneficio },
              undefined,
              userId
            );
            // gritos utilizados — notificação pessoal para o próprio usuário
            const _saldoAtual = await pool.query('SELECT "gritosTotal" FROM users WHERE id = $1 LIMIT 1', [userId]).catch(() => ({ rows: [] }));
            fireRules("gritos_utilizados", { quantidade_gritos: String(result.pontosOfertados || 0), saldo_gritos: String(_saldoAtual.rows[0]?.gritosTotal ?? 0), beneficio: String(beneficioId) }, undefined, userId);
            // lance_superado: notificar quem era o líder anterior
            try {
              const prevLider = await pool.query(
                `SELECT user_id FROM beneficio_lances WHERE beneficio_id = $1 AND user_id != $2 AND status = 'ativo' ORDER BY pontos_ofertados DESC LIMIT 1`,
                [beneficioId, userId]
              );
              if (prevLider.rows.length > 0) {
                fireRules("lance_superado", { valor: String(result.pontosOfertados || 0) }, undefined, prevLider.rows[0].user_id);
              }
            } catch { }
          }
        } catch (e) { /* silencioso */ }
      }

      res.json(result);
    } catch (error: any) {
      console.error("❌ [PRODUCTION-SAFE] Erro crítico na transação:", {
        error: error?.message || error,
        beneficioId: beneficioId ?? req.params.id,
        userId: userIdForLog ?? userAuth?.id,
        transacaoId,
        timestamp: new Date().toISOString(),
      });

      // ✅ CRÍTICO 12: ERROR HANDLING PRODUCTION-SAFE
      const isDuplicateTransaction =
        error?.message?.includes("duplicate") ||
        error?.message?.includes("unique");

      if (isDuplicateTransaction) {
        return res.status(409).json({
          success: false,
          message: "Transação duplicada detectada",
          code: "DUPLICATE_TRANSACTION",
          transacaoId,
        });
      }

      // Status específicos para diferentes tipos de erro
      const statusCode = error?.message?.includes("não está ativo")
        ? 409
        : error?.message?.includes("expirou")
          ? 410
          : error?.message?.includes("insuficientes")
            ? 402
            : 400;

      return res.status(statusCode).json({
        success: false,
        message: error?.message || "Erro interno do servidor",
        code: "TRANSACTION_FAILED",
        transacaoId,
      });
    }
  });
  // Verificar se usuário já participou de um benefício
