  // Endpoint para estatísticas detalhadas de um benefício
  app.get("/api/beneficios/:id/estatisticas", async (req, res) => {
    try {
      const beneficioId = parseInt(req.params.id);

      const sessionUser = (req as any).user;
      const userId =
        sessionUser?.id != null ? parseInt(String(sessionUser.id), 10) : null;

      console.log(
        `📊 [ESTATÍSTICAS] Buscando dados para benefício ${beneficioId}, usuário ${userId}`
      );

      // ✅ 1. Buscar dados reais do benefício
      const beneficio = await storage.getBeneficio(beneficioId);
      if (!beneficio) {
        return res.status(404).json({ message: "Benefício não encontrado" });
      }

      // ✅ 2. Buscar todos os lances reais do benefício
      const todosLances = await storage.getBeneficioLancesByBeneficio(
        beneficioId
      );

      // Filtrar apenas lances ativos
      const lancesAtivos = todosLances.filter(
        (lance) => lance.status === "ativo"
      );

      // ✅ 3. Calcular total de lances reais
      const totalLances = lancesAtivos.length;

      // ✅ 4. Calcular tempo restante real baseado em prazoLances
      let tempoRestante = { horas: 0, minutos: 0, segundos: 0 };
      let lanceEncerrado = false; // Se não há prazo, lance está aberto

      if (beneficio.prazoLances) {
        const agora = new Date();
        const prazoFim = new Date(beneficio.prazoLances);
        const diferenca = prazoFim.getTime() - agora.getTime();

        if (diferenca > 0) {
          // Prazo ainda não expirou

          lanceEncerrado = false;
          const horas = Math.floor(diferenca / (1000 * 60 * 60));
          const minutos = Math.floor(
            (diferenca % (1000 * 60 * 60)) / (1000 * 60)
          );
          const segundos = Math.floor((diferenca % (1000 * 60)) / 1000);

          tempoRestante = { horas, minutos, segundos };
        } else {
          // Prazo expirou
          lanceEncerrado = true;
        }
      }

      // ✅ 5. Se não há lances, retornar dados básicos
      if (totalLances === 0) {
        return res.json({
          totalLances: 0,
          posicaoUsuario: null,
          top3Lances: [],
          tempoRestante,
          lanceEncerrado,
          gritosMinimos: beneficio.gritosMinimos || 1,
          lanceUsuario: null,
        });
      }
      // ✅ 6. AGRUPAR POR USUÁRIO: Pegar apenas o maior lance de cada usuário
      // Primeiro, criar um mapa de userId -> maior lance
      const maiorLancePorUsuario = new Map<number, (typeof lancesAtivos)[0]>();
      for (const lance of lancesAtivos) {
        const lanceAtual = maiorLancePorUsuario.get(lance.userId);
        if (!lanceAtual || lance.pontosOfertados > lanceAtual.pontosOfertados) {
          maiorLancePorUsuario.set(lance.userId, lance);
        }
      }

      // Converter para array e ordenar do maior para menor
      const lancesAgrupados = Array.from(maiorLancePorUsuario.values());
      const lancesOrdenados = lancesAgrupados.sort(
        (a, b) => b.pontosOfertados - a.pontosOfertados
      );

      // Total de participantes únicos (não de lances totais)
      const totalParticipantes = lancesOrdenados.length;

      // ✅ 7. Buscar informações dos usuários para os top 3 lances
      const top3LancesData = [];
      for (let i = 0; i < Math.min(3, lancesOrdenados.length); i++) {
        const lance = lancesOrdenados[i];
        try {
          const user = await storage.getUser(lance.userId);
          const nomeCompleto = user
            ? `${user.nome} ${user.sobrenome || ""}`.trim()
            : "Usuário Anônimo";

          top3LancesData.push({
            posicao: i + 1,
            nome: nomeCompleto,
            pontos: lance.pontosOfertados,
            isUsuario: userId === lance.userId,
          });
        } catch (err) {
          console.error(`❌ Erro ao buscar usuário ${lance.userId}:`, err);
          top3LancesData.push({
            posicao: i + 1,
            nome: "Usuário Anônimo",
            pontos: lance.pontosOfertados,
            isUsuario: userId === lance.userId,
          });
        }
      }

      // ✅ 8. Calcular posição do usuário e buscar seu lance
      let posicaoUsuario: number | null = null;
      let lanceUsuario: any = null;

      if (userId) {
        // Encontrar o MAIOR lance do usuário (usando dados agregados)
        const lanceDoUsuario = maiorLancePorUsuario.get(userId);

        if (lanceDoUsuario) {
          // Calcular posição do usuário usando a lista ordenada (já agregada)
          posicaoUsuario =
            lancesOrdenados.findIndex((lance) => lance.userId === userId) + 1;

          lanceUsuario = {
            pontos: lanceDoUsuario.pontosOfertados,
            dataLance: lanceDoUsuario.createdAt || new Date().toISOString(),
          };
        }
      }

      const estatisticas = {
        totalLances: totalParticipantes, // Retornar participantes únicos, não total de lances
        posicaoUsuario,
        top3Lances: top3LancesData,
        tempoRestante,
        lanceEncerrado,
        gritosMinimos: beneficio.gritosMinimos || 1,
        lanceUsuario,
      };

      console.log(`📊 [ESTATÍSTICAS REAIS] Benefício ${beneficioId}:`, {
        totalParticipantes,
        posicaoUsuario,
        lanceEncerrado,
        prazoLances: beneficio.prazoLances,
      });

      res.json(estatisticas);
    } catch (error) {
      console.error("❌ [ESTATÍSTICAS] Erro:", error);
      res.status(500).json({ message: "Erro interno do servidor" });
    }
  });

