  // POST /api/instances/:id/enrollments - Criar nova inscrição em uma turma
  app.post("/api/instances/:id/enrollments", requireAuth, async (req, res) => {
    try {
      const instanceId = parseInt(req.params.id);
      console.log(`📝 [ENROLLMENT PEC] Criando inscrição — InstanceId: "${req.params.id}", Aluno: "${req.body?.student_name || req.body?.student_cpf || 'não informado'}"`);

      if (isNaN(instanceId)) {
        console.warn(`⚠️ [ENROLLMENT PEC] ID de turma inválido — valor recebido: "${req.params.id}"`);
        return res.status(400).json({ error: `ID de turma inválido: "${req.params.id}" não é um número válido.` });
      }

      const coordenadorId = req.user?.id;

      const enrollmentData = { ...req.body, activity_instance_id: instanceId };
      const enrollment = await storage.createEnrollment(enrollmentData);

      // 🔗 VINCULAÇÃO AUTOMÁTICA COM PSICOSSOCIAL
      try {
        // Verificar se já existe vínculo
        const vinculoExistente = await db
          .select()
          .from(psicoPecVinculo)
          .where(eq(psicoPecVinculo.enrollmentId, enrollment.id))
          .limit(1);

        if (vinculoExistente.length === 0) {
          const alunoNome = enrollment.student_name || "Aluno PEC";

          // Criar família no Psicossocial
          const [novaFamilia] = await db
            .insert(psicoFamilias)
            .values({
              nomeResponsavel: alunoNome,
              numeroMembros: 1,
              telefone: enrollment.telefone_contato || null,
              endereco: null,
              status: "ativo",
              coordenadorId: coordenadorId
                ? parseInt(coordenadorId.toString())
                : null,
              observacoes: `Família criada automaticamente - PEC: ${alunoNome}`,
            })
            .returning();

          // Criar vínculo
          await db.insert(psicoPecVinculo).values({
            enrollmentId: enrollment.id,
            psicoFamiliaId: novaFamilia.id,
            papel: "atendido",
            observacoes: "Vínculo criado automaticamente ao cadastrar no PEC",
          });

          console.log(
            `✅ [PEC→PSICO] Aluno ${enrollment.id} vinculado automaticamente à família ${novaFamilia.id}`
          );
        } else {
          console.log(
            `ℹ️ [PEC→PSICO] Aluno ${enrollment.id} já possui vínculo psicossocial`
          );
        }
      } catch (vinculoError) {
        console.error(
          "⚠️ [PEC→PSICO] Erro ao criar vínculo automático (enrollment continuou):",
          vinculoError
        );
      }
      console.log(`✅ [ENROLLMENT PEC] Inscrição criada — EnrollmentId: ${enrollment.id}, InstanceId: ${instanceId}`);
      try {
        const fr = (app as any)._firePushRulesByTrigger;
        if (fr && enrollment.student_cpf) {
          const alunoTarget = resolveAlunoPushTarget({ studentCpf: enrollment.student_cpf });
          if (alunoTarget) {
            fr(
              "turma_aluno_alterada",
              { turma: String(instanceId), aluno: enrollment.student_name || enrollment.student_cpf || "" },
              undefined,
              undefined,
              alunoTarget.targetUserKey
            );
          }
        }
      } catch { }
      res.status(201).json(enrollment);
    } catch (error: any) {
      console.error(`❌ [ENROLLMENT PEC] Erro ao criar inscrição`);
      console.error(`   → InstanceId : ${req.params.id}`);
      console.error(`   → Aluno CPF  : ${req.body?.student_cpf || 'não informado'}`);
      console.error(`   → Aluno Nome : ${req.body?.student_name || 'não informado'}`);
      console.error(`   → Código PG  : ${error?.code || 'n/a'}`);
      console.error(`   → Constraint : ${error?.constraint || 'n/a'}`);
      console.error(`   → Detalhe    : ${error?.detail || 'n/a'}`);
      console.error(`   → Erro       : ${error?.message || error}`);
      const pgErr = formatPostgresError(error, 'inscrição PEC');
      res.status(pgErr.status).json({ error: pgErr.message });
    }
  });

