  // POST /api/pec/instances/:id/finalizar - Finalizar turma PEC (formados x reprovados)
  app.post("/api/pec/instances/:id/finalizar", async (req, res) => {
    try {
      const turmaId = parseInt(req.params.id);
      const { alunosConcluidosCpfs } = req.body;

      if (!Array.isArray(alunosConcluidosCpfs)) {
        return res.status(400).json({ error: "alunosConcluidosCpfs deve ser um array" });
      }

      const [turma] = await db
        .select({ id: activityInstances.id, title: activityInstances.title })
        .from(activityInstances)
        .where(eq(activityInstances.id, turmaId))
        .limit(1);
      if (!turma) {
        return res.status(404).json({ error: "Turma não encontrada" });
      }

      const sessoes = await db
        .select({ id: sessions.id })
        .from(sessions)
        .where(eq(sessions.activity_instance_id, turmaId))
        .limit(1);
      if (sessoes.length === 0) {
        return res.status(400).json({
          error: `Não é possível finalizar a turma "${turma.title}". Nenhuma sessão/chamada foi registrada.`,
        });
      }

      await db
        .update(activityInstances)
        .set({ situation: "encerrada" as any, updated_at: new Date() })
        .where(eq(activityInstances.id, turmaId));

      const cpfsLimpos = alunosConcluidosCpfs
        .map((c: string) => String(c || "").replace(/\D/g, ""))
        .filter(Boolean);

      if (cpfsLimpos.length > 0) {
        await db
          .update(instanceEnrollments)
          .set({ status: "concluido" })
          .where(
            and(
              eq(instanceEnrollments.activity_instance_id, turmaId),
              inArray(instanceEnrollments.student_cpf, cpfsLimpos)
            )
          );
      }

      await db
        .update(instanceEnrollments)
        .set({ status: "reprovado" })
        .where(
          and(
            eq(instanceEnrollments.activity_instance_id, turmaId),
            eq(instanceEnrollments.status, "ativo")
          )
        );

      res.json({
        success: true,
        message: "Turma finalizada com sucesso",
        alunosConcluidos: cpfsLimpos.length,
      });
    } catch (error: any) {
      console.error("Erro ao finalizar turma PEC:", error);
      res.status(500).json({ error: "Erro ao finalizar turma" });
    }
  });

