  // POST /api/educadores - Cadastrar novo educador
  app.post("/api/educadores", async (req, res) => {
    try {
      const educadorData = req.body;
      console.log("👨‍🏫 Creating educador:", {
        nome: educadorData.nome_completo,
        cpf: educadorData.cpf,
      });

      // Validar campos obrigatórios
      if (!educadorData.cpf) {
        return res.status(400).json({ error: "O CPF do educador é obrigatório." });
      }
      if (!educadorData.nome_completo) {
        return res.status(400).json({ error: "O nome completo do educador é obrigatório." });
      }
      if (!educadorData.telefone) {
        return res.status(400).json({ error: "O telefone do educador é obrigatório." });
      }

      // Verificar se CPF já existe
      const existingEducador = await storage.getEducadorByCpf(educadorData.cpf);
      if (existingEducador) {
        return res.status(409).json({
          error: "Já existe um educador cadastrado com este CPF.",
        });
      }

      const educador = await storage.createEducador(educadorData);
      console.log("✅ Educador created:", educador.id);

      // Vincular educador ao programa PEC automaticamente
      try {
        const vinculo = await storage.createEducadorPrograma({
          educador_id: educador.id,
          programa: "pec",
          cargo: educadorData.especialidades?.[0] || "educador",
          status: "ativo",
        });
        console.log("✅ Educador vinculado ao programa PEC:", vinculo.id);

        res.status(201).json({
          ...educador,
          vinculo_programa: vinculo,
        });
      } catch (vinculoError) {
        // Se falhar ao criar o vínculo, logar erro mas retornar o educador criado
        console.error(
          "⚠️ Erro ao vincular educador ao programa PEC:",
          vinculoError
        );
        res.status(201).json({
          ...educador,
          warning:
            "Educador criado mas não foi possível vincular ao programa PEC automaticamente",
        });
      }
    } catch (error) {
      console.error("❌ Error creating educador:", error);
      const pgErr = formatPostgresError(error, 'educador');
      res.status(pgErr.status).json({ error: pgErr.message });
    }
  });

  // PUT /api/educadores/:id - Atualizar educador
  app.put("/api/educadores/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const educadorData = req.body;
      console.log(`👨‍🏫 Updating educador ${id}:`, {
        nome: educadorData.nome_completo,
        cpf: educadorData.cpf,
      });

      // Validar campos obrigatórios
      if (!educadorData.nome_completo) {
        return res.status(400).json({ error: "O nome completo do educador é obrigatório." });
      }
      if (!educadorData.telefone) {
        return res.status(400).json({ error: "O telefone do educador é obrigatório." });
      }

      // Verificar se educador existe
      const educadorExistente = await storage.getEducadorById(id);
      if (!educadorExistente) {
        return res.status(404).json({ error: "Educador não encontrado" });
      }

      // Atualizar educador
      const educadorAtualizado = await storage.updateEducador(id, educadorData);
      console.log(`✅ Educador ${id} atualizado com sucesso`);

      res.json({
        success: true,
        message: "Educador atualizado com sucesso",
        educador: educadorAtualizado,
      });
    } catch (error: any) {
      console.error("❌ Error updating educador:", error);
      const pgErr = formatPostgresError(error, 'educador');
      res.status(pgErr.status).json({ error: pgErr.message });
    }
  });

  // POST /api/educadores/:id/programa - Vincular educador a um programa
  app.post("/api/educadores/:id/programa", async (req, res) => {
    try {
      const educadorId = parseInt(req.params.id);
      const { programa, cargo } = req.body;

      if (isNaN(educadorId)) {
        return res.status(400).json({ error: "ID de educador inválido" });
      }

      if (!programa) {
        return res.status(400).json({ error: "Campo programa é obrigatório" });
      }

      console.log(
        `🔗 Vinculando educador ${educadorId} ao programa ${programa}`
      );

      const vinculo = await storage.createEducadorPrograma({
        educador_id: educadorId,
        programa,
        cargo: cargo || "Educador",
      });

      console.log("✅ Vínculo criado:", vinculo.id);
      res.status(201).json(vinculo);
    } catch (error) {
      console.error("❌ Error creating educador-programa link:", error);
      res.status(500).json({
        error: "Erro ao vincular educador ao programa",
        details: error.message,
      });
    }
  });

  // GET /api/educadores/:id - Buscar educador por ID
  app.get("/api/educadores/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      if (isNaN(id)) {
        return res.status(400).json({ error: "ID inválido" });
      }

      const educador = await storage.getEducadorById(id);
      if (!educador) {
        return res.status(404).json({ error: "Educador não encontrado" });
      }

      res.json(educador);
    } catch (error) {
      console.error("❌ Error fetching educador:", error);
      res.status(500).json({ error: "Erro ao buscar educador" });
    }
  });

  // ===== PATROCINADORES (TABELA) =====
  app.get("/api/patrocinadores", async (req, res) => {
    try {
      // Parâmetro de filtro por mês (0 = Janeiro, 11 = Dezembro)
      const mesParam =
        req.query.mes !== undefined
          ? parseInt(req.query.mes as string)
          : undefined;
      const ano = parseInt(req.query.ano as string) || new Date().getFullYear();

      let patrocinadoresList = await storage.getPatrocinadores(ano);

      // Filtrar por mês se especificado
      if (mesParam !== undefined && mesParam >= 0 && mesParam <= 11) {
        const anoAtual = 2025;
        const dataFimMes = new Date(anoAtual, mesParam + 1, 0);
        const dataInicioMes = new Date(anoAtual, mesParam, 1);

        patrocinadoresList = patrocinadoresList.filter((p: any) => {
          // Patrocinador ativo no mês se: data_inicio <= fim do mês E (data_fim >= início do mês OU data_fim é null)
          const dataInicio = p.dataInicio
            ? new Date(p.dataInicio)
            : new Date(0);
          const dataFim = p.dataFim ? new Date(p.dataFim) : null;

          const iniciadoAntesOuDuranteMes = dataInicio <= dataFimMes;
          const naoTerminouAntes = !dataFim || dataFim >= dataInicioMes;

          return iniciadoAntesOuDuranteMes && naoTerminouAntes;
        });
        console.log(
          `📅 [PATROCINADORES] Filtrado por mês ${mesParam + 1}/${anoAtual}: ${patrocinadoresList.length
          } patrocinadores`
        );
      }

      const totalPatrocinadores = patrocinadoresList.length;

      res.json({
        ano,
        totalPatrocinadores,
        patrocinadores: patrocinadoresList,
      });
    } catch (error) {
      console.error("❌ Error fetching patrocinadores:", error);
      res.status(500).json({ error: "Erro ao buscar patrocinadores" });
    }
  });

