  // ===== INGRESSO - CRIAR PAYMENT INTENT =====
  app.post("/api/ingresso/create-payment", async (req, res) => {
    try {
      const { nome, telefone, amount } = req.body;

      if (!nome || !telefone || !amount) {
        return res
          .status(400)
          .json({ error: "Nome, telefone e valor são obrigatórios" });
      }

      // Validar quantidade (deve estar entre 1 e 5)
      if (!Number.isInteger(quantidade) || quantidade < 1 || quantidade > 5) {
        return res
          .status(400)
          .json({ error: "Quantidade deve ser um número inteiro entre 1 e 5" });
      }

      // Criar PaymentIntent no Stripe
      const paymentIntent = await stripe.paymentIntents.create({
        amount: amount, // Já vem em centavos (valor total = unitário * quantidade)
        currency: "brl",
        automatic_payment_methods: {
          enabled: true,
        },
        metadata: {
          tipo: "ingresso_2026",
          nome: nome,
          telefone: telefone,
          quantidade: quantidade.toString(),
          produto: `Ingresso${quantidade > 1 ? "s" : ""
            } Premium - Instituto O Grito 2026`,
        },
        description: `${quantidade} Ingresso${quantidade > 1 ? "s" : ""
          } Premium - ${nome} (${telefone})`,
      });

      console.log(
        `💳 [INGRESSO STRIPE] PaymentIntent criado: ${paymentIntent.id
        } para ${nome} - R$ ${amount / 100}`
      );

      res.json({
        success: true,
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
      });
    } catch (error) {
      console.error("❌ [INGRESSO STRIPE] Erro ao criar PaymentIntent:", error);
      res.status(500).json({ error: "Erro ao criar pagamento" });
    }
  });

