  // 📊 GET /api/marketing-seguidores-mensal - Dados mensais de seguidores
  app.get("/api/marketing-seguidores-mensal", async (req, res) => {
    try {
      const ano = parseInt(req.query.ano as string) || new Date().getFullYear();
      console.log(`📊 [SEGUIDORES-MENSAL] Buscando dados para ${ano}...`);

      const now = new Date();
      const currentYear = now.getFullYear();
      const currentMonth = now.getMonth() + 1;

      if (ano === currentYear) {
        try {
          const subscriptions = await stripe.subscriptions.list({ status: "active", limit: 100 });
          const trialingSubscriptions = await stripe.subscriptions.list({ status: "trialing", limit: 100 });
          const liveDoadores = subscriptions.data.length + trialingSubscriptions.data.length;

          const existsCheck = await db.execute(sql`
            SELECT id FROM marketing_seguidores_mensal WHERE ano = ${currentYear} AND mes = ${currentMonth} LIMIT 1
          `);

          if (existsCheck.rows.length > 0) {
            await db.execute(sql`
              UPDATE marketing_seguidores_mensal SET doadores_ativos = ${liveDoadores}, updated_at = NOW()
              WHERE ano = ${currentYear} AND mes = ${currentMonth}
            `);
          } else {
            const prevMonth = await db.execute(sql`
              SELECT total_seguidores FROM marketing_seguidores_mensal 
              WHERE ano = ${currentMonth === 1 ? currentYear - 1 : currentYear} AND mes = ${currentMonth === 1 ? 12 : currentMonth - 1}
              LIMIT 1
            `);
            const prevTotal = prevMonth.rows.length > 0 ? Number((prevMonth.rows[0] as any).total_seguidores) : 0;

            await db.execute(sql`
              INSERT INTO marketing_seguidores_mensal (ano, mes, seguidores_ganhos, seguidores_perdidos, total_seguidores, materiais_distribuidos, doadores_ativos, updated_at)
              VALUES (${currentYear}, ${currentMonth}, 0, 0, ${prevTotal}, 0, ${liveDoadores}, NOW())
              ON CONFLICT (ano, mes) DO NOTHING
            `);
            console.log(`📊 [SEGUIDORES-MENSAL] Criado registro automático para ${currentMonth}/${currentYear} com ${liveDoadores} doadores ativos`);
          }
        } catch (stripeErr) {
          console.error("⚠️ [SEGUIDORES-MENSAL] Erro ao buscar doadores live:", stripeErr);
        }
      }

      const result = await db.execute(sql`
        SELECT * FROM marketing_seguidores_mensal 
        WHERE ano = ${ano} 
        ORDER BY mes ASC
      `);

      res.json({ success: true, data: result.rows });
    } catch (error) {
      console.error("❌ [SEGUIDORES-MENSAL] Erro ao buscar:", error);
      res.status(500).json({ success: false, error: "Erro ao buscar dados mensais" });
    }
  });

  // 📊 POST /api/marketing-seguidores-mensal - Criar/atualizar dados mensais
  app.post("/api/marketing-seguidores-mensal", async (req, res) => {
    try {
      const { ano, mes, seguidores_ganhos, seguidores_perdidos, materiais_distribuidos } = req.body;

      if (!ano || !mes) {
        return res.status(400).json({ success: false, error: "Ano e mês são obrigatórios" });
      }

      const ganhos = seguidores_ganhos || 0;
      const perdidos = seguidores_perdidos || 0;

      console.log(`📊 [SEGUIDORES-MENSAL] Salvando dados para ${ano}/${mes}...`);

      const prevMonth = await db.execute(sql`
        SELECT total_seguidores FROM marketing_seguidores_mensal 
        WHERE ano = ${mes === 1 ? ano - 1 : ano} AND mes = ${mes === 1 ? 12 : mes - 1}
        LIMIT 1
      `);
      const prevTotal = prevMonth.rows.length > 0 ? Number(prevMonth.rows[0].total_seguidores) : 0;
      const computedTotal = prevTotal > 0 ? prevTotal + ganhos - perdidos : (ganhos - perdidos);

      let doadoresAtivos = 0;
      try {
        const subscriptions = await stripe.subscriptions.list({ status: "active", limit: 100 });
        const trialingSubscriptions = await stripe.subscriptions.list({ status: "trialing", limit: 100 });
        doadoresAtivos = subscriptions.data.length + trialingSubscriptions.data.length;
        console.log(`📊 [SEGUIDORES-MENSAL] Doadores ativos do Stripe: ${doadoresAtivos}`);
      } catch (stripeErr) {
        console.error("⚠️ [SEGUIDORES-MENSAL] Erro ao buscar doadores do Stripe:", stripeErr);
      }

      await db.execute(sql`
        INSERT INTO marketing_seguidores_mensal (ano, mes, seguidores_ganhos, seguidores_perdidos, total_seguidores, materiais_distribuidos, doadores_ativos, updated_at)
        VALUES (${ano}, ${mes}, ${ganhos}, ${perdidos}, ${computedTotal}, ${materiais_distribuidos || 0}, ${doadoresAtivos}, NOW())
        ON CONFLICT (ano, mes) DO UPDATE SET
          seguidores_ganhos = EXCLUDED.seguidores_ganhos,
          seguidores_perdidos = EXCLUDED.seguidores_perdidos,
          total_seguidores = EXCLUDED.total_seguidores,
          materiais_distribuidos = EXCLUDED.materiais_distribuidos,
          doadores_ativos = EXCLUDED.doadores_ativos,
          updated_at = NOW()
      `);

      res.json({ success: true, message: `Dados de ${mes}/${ano} salvos com sucesso`, total_seguidores: computedTotal, doadores_ativos: doadoresAtivos });
    } catch (error) {
      console.error("❌ [SEGUIDORES-MENSAL] Erro ao salvar:", error);
      res.status(500).json({ success: false, error: "Erro ao salvar dados mensais" });
    }
  });

  // 📊 GET /api/gestao-vista/evolucao-mensal - Dados de evolução mensal para gráfico
  // Usa os mesmos dados do módulo gestaoVistaData (mesma fonte da tela do doador)
  app.get("/api/gestao-vista/evolucao-mensal", async (req, res) => {
    try {
      const ano = (req.query.ano as string) || "2025";
      console.log(`📊 [EVOLUCAO] Buscando dados mensais para ${ano}...`);

      const meses = [
        "Jan",
        "Fev",
        "Mar",
        "Abr",
        "Mai",
        "Jun",
        "Jul",
        "Ago",
        "Set",
        "Out",
        "Nov",
        "Dez",
      ];

      // Para 2025, usar dados do gestaoVistaData (mesma fonte da tela do doador)
      if (ano === "2025") {
        const { dadosMensais2025 } = gestaoVistaData;

        const dados = meses.map((mes, idx) => ({
          mes,
          visitas: dadosMensais2025.visitasDomicilio[idx] ?? 0,
          atendimentos: dadosMensais2025.atendimentosPsico[idx] ?? 0,
        }));

        res.json({ success: true, ano, dados });
      } else if (ano === '2026') {
        // Para 2026, buscar dados em tempo real do banco
        const dadosMensais: Array<{ mes: string; visitas: number; atendimentos: number; alunosFormados: number; criancasAtendidas: number; alunosEmFormacao: number; frequencia: number }> = [];

        for (let i = 0; i < 12; i++) {
          const mesNum = i + 1;
          try {
            const indicadores = await gestaoVistaData.getIndicadores2026(mesNum);
            dadosMensais.push({
              mes: meses[i],
              visitas: indicadores.visitasDomicilio,
              atendimentos: indicadores.atendimentosPsico,
              alunosFormados: indicadores.alunosFormados,
              criancasAtendidas: indicadores.criancasAtendidas,
              alunosEmFormacao: indicadores.alunosEmFormacao,
              frequencia: indicadores.frequencia
            });
          } catch (err) {
            dadosMensais.push({ mes: meses[i], visitas: 0, atendimentos: 0, alunosFormados: 0, criancasAtendidas: 0, alunosEmFormacao: 0, frequencia: 0 });
          }
        }

        res.json({ success: true, ano, dados: dadosMensais });
      } else {
        // Para outros anos, retornar zeros
        const dados = meses.map((mes) => ({
          mes,
          visitas: 0,
          atendimentos: 0,
        }));

        res.json({ success: true, ano, dados });
      }
    } catch (error) {
      console.error("❌ [EVOLUCAO] Erro:", error);
      res.status(500).json({ success: false, error: "Erro ao buscar dados" });
    }
  });

  // 📊 GET /api/gestao-vista/turmas-ativas-pec - Turmas ativas PEC por projeto
  // ── GESTÃO À VISTA: Favela 3D KPIs ──────────────────────────────────
  app.get('/api/gestao-vista/favela3d', async (req, res) => {
    try {
      const anoParam = req.query.ano ? parseInt(req.query.ano as string) : new Date().getFullYear();
      const mesParam = req.query.mes !== undefined && req.query.mes !== 'todos' ? parseInt(req.query.mes as string) : null;
      const fav3dTrimestre = req.query.trimestre ? parseInt(req.query.trimestre as string) : null;
      const fav3dMesInicio = req.query.mesInicio ? parseInt(req.query.mesInicio as string) : null;
      const fav3dMesFim = req.query.mesFim ? parseInt(req.query.mesFim as string) : null;
      const fav3dRangeValid = !fav3dTrimestre && fav3dMesInicio !== null && fav3dMesFim !== null &&
        fav3dMesInicio >= 1 && fav3dMesInicio <= 12 && fav3dMesFim >= 1 && fav3dMesFim <= 12 && fav3dMesInicio <= fav3dMesFim;

      const filtraMes = !fav3dRangeValid && mesParam !== null && mesParam >= 1 && mesParam <= 12;
      const filtraTrimestre = fav3dTrimestre !== null && fav3dTrimestre >= 1 && fav3dTrimestre <= 4;
      const filtraRange = fav3dRangeValid;
      const rangeMesInicio = filtraRange ? fav3dMesInicio! : 0;
      const rangeMesFim = filtraRange ? fav3dMesFim! : 0;
      const hoje = new Date();

      // Datas para os filtros (mesParam é 1-indexado vindo do frontend: Jan=1, Abr=4...)
      const inicioMes = filtraMes ? new Date(anoParam, mesParam! - 1, 1) : null;
      const fimMesReal = filtraMes ? new Date(anoParam, mesParam!, 0, 23, 59, 59) : null;
      // Para acumulados: limita ao dia de hoje (mês futuro = sem dados ainda)
      const fimMesAcumulado = filtraMes ? (fimMesReal! > hoje ? hoje : fimMesReal!) : null;
      // Se o mês inteiro ainda não começou, não há dados
      const mesFuturo = filtraMes && inicioMes! > hoje;

      // Trimestre: fim acumulado = último dia do trimestre (ou hoje se ainda não fechou)
      // T1=Mar(mês3), T2=Jun(mês6), T3=Set(mês9), T4=Dez(mês12)
      // new Date(ano, t*3, 0) = último dia do mês t*3 (ex: T1 → new Date(2026,3,0) = 31/mar)
      const fimTrimestreReal = filtraTrimestre ? new Date(anoParam, fav3dTrimestre! * 3, 0, 23, 59, 59) : null;
      const fimTrimestreAcum = filtraTrimestre ? (fimTrimestreReal! > hoje ? hoje : fimTrimestreReal!) : null;
      const trimFuturo = filtraTrimestre && new Date(anoParam, (fav3dTrimestre! - 1) * 3, 1) > hoje;

      // Filtros por tipo de dado
      // registros/visitas: ocorreram naquele mês (data exata) — futuro retorna 0 naturalmente
      const registroFilter = filtraTrimestre
        ? `status IS DISTINCT FROM 'inativo' AND EXTRACT(YEAR FROM data) = ${anoParam} AND EXTRACT(MONTH FROM data) BETWEEN ${(fav3dTrimestre! - 1) * 3 + 1} AND ${fav3dTrimestre! * 3}`
        : filtraRange
          ? `status IS DISTINCT FROM 'inativo' AND EXTRACT(YEAR FROM data) = ${anoParam} AND EXTRACT(MONTH FROM data) BETWEEN ${rangeMesInicio} AND ${rangeMesFim}`
          : filtraMes
            ? `status IS DISTINCT FROM 'inativo' AND EXTRACT(YEAR FROM data) = ${anoParam} AND EXTRACT(MONTH FROM data) = ${mesParam!}`
            : `status IS DISTINCT FROM 'inativo' AND EXTRACT(YEAR FROM data) = ${anoParam}`;

      // famílias/IGF: acumulado até o fim do mês/trimestre (ou hoje se ainda não fechou)
      const fimRangeReal = filtraRange ? new Date(anoParam, rangeMesFim, 0, 23, 59, 59) : null;
      const fimRangeAcum = filtraRange && fimRangeReal ? (fimRangeReal > hoje ? hoje : fimRangeReal) : null;
      const rangeFuturo = filtraRange && new Date(anoParam, rangeMesInicio - 1, 1) > hoje;

      const participanteFilter = mesFuturo
        ? `FALSE`
        : trimFuturo
          ? `FALSE`
          : rangeFuturo
            ? `FALSE`
            : filtraMes
              ? `status IS DISTINCT FROM 'inativo' AND created_at <= '${fimMesAcumulado!.toISOString()}'`
              : filtraTrimestre
                ? `status IS DISTINCT FROM 'inativo' AND created_at <= '${fimTrimestreAcum!.toISOString()}'`
                : filtraRange
                  ? `status IS DISTINCT FROM 'inativo' AND created_at <= '${fimRangeAcum!.toISOString()}'`
                  : `status IS DISTINCT FROM 'inativo'`;

      // membros do grupo: estavam no grupo até o fim do mês
      const membroFilter = mesFuturo
        ? `FALSE`
        : filtraMes
          ? `m.criado_em <= '${fimMesAcumulado!.toISOString()}'`
          : `TRUE`;

      // encontros: ocorreram naquele mês
      const reuniaoFilter = filtraMes
        ? `r.data >= '${inicioMes!.toISOString().slice(0, 10)}' AND r.data <= '${fimMesReal!.toISOString().slice(0, 10)}'`
        : `TRUE`;

      const result = await pool.query(`
        SELECT
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter}) AS familias,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo != 'visita_domiciliar') AS registros,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'visita_domiciliar') AS visitas,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'atendimento_individual') AS atendimentos_individuais,
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter} AND igf IN ('E1','E2')) AS igf_alta,
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter} AND igf IN ('P1','P2')) AS igf_media,
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter} AND igf = 'D') AS igf_baixa,
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter} AND tem_bolsa_familia = 'sim') AS bolsa_familia,
          (SELECT COUNT(*)::int FROM favela3d_participantes WHERE ${participanteFilter} AND tem_cad_unico = 'sim') AS cad_unico,
          (SELECT COALESCE(SUM(COALESCE(criancas,0) + COALESCE(adolescentes,0) + COALESCE(adultos,0) + COALESCE(idosos,0)), 0)::int FROM favela3d_participantes WHERE ${participanteFilter}) AS pessoas_mapeadas,
          (SELECT COUNT(DISTINCT m.participante_id)::int FROM favela3d_grupos g LEFT JOIN favela3d_grupo_membros m ON m.grupo_id = g.id WHERE g.nome ILIKE '%mulheres%' AND ${membroFilter}) AS mulheres_pessoas,
          (SELECT COUNT(*)::int FROM favela3d_reunioes r JOIN favela3d_grupos g ON g.id = r.grupo_id WHERE g.nome ILIKE '%mulheres%' AND ${reuniaoFilter}) AS mulheres_encontros,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'atendimento_coletivo') AS total_coletivos,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'gerando_lideranca') AS gerando_lideranca,
          (SELECT COUNT(DISTINCT pid)::int FROM favela3d_registros, LATERAL unnest(participantes_ids) AS pid WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'gerando_lideranca') AS gerando_lideranca_pessoas,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'assembleia') AS assembleia,
          (SELECT COUNT(DISTINCT pid)::int FROM favela3d_registros, LATERAL unnest(participantes_ids) AS pid WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'assembleia') AS assembleia_pessoas,
          (SELECT COUNT(*)::int FROM favela3d_registros WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'grupo_mulheres') AS grupo_mulheres,
          (SELECT COUNT(DISTINCT pid)::int FROM favela3d_registros, LATERAL unnest(participantes_ids) AS pid WHERE ${registroFilter} AND tipo = 'atendimento_coletivo' AND categoria = 'grupo_mulheres') AS grupo_mulheres_pessoas
      `);
      res.json(result.rows[0] || {});
    } catch (e: any) {
      console.error('gestao-vista/favela3d:', e);
      res.status(500).json({ error: 'Erro ao buscar KPIs Favela 3D' });
    }
  });

  app.get('/api/gestao-vista/turmas-ativas-pec', async (req, res) => {
    try {
      const result = await pool.query(`
        SELECT p.name as projeto, COUNT(ai.id)::int as total
        FROM activity_instances ai
        JOIN pec_activities pa ON ai.activity_id = pa.id
        JOIN projects p ON pa.project_id = p.id
        WHERE ai.situation IN ('execucao', 'planejamento')
        GROUP BY p.id, p.name
        ORDER BY total DESC
      `);

      const porProjeto = result.rows.map((r: any) => ({
        projeto: r.projeto,
        total: r.total,
      }));
      const totalAtivas = porProjeto.reduce((s: number, r: any) => s + r.total, 0);

      res.json({ success: true, totalAtivas, porProjeto });
    } catch (error) {
      console.error('[TURMAS-ATIVAS-PEC]', error);
      res.status(500).json({ success: false, error: 'Erro ao buscar turmas ativas' });
    }
  });

  // =========  POST /api/user-causas  =========
  // Endpoint para salvar a escolha de "Grito" do usuário
  app.post("/api/user-causas", async (req, res) => {
    try {
      const { telefone, causa } = req.body;

      if (!telefone || !causa) {
        return res.status(400).json({
          success: false,
          message: "Telefone e causa são obrigatórios",
        });
      }

      // TRECHO ALTERADO
      // Buscar usuário pelo telefone
      // TRECHO ANTIGO
      // const normalizedPhone = telefone.startsWith('+') ? telefone : `+55${telefone}`;

      // NOVO TRECHO:
      const digits = String(telefone).replace(/\D/g, "");
      const normalizedPhone = `+${digits.startsWith("55") ? digits : "55" + digits
        }`;

      const user = await db
        .select()
        .from(users)
        .where(eq(users.telefone, normalizedPhone))
        .limit(1);

      if (!user[0]) {
        return res.status(404).json({
          success: false,
          message: "Usuário não encontrado",
        });
      }

      // Verificar se já existe uma causa para este usuário (substitui se existir)
      const existingCausa = await db
        .select()
        .from(userCausas)
        .where(eq(userCausas.userId, user[0].id))
        .limit(1);

      if (existingCausa[0]) {
        // Atualizar causa existente
        await db.update(userCausas)
          .set({ causa })
          .where(eq(userCausas.userId, user[0].id));
      } else {
        // Inserir nova causa
        await db.insert(userCausas).values({
          userId: user[0].id,
          causa,
        });
      }

      console.log(
        `✅ [USER CAUSAS] Salvou causa "${causa}" para usuário ID ${user[0].id}`
      );

      res.json({
        success: true,
        message: "Causa salva com sucesso",
      });
    } catch (error) {
      console.error("❌ [USER CAUSAS] Erro ao salvar causa:", error);
      res.status(500).json({
        success: false,
        message: "Erro interno do servidor",
      });
    }
  });

