  // Criar nova turma
  app.post("/api/turmas-inclusao", async (req, res) => {
    try {
      const professorId = req.user?.id;

      // Gerar código automaticamente: TI-AAAA-XXXX (Turma Inclusão - Ano - Sequencial)
      const ano = new Date().getFullYear();
      const countResult = await pool.query("SELECT COUNT(*) as total FROM turmas_inclusao WHERE EXTRACT(YEAR FROM created_at) = $1", [ano]);
      const sequencial = (parseInt(countResult.rows[0]?.total || 0) + 1).toString().padStart(4, "0");
      const codigoGerado = `TI-${ano}-${sequencial}`;

      const turmaData = {
        ...req.body,
        professorId,
        codigo: codigoGerado,
        numeroVagas: parseInt(req.body.numeroVagas || req.body.vagas) || 20,
        vagasOcupadas: 0,
      };

      // Salvar a turma no banco de dados
      const novaTurma = await storage.createTurmaInclusao(turmaData);
      console.log("Turma inclusao criada:", novaTurma.id);
      try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("turma_criada", { nome: novaTurma.nome || "" }); } catch { }
      res.status(201).json(novaTurma);
    } catch (error: any) {
      console.error("Erro ao criar turma inclusao:", error);
      res.status(500).json({ error: "Erro ao criar turma" });
    }
  });
  // Atualizar turma
  app.patch("/api/turmas-inclusao/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const updateData = { ...req.body };
      console.log(`📝 [TURMAS] Atualizando turma ${id} com diasSemana:`, updateData.diasSemana);

      // Se a turma está sendo reaberta (voltando de concluido/finalizado para ativo/em_andamento),
      // reativa todos os participantes para que apareçam corretamente no modal de finalizar.
      const statusAtivos = ['ativo', 'em_andamento', 'em andamento', 'emandamento', 'andamento', 'ativo', 'em_execucao', 'execucao'];
      const statusFinalizados = ['concluido', 'finalizado', 'encerrado', 'encerrada'];
      if (updateData.status && statusAtivos.includes(updateData.status.toLowerCase())) {
        const turmaAtual = await db.select({ status: turmasInclusao.status }).from(turmasInclusao).where(eq(turmasInclusao.id, id)).limit(1);
        const statusAnterior = (turmaAtual[0]?.status || '').toLowerCase();
        if (statusFinalizados.includes(statusAnterior)) {
          await db.update(participantesTurmas)
            .set({ status: 'ativo' })
            .where(eq(participantesTurmas.turmaId, id));
          console.log(`♻️ [TURMAS] Turma ${id} reaberta: participantes reativados para 'ativo'`);
        }
      }

      const turma = await storage.updateTurmaInclusao(id, updateData);
      try { const fr = (app as any)._firePushRulesByTrigger; if (fr) fr("turma_alterada", { nome: turma?.nome || String(id) }, undefined, undefined, undefined, { vertente: "inclusao" }); } catch { }
      res.json(turma);
    } catch (error: any) {
      console.error("Erro ao atualizar turma:", error);
      res.status(500).json({ error: "Erro ao atualizar turma" });
    }
  });

