  app.post("/api/turmas-inclusao/:id/finalizar", async (req, res) => {
    try {
      const turmaId = parseInt(req.params.id);
      const { participantesConcluidosIds } = req.body;

      if (!Array.isArray(participantesConcluidosIds)) {
        return res.status(400).json({ error: "participantesConcluidosIds deve ser um array" });
      }

      // Verificar se existem chamadas registradas para esta turma
      const turmaInfo = await db.select({ dataInicio: turmasInclusao.dataInicio, dataFim: turmasInclusao.dataFim, nome: turmasInclusao.nome })
        .from(turmasInclusao).where(eq(turmasInclusao.id, turmaId)).limit(1);
      if (!turmaInfo[0]) {
        return res.status(404).json({ error: "Turma não encontrada" });
      }
      const diasComChamada = await db.execute(sql`
        SELECT DISTINCT data FROM presencas_inclusao
        WHERE turma_id = ${turmaId}
        ORDER BY data ASC
      `);
      const diasRegistrados = (diasComChamada.rows || []).map((r: any) => {
        const d = r.data instanceof Date ? r.data : new Date(r.data);
        return d.toISOString().slice(0, 10);
      });
      if (diasRegistrados.length === 0) {
        return res.status(400).json({
          error: `Não é possível finalizar a turma "${turmaInfo[0].nome}". Nenhuma chamada foi registrada. Lance pelo menos uma chamada antes de finalizar.`,
        });
      }

      // Atualizar status da turma para concluido
      await db.update(turmasInclusao)
        .set({ status: "concluido", updatedAt: new Date() })
        .where(eq(turmasInclusao.id, turmaId));

      // Atualizar status dos participantes selecionados para concluido
      if (participantesConcluidosIds.length > 0) {
        await db.update(participantesTurmas)
          .set({ status: "concluido" })
          .where(
            and(
              eq(participantesTurmas.turmaId, turmaId),
              inArray(participantesTurmas.participanteId, participantesConcluidosIds)
            )
          );
      }

      // Marcar os demais como reprovado (não formou — não é evasão)
      await db.update(participantesTurmas)
        .set({ status: "reprovado" })
        .where(
          and(
            eq(participantesTurmas.turmaId, turmaId),
            eq(participantesTurmas.status, "ativo")
          )
        );

      // ✅ Auto-inativação: sincronizar status de TODOS os participantes da turma
      const todosParticipantesIds = await db
        .select({ participanteId: participantesTurmas.participanteId })
        .from(participantesTurmas)
        .where(eq(participantesTurmas.turmaId, turmaId));

      let inativados = 0;
      for (const { participanteId } of todosParticipantesIds) {
        const novoStatus = await syncParticipanteInclusaoStatus(participanteId);
        if (novoStatus === 'inativo') inativados++;
      }
      console.log(`✅ [FINALIZAR TURMA] Turma ${turmaId} concluída. Participantes sincronizados: ${todosParticipantesIds.length}, inativados: ${inativados}`);

      res.json({
        success: true,
        message: "Turma finalizada com sucesso",
        alunosConcluidos: participantesConcluidosIds.length,
        alunosInativados: inativados
      });
    } catch (error: any) {
      console.error("Erro ao finalizar turma:", error);
      res.status(500).json({ error: "Erro ao finalizar turma" });
    }
  });

  // ==================== EXCEÇÕES DE AULAS - INCLUSÃO PRODUTIVA ====================

  // GET /api/turmas-inclusao/:id/dias-aula — retorna datas reais de aulas da turma
  app.get("/api/turmas-inclusao/:id/dias-aula", requireAuth, async (req, res) => {
    try {
      const turmaId = parseInt(req.params.id);
      if (isNaN(turmaId)) return res.status(400).json({ error: "turmaId inválido" });

      const [turma] = await db.select({
        diasSemana: turmasInclusao.diasSemana,
        dataInicio: turmasInclusao.dataInicio,
        dataFim: turmasInclusao.dataFim,
      }).from(turmasInclusao).where(eq(turmasInclusao.id, turmaId)).limit(1);

      if (!turma) return res.status(404).json({ error: "Turma não encontrada" });

      const datas = new Set<string>();

      // 1) Datas das presenças já registradas
      const presencas = await db.execute(sql`
        SELECT DISTINCT data FROM presencas_inclusao
        WHERE turma_id = ${turmaId} ORDER BY data ASC
      `);
      for (const row of presencas.rows as any[]) {
        const raw = row.data;
        const ymd = raw instanceof Date
          ? raw.toISOString().slice(0, 10)
          : String(raw ?? "").split("T")[0].slice(0, 10);
        if (ymd) datas.add(ymd);
      }

      // 2) Datas calculadas pelo calendário da turma (dias_semana + data_inicio + data_fim)
      const normalizeDiaSemana = (dia: string): string =>
        String(dia || "")
          .trim()
          .toLowerCase()
          .normalize("NFD")
          .replace(/[\u0300-\u036f]/g, "");

      const diaSemanaMap: Record<string, number> = {
        domingo: 0,
        segunda: 1,
        "segunda-feira": 1,
        terca: 2,
        "terca-feira": 2,
        quarta: 3,
        "quarta-feira": 3,
        quinta: 4,
        "quinta-feira": 4,
        sexta: 5,
        "sexta-feira": 5,
        sabado: 6,
      };
      if (turma.diasSemana?.length && turma.dataInicio && turma.dataFim) {
        const diasAlvo = (turma.diasSemana as string[])
          .map((d) => diaSemanaMap[normalizeDiaSemana(d)])
          .filter((n): n is number => n !== undefined);
        const inicio = parseDateLocal(turma.dataInicio);
        const fim = parseDateLocal(turma.dataFim);
        if (inicio && fim) {
          for (let d = new Date(inicio); d <= fim; d.setDate(d.getDate() + 1)) {
            if (diasAlvo.includes(d.getDay())) {
              datas.add(toYMDString(d));
            }
          }
        }
      }

      const sorted = Array.from(datas).sort().reverse(); // mais recentes primeiro
      res.json({ dias: sorted });
    } catch (error: any) {
      console.error("Erro ao buscar dias de aula:", error);
      res.status(500).json({ error: "Erro ao calcular dias de aula" });
    }
  });

