  // Criar novo plano de aula
  app.post("/api/professor/:userId/planos-aula", async (req, res) => {
    try {
      const professorId = parseInt(req.params.userId);
      const vertente = normalizeVertente((req.query.vertente as string) || req.body?.vertente);
      const { turmaId, data, titulo, objetivos, conteudo, metodologia, recursos, avaliacao, duracaoMinutos, status } = req.body;

      const turmaIdNum = parseInt(turmaId);
      const allowedTurmaIds = await getProfessorTurmaIdsForVertente(professorId, vertente as "pec" | "inclusao");
      if (!allowedTurmaIds.includes(turmaIdNum)) {
        return res.status(403).json({ error: "Você não tem permissão para criar plano nesta turma." });
      }

      // Bloquear duplicidade: apenas 1 plano por turma por data (independente do professor)
      const existente = await db
        .select({ id: planoAula.id })
        .from(planoAula)
        .where(and(eq(planoAula.turmaId, turmaIdNum), eq(planoAula.data, data)))
        .limit(1);

      if (existente.length > 0) {
        return res.status(409).json({
          error: "Já existe um plano de aula cadastrado para esta turma nesta data. Edite o plano existente em vez de criar um novo."
        });
      }

      const [novoPlano] = await db.insert(planoAula).values({
        professorId,
        turmaId: turmaIdNum,
        data,
        titulo,
        objetivos,
        conteudo,
        metodologia,
        recursos: recursos || null,
        avaliacao: avaliacao || null,
        duracaoMinutos: duracaoMinutos ? parseInt(duracaoMinutos) : null,
        status: status || 'rascunho'
      }).returning();

      res.status(201).json({ ...novoPlano, status: statusPlanoParaApi(novoPlano.status) });
    } catch (error: any) {
      console.error("Erro ao criar plano de aula:", error);
      res.status(500).json({ error: "Erro ao criar plano de aula" });
    }
  });

  // Atualizar plano de aula
  app.put("/api/professor/:userId/planos-aula/:planoId", async (req, res) => {
    try {
      const planoId = parseInt(req.params.planoId);
      const { turmaId, data, titulo, objetivos, conteudo, metodologia, recursos, avaliacao, duracaoMinutos, status } = req.body;

      const existente = await db
        .select({ id: planoAula.id })
        .from(planoAula)
        .where(and(
          eq(planoAula.turmaId, parseInt(turmaId)),
          eq(planoAula.data, data),
          ne(planoAula.id, planoId)
        ))
        .limit(1);

      if (existente.length > 0) {
        return res.status(409).json({
          error: "Já existe um plano de aula cadastrado para esta turma nesta data. Edite o plano existente em vez de criar um novo."
        });
      }

      const [planoAtualizado] = await db
        .update(planoAula)
        .set({
          turmaId: parseInt(turmaId),
          data,
          titulo,
          objetivos,
          conteudo,
          metodologia,
          recursos: recursos || null,
          avaliacao: avaliacao || null,
          duracaoMinutos: duracaoMinutos ? parseInt(duracaoMinutos) : null,
          status: status || 'rascunho',
          updatedAt: new Date()
        })
        .where(and(eq(planoAula.id, planoId), eq(planoAula.professorId, parseInt(req.params.userId))))
        .returning();

      if (!planoAtualizado) {
        return res.status(403).json({ error: "Você não tem permissão para editar este plano de aula." });
      }

      res.json({ ...planoAtualizado, status: statusPlanoParaApi(planoAtualizado.status) });
    } catch (error: any) {
      console.error("Erro ao atualizar plano de aula:", error);
      res.status(500).json({ error: "Erro ao atualizar plano de aula" });
    }
  });

