  // Adicionar participante a uma turma
  // Obter participantes de uma turma específica
  app.get("/api/turmas-inclusao/:turmaId/participantes", async (req, res) => {
    try {
      const turmaId = parseInt(req.params.turmaId);
      const dateFilter = req.query.date as string | undefined;
      const params: (number | string)[] = [turmaId];
      let dateWhere = "";
      if (dateFilter) {
        params.push(dateFilter);
        dateWhere = `
          AND COALESCE(pt.status, 'ativo') = 'ativo'
          AND (pt.data_ingresso IS NULL OR pt.data_ingresso <= $${params.length}::date)
          AND (iev.id IS NULL OR iev.data_desligamento > $${params.length}::date)`;
      }
      const result = await pool.query(
        `
        WITH turma AS (
          SELECT id, nome, codigo FROM turmas_inclusao WHERE id = $1
        ),
        pec_instance AS (
          SELECT ie.activity_instance_id
          FROM participantes_turmas pt
          JOIN participantes_inclusao pi ON pi.id = pt.participante_id
          JOIN instance_enrollments ie ON regexp_replace(COALESCE(ie.student_cpf, ''), '[^0-9]', '', 'g')
            = regexp_replace(COALESCE(pi.cpf, ''), '[^0-9]', '', 'g')
            AND length(regexp_replace(COALESCE(pi.cpf, ''), '[^0-9]', '', 'g')) > 0
            AND length(regexp_replace(COALESCE(ie.student_cpf, ''), '[^0-9]', '', 'g')) > 0
          WHERE pt.turma_id = $1
          GROUP BY ie.activity_instance_id
          ORDER BY COUNT(*) DESC
          LIMIT 1
        ),
        pec_by_meta AS (
          SELECT ai.id AS activity_instance_id
          FROM turma t
          JOIN activity_instances ai ON (
            (t.codigo IS NOT NULL AND t.codigo <> '' AND ai.code = t.codigo)
            OR ai.title ILIKE '%' || t.nome || '%'
            OR ai.title ILIKE '%' || regexp_replace(t.nome, '^LAB - ', '') || '%'
          )
          LIMIT 1
        ),
        pec AS (
          SELECT activity_instance_id FROM pec_instance
          UNION
          SELECT activity_instance_id FROM pec_by_meta
          LIMIT 1
        )
        SELECT
          pi.id,
          pi.nome,
          pi.cpf,
          pi.telefone,
          pi.data_nascimento AS "dataNascimento",
          pt.id AS "participanteTurmaId",
          COALESCE(pt.status, 'ativo') AS status,
          (iev.id IS NOT NULL) AS "evasaoAtiva",
          iev.data_desligamento::text AS "dataEvasao",
          iev.id AS "evasaoId",
          COALESCE(ie.evadido, false) AS "evadidoPec",
          pe_pec.data_desligamento::text AS "dataEvasaoPec"
        FROM participantes_turmas pt
        JOIN participantes_inclusao pi ON pi.id = pt.participante_id
        LEFT JOIN inclusao_evasoes iev ON iev.participante_turma_id = pt.id AND iev.revertido_em IS NULL
        LEFT JOIN pec ON true
        LEFT JOIN instance_enrollments ie ON ie.activity_instance_id = pec.activity_instance_id
          AND length(regexp_replace(COALESCE(pi.cpf, ''), '[^0-9]', '', 'g')) > 0
          AND length(regexp_replace(COALESCE(ie.student_cpf, ''), '[^0-9]', '', 'g')) > 0
          AND regexp_replace(COALESCE(ie.student_cpf, ''), '[^0-9]', '', 'g')
            = regexp_replace(COALESCE(pi.cpf, ''), '[^0-9]', '', 'g')
        LEFT JOIN pec_evasoes pe_pec ON pe_pec.enrollment_id = ie.id AND pe_pec.revertido_em IS NULL
        WHERE pt.turma_id = $1
        ${dateWhere}
        ORDER BY pi.nome ASC
        `,
        params
      );
      res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
      res.json(result.rows.map((row: any) => ({
        ...row,
        evasaoAtiva: row.evasaoAtiva === true,
        evasaoId: row.evasaoId ?? null,
      })));
    } catch (error: any) {
      console.error("Erro ao buscar participantes da turma:", error);
      res.status(500).json({ error: "Erro ao buscar participantes da turma" });
    }
  });

