  app.get("/api/negocios-sociais/entrada", ...requireNegociosSociaisEditor, async (req, res) => {
    try {
      const ano = parseInt(req.query.ano as string) || new Date().getFullYear();
      const mes = req.query.mes ? parseInt(req.query.mes as string) : null;
      if (mes === null) {
        // Anual: retorna a SOMA de todos os meses salvos para o ano
        const r = await pool.query(`
          SELECT
            COALESCE(SUM(outlet_doacoes_recebidas),0) as outlet_doacoes_recebidas,
            COALESCE(SUM(outlet_pecas_vendidas),0) as outlet_pecas_vendidas,
            COALESCE(SUM(outlet_clientes_atendidos),0) as outlet_clientes_atendidos,
            COALESCE(SUM(cacambas_do_bem),0) as cacambas_do_bem,
            COALESCE(SUM(outlet_lives_realizadas),0) as outlet_lives_realizadas,
            COALESCE(SUM(griffte_clientes_atendidos),0) as griffte_clientes_atendidos,
            COALESCE(SUM(griffte_pedidos_entregues),0) as griffte_pedidos_entregues,
            COALESCE(SUM(griffte_pecas_confeccionadas),0) as griffte_pecas_confeccionadas,
            COALESCE(SUM(outlet_valor_vendas),0) as outlet_valor_vendas,
            COALESCE(SUM(griffte_valor_vendas),0) as griffte_valor_vendas
          FROM negocios_sociais_dados WHERE ano=$1 AND mes IS NOT NULL
        `, [ano]);
        const row = r.rows[0];
        // Se todos os campos forem 0 e não houver meses salvos, retorna null
        const hasMeses = await pool.query(
          `SELECT COUNT(*) as cnt FROM negocios_sociais_dados WHERE ano=$1 AND mes IS NOT NULL`, [ano]
        );
        if (parseInt(hasMeses.rows[0].cnt) === 0) return res.json(null);
        return res.json(row);
      }
      const r = await pool.query(
        `SELECT outlet_doacoes_recebidas, outlet_pecas_vendidas, outlet_clientes_atendidos,
                cacambas_do_bem, outlet_lives_realizadas,
                griffte_clientes_atendidos, griffte_pedidos_entregues, griffte_pecas_confeccionadas,
                COALESCE(outlet_valor_vendas,0) as outlet_valor_vendas,
                COALESCE(griffte_valor_vendas,0) as griffte_valor_vendas
         FROM negocios_sociais_dados WHERE ano=$1 AND mes=$2 LIMIT 1`,
        [ano, mes]
      );
      res.json(r.rows[0] || null);
    } catch (e: any) { res.status(500).json({ error: e.message }); }
  });

