  app.get(
    "/api/admin/beneficios/:id/top-licitantes",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const beneficioId = parseInt(req.params.id);

        if (isNaN(beneficioId)) {
          return res
            .status(400)
            .json({ success: false, message: "ID de benefício inválido" });
        }

        // Buscar todos os lances deste benefício ordenados por pontos
        const topLicitantes = await db
          .select({
            userId: beneficioLances.userId,
            nomeUsuario: users.nome,
            telefone: users.telefone,
            email: users.email,
            pontosOfertados: beneficioLances.pontosOfertados,
            status: beneficioLances.status,
            dataLance: beneficioLances.createdAt,
          })
          .from(beneficioLances)
          .innerJoin(users, eq(beneficioLances.userId, users.id))
          .where(eq(beneficioLances.beneficioId, beneficioId))
          .orderBy(desc(beneficioLances.pontosOfertados))
          .limit(10);

        // Também buscar o ganhador já registrado (se existir)
        const ganhadorExistente = await db
          .select({
            id: beneficioGanhadores.id,
            userId: beneficioGanhadores.userId,
            fotoUrl: beneficioGanhadores.fotoUrl,
            lancesTotais: beneficioGanhadores.lancesTotais,
            gritosTotais: beneficioGanhadores.gritosTotais,
            depoimento: beneficioGanhadores.depoimento,
            nomeUsuario: users.nome,
          })
          .from(beneficioGanhadores)
          .leftJoin(users, eq(beneficioGanhadores.userId, users.id))
          .where(eq(beneficioGanhadores.beneficioId, beneficioId))
          .limit(1);

        console.log(
          "📊 [TOP-LICITANTES] Benefício " +
          beneficioId +
          ": " +
          topLicitantes.length +
          " licitantes encontrados"
        );

        res.json({
          success: true,
          topLicitantes,
          ganhadorExistente: ganhadorExistente[0] || null,
          totalLances: topLicitantes.length,
        });
      } catch (error: any) {
        console.error("❌ [TOP-LICITANTES] Erro:", error);
        res
          .status(500)
          .json({ success: false, message: "Erro ao buscar top licitantes" });
      }
    }
  );


