  // GET /api/monitor/:monitorId/historico-chamadas - Buscar histórico de chamadas
  app.get("/api/monitor/:monitorId/historico-chamadas", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined;
      const user = (req as any).user;

      const access = ensureSelfAccess(user, monitorId, 'historico');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }

      let historico: any[] = [];

      // Se vertente é inclusao, buscar apenas presenças de inclusão
      if (vertente === 'inclusao') {
        // Buscar todas as turmas de inclusão
        const turmas = await db.select({
          id: turmasInclusao.id,
          nome: turmasInclusao.nome
        }).from(turmasInclusao);

        const turmaMap = new Map(turmas.map(t => [t.id, t.nome]));

        // Buscar presenças de inclusão com nomes dos participantes
        const presencas = await db.select({
          id: presencasInclusao.id,
          participanteId: presencasInclusao.participanteId,
          turmaId: presencasInclusao.turmaId,
          data: presencasInclusao.data,
          presente: presencasInclusao.presente,
          observacoes: presencasInclusao.observacoes,
          justificativa: presencasInclusao.justificativa,
          fotoComprovante: presencasInclusao.fotoComprovante,
          teveAlimentacao: presencasInclusao.teveAlimentacao,
          createdAt: presencasInclusao.createdAt,
          nome: participantesInclusao.nome
        })
          .from(presencasInclusao)
          .leftJoin(participantesInclusao, eq(presencasInclusao.participanteId, participantesInclusao.id))
          .orderBy(desc(presencasInclusao.data), desc(presencasInclusao.id));

        // Agrupar por turma e data
        const grouped = new Map<string, any>();
        for (const p of presencas) {
          const key = `${p.turmaId}_${p.data}`;
          if (!grouped.has(key)) {
            grouped.set(key, {
              id: `inclusao_${p.turmaId}_${p.data}`,
              data: p.data,
              grupo: turmaMap.get(p.turmaId!) || `Turma ${p.turmaId}`,
              titulo: `Chamada - ${turmaMap.get(p.turmaId!) || 'Turma'}`,
              totalPresentes: 0,
              presencas: [],
              grupoId: p.turmaId,
              criadoEm: p.createdAt,
              fotoComprovante: null,
              teveAlimentacao: null,
              tipo: 'inclusao'
            });
          }
          const group = grouped.get(key);
          if (p.fotoComprovante && !group.fotoComprovante) {
            group.fotoComprovante = p.fotoComprovante;
          }
          group.presencas.push({
            id: p.participanteId,
            nome: p.nome,
            presente: p.presente,
            observacoes: p.observacoes,
            justificativa: p.justificativa,
            fotoComprovante: p.fotoComprovante
          });
          if (p.teveAlimentacao === true) {
            group.teveAlimentacao = true;
          } else if (group.teveAlimentacao !== true && p.teveAlimentacao === false) {
            group.teveAlimentacao = false;
          }
          if (p.presente === true) {
            group.totalPresentes++;
          }
        }

        historico = Array.from(grouped.values());
        await enrichHistoricoGroupsWithEligible(pool, historico);
      } else {
        // PEC: Buscar turmas via staffAssignments
        const staffAssigns = await db.select({
          instanceId: staffAssignments.activity_instance_id,
          instanceTitle: activityInstances.title
        })
          .from(staffAssignments)
          .innerJoin(activityInstances, eq(staffAssignments.activity_instance_id, activityInstances.id))
          .where(eq(staffAssignments.person_id, monitorId));

        const pecInstanceIds = staffAssigns.map(s => s.instanceId);

        // Buscar todos os activityInstances para ter os nomes corretos
        const allInstances = await db.select({ id: activityInstances.id, title: activityInstances.title })
          .from(activityInstances);
        const instanceTitleMap = new Map(allInstances.map(i => [i.id, i.title]));

        // Buscar matriculados ativos com data de matrícula (para calcular total correto por sessão)
        const enrolledResultHist = await db.execute(sql`
          SELECT ie.activity_instance_id AS instance_id, ie.student_cpf, ie.enrollment_date
          FROM instance_enrollments ie
          WHERE ie.active = true
        `);
        const enrolledRowsHist = enrolledResultHist.rows as { instance_id: number; student_cpf: string; enrollment_date: string | null }[];
        const enrolledByInstanceHist = new Map<number, { cpf: string; enrollmentDate: string | null }[]>();
        for (const row of enrolledRowsHist) {
          const instId = Number(row.instance_id);
          if (!enrolledByInstanceHist.has(instId)) enrolledByInstanceHist.set(instId, []);
          enrolledByInstanceHist.get(instId)!.push({
            cpf: row.student_cpf,
            enrollmentDate: row.enrollment_date ? String(row.enrollment_date).slice(0, 10) : null
          });
        }

        // Buscar nomes de todos os alunos matriculados (para incluir ausentes nas presencas)
        const allEnrolledCpfs = [...new Set(enrolledRowsHist.map(r => r.student_cpf))];
        const alunoNameMap = new Map<string, string>();
        if (allEnrolledCpfs.length > 0) {
          const alunoNamesResult = await pool.query(
            `SELECT cpf, nome_completo FROM aluno WHERE cpf = ANY($1)`,
            [allEnrolledCpfs]
          );
          for (const row of alunoNamesResult.rows) {
            alunoNameMap.set(row.cpf, row.nome_completo);
          }
        }

        // Buscar sessões (chamadas) das turmas PEC
        // Se o monitor não tem staffAssignments, retorna todas as sessões PEC (mesma lógica dos grupos)
        let pecSessions: any[] = [];
        if (pecInstanceIds.length > 0) {
          pecSessions = await db.select().from(sessions)
            .where(inArray(sessions.activity_instance_id, pecInstanceIds))
            .orderBy(desc(sessions.date), desc(sessions.id));
        } else {
          // Fallback: retorna todas as sessões PEC
          pecSessions = await db.select().from(sessions)
            .orderBy(desc(sessions.date), desc(sessions.id));
        }

        // Converter sessões PEC para formato do histórico
        const pecHistorico = pecSessions.map(sess => {
          const sessionDate = sess.date ? String(sess.date).slice(0, 10) : null;
          const todosMatriculados = enrolledByInstanceHist.get(sess.activity_instance_id) || [];
          const matriculadosNaData = sessionDate
            ? todosMatriculados.filter(m => !m.enrollmentDate || m.enrollmentDate <= sessionDate)
            : todosMatriculados;
          const attendanceArr: any[] = Array.isArray(sess.attendance) ? sess.attendance : [];
          const totalPresentes = attendanceArr.filter((p: any) => p.presente === true || p.status === "presente").length;
          const totalAlunos = matriculadosNaData.length || attendanceArr.length;

          // Incluir ausentes: alunos matriculados que não estão no attendance
          // Normaliza CPF removendo pontos e traços para comparação segura
          const normCpf = (c: string) => String(c || '').replace(/[.\-]/g, '').trim();
          const attendanceCpfs = new Set(
            attendanceArr.map((p: any) => normCpf(p.alunoCpf || p.cpf || '')).filter(Boolean)
          );
          const fullPresencas = [...attendanceArr];
          for (const m of matriculadosNaData) {
            if (!attendanceCpfs.has(normCpf(m.cpf))) {
              fullPresencas.push({
                alunoCpf: m.cpf,
                cpf: m.cpf,
                nome: alunoNameMap.get(m.cpf) || m.cpf,
                alunoNome: alunoNameMap.get(m.cpf) || m.cpf,
                presente: false,
                status: 'ausente'
              });
            }
          }

          return {
            id: `pec_${sess.id}`,
            sessaoId: sess.id,
            data: sess.date,
            grupo: instanceTitleMap.get(sess.activity_instance_id) || sess.title,
            titulo: sess.title,
            totalPresentes,
            totalAlunos,
            presencas: fullPresencas,
            grupoId: sess.activity_instance_id,
            criadoEm: sess.createdAt,
            fotoComprovante: (sess as any).fotoComprovante || null,
            teveAlimentacao: sess.teveAlimentacao ?? null,
            tipo: 'pec'
          };
        });

        historico = pecHistorico;
      }

      // Ordenar por data
      historico.sort((a, b) => {
        const dateA = new Date(a.data || 0).getTime();
        const dateB = new Date(b.data || 0).getTime();
        return dateB - dateA;
      });

      res.json(historico);
    } catch (error: any) {
      console.error("Error fetching historico chamadas:", error);
      res.status(500).json({ error: "Failed to fetch historico" });
    }
  });

  // POST /api/monitor/:monitorId/registro-presenca - Nova rota para chamada sem turma
  app.post("/api/monitor/:monitorId/registro-presenca", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined;
      const user = (req as any).user;

      const access = ensureSelfAccess(user, monitorId, 'chamada');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }

      const { grupoId, data, observacoes, presencas } = req.body;

      if (!grupoId || !data) {
        return res.status(400).json({ error: 'grupoId e data são obrigatórios' });
      }

      // Primeiro tenta buscar como PEC (activityInstances)
      const pecInstance = await db.select().from(activityInstances)
        .where(eq(activityInstances.id, grupoId))
        .limit(1);

      if (pecInstance.length > 0) {
        // É uma turma PEC — atualiza sessão do dia se já existir (ex.: catraca), senão cria
        const instance = pecInstance[0];
        const dataYMD = String(data).split("T")[0];
        const teveAlim =
          req.body.teve_alimentacao === true ? true : req.body.teve_alimentacao === false ? false : null;

        const existingSess = await db
          .select({ id: sessions.id })
          .from(sessions)
          .where(and(eq(sessions.activity_instance_id, grupoId), eq(sessions.date, dataYMD)))
          .limit(1);

        let sessionId: number;
        if (existingSess.length > 0) {
          sessionId = existingSess[0].id;
          await db
            .update(sessions)
            .set({
              attendance: presencas,
              teveAlimentacao: teveAlim,
              title: 'Chamada - ' + (instance.title || 'Sem grupo'),
              description: observacoes || '',
            })
            .where(eq(sessions.id, sessionId));
          console.log(`[RBAC MONITOR] Registro de presença PEC ATUALIZADO (sessão ${sessionId}) por monitor ${monitorId} turma ${grupoId}`);
        } else {
          const [session] = await db.insert(sessions).values({
            activity_instance_id: grupoId,
            date: dataYMD,
            hours: "2.00",
            title: 'Chamada - ' + (instance.title || 'Sem grupo'),
            description: observacoes || '',
            observations: '',
            status: 'realizado',
            attendance: presencas,
            teveAlimentacao: teveAlim,
          }).returning();
          sessionId = session.id;
          console.log(`[RBAC MONITOR] Registro de presença PEC criado por monitor ${monitorId} para turma ${grupoId}`);
        }

        return res.json({ success: true, id: sessionId, sessionId, message: 'Presença registrada com sucesso' });
      }

      // Tenta buscar como Turma de Inclusão
      const turmaInclusao = await db.select().from(turmasInclusao)
        .where(eq(turmasInclusao.id, grupoId))
        .limit(1);

      if (turmaInclusao.length > 0) {
        // É uma turma de Inclusão - salvar presenças na tabela presencas_inclusao
        const turma = turmaInclusao[0];

        // Apaga registros existentes (inclusive os da catraca) e reinserção completa
        const dataYMDMonitor = String(data).split('T')[0];
        await db.delete(presencasInclusao).where(
          and(eq(presencasInclusao.turmaId, grupoId), sql`${presencasInclusao.data}::date = ${dataYMDMonitor}::date`)
        );

        const insertedPresencas = [];
        for (const p of (presencas || [])) {
          let participanteId = p.id || p.participanteId;
          if (!participanteId && (p.cpf || p.alunoCpf)) {
            const found = await db
              .select({ id: participantesInclusao.id })
              .from(participantesInclusao)
              .where(eq(participantesInclusao.cpf, String(p.cpf || p.alunoCpf)))
              .limit(1);
            if (found[0]) participanteId = found[0].id;
          }
          if (participanteId) {
            const teveAlim = req.body.teve_alimentacao === true ? true : req.body.teve_alimentacao === false ? false : null;
            const [presenca] = await db.insert(presencasInclusao).values({
              participanteId: typeof participanteId === 'string' ? parseInt(participanteId) : participanteId,
              turmaId: grupoId,
              data: dataYMDMonitor,
              presente: p.presente || p.present || false,
              observacoes: p.presente ? (p.viaCatraca ? `Presença via catraca às ${p.hora || ''}` : null) : null,
              justificativa: p.justificativa || null,
              justificativaMotivo: p.justificativaMotivo || null,
              justificativaObs: p.justificativaObs || null,
              contaComoPresenca: p.contaComoPresenca === true,
              teveAlimentacao: teveAlim,
            }).returning();
            insertedPresencas.push(presenca);
          }
        }

        console.log(`[RBAC MONITOR] Registro de ${insertedPresencas.length} presenças Inclusão criado por monitor ${monitorId} para turma ${grupoId}`);
        return res.json({ success: true, count: insertedPresencas.length, message: 'Presenças registradas com sucesso' });
      }

      // Fallback: tenta como monitorGrupos (legacy)
      const grupo = await db.query.monitorGrupos.findFirst({
        where: and(
          eq(monitorGrupos.id, grupoId),
          eq(monitorGrupos.monitorUserId, monitorId)
        )
      });

      if (!grupo) {
        return res.status(404).json({ error: 'Grupo não encontrado' });
      }

      // Salvar na tabela registros_atividades
      const registro = await db.insert(registrosAtividades).values({
        monitorUserId: monitorId,
        dataAtividade: data,
        grupo: grupo.nome,
        titulo: `Chamada - ${grupo.nome}`,
        descricao: observacoes || '',
        participantes: presencas?.filter((p: any) => p.presente).length || 0,
        resultadosObservacoes: JSON.stringify({ presencas, grupoId })
      }).returning();

      console.log(`[RBAC MONITOR] Registro de presença criado por monitor ${monitorId} para grupo ${grupoId}`);
      res.json({ success: true, id: registro[0].id, message: 'Presença registrada com sucesso' });
    } catch (error: any) {
      console.error("Error creating registro presenca:", error);
      res.status(500).json({ error: "Failed to create registro" });
    }
  });

