  // GET /api/favela3d/next-cpf-provisorio
  // Retorna o próximo CPF provisório sequencial (000.000.000-XX)
  app.get("/api/favela3d/next-cpf-provisorio", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const [r1, r2] = await Promise.all([
        db.execute(sql`SELECT cpf FROM favela3d_participantes WHERE cpf LIKE '000.000.000-%' OR cpf LIKE '00000000%'`),
        db.execute(sql`SELECT cpf FROM favela3d_grupo_participantes WHERE cpf LIKE '000.000.000-%' OR cpf LIKE '00000000%'`),
      ]);
      const all = [...(r1.rows as any[]), ...(r2.rows as any[])].map(r => r.cpf as string);
      let maxNum = 0;
      for (const cpf of all) {
        if (!cpf) continue;
        const digits = cpf.replace(/\D/g, "");
        if (digits.length === 11 && digits.startsWith("000000000")) {
          const n = parseInt(digits.slice(9), 10);
          if (n > maxNum) maxNum = n;
        }
      }
      const next = maxNum + 1;
      const formatted = `000.000.000-${String(next).padStart(2, "0")}`;
      return res.json({ cpf: formatted });
    } catch (e) {
      console.error("next-cpf-provisorio:", e);
      return res.status(500).json({ error: "Erro ao gerar CPF provisório" });
    }
  });

  // GET /api/favela3d/participantes
