  // GET /api/favela3d/registros
  app.get("/api/favela3d/registros", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const registros = await db.select().from(favela3dRegistros)
        .orderBy(desc(favela3dRegistros.data));

      // Resolve participantes_ids → nomes para registros coletivos
      const idsNeeded = new Set<number>();
      registros.forEach(r => {
        if (r.participantesIds && Array.isArray(r.participantesIds)) {
          (r.participantesIds as number[]).forEach(id => idsNeeded.add(id));
        }
      });

      let nomeMap: Record<number, string> = {};
      if (idsNeeded.size > 0) {
        const ids = Array.from(idsNeeded);
        const rows = await pool.query(
          `SELECT id, nome FROM favela3d_participantes WHERE id = ANY($1)`,
          [ids]
        );
        rows.rows.forEach((row: any) => { nomeMap[row.id] = row.nome; });
      }

      const enriched = registros.map(r => ({
        ...r,
        participantesNomes: r.participantesIds && Array.isArray(r.participantesIds)
          ? (r.participantesIds as number[]).map(id => nomeMap[id] || `ID ${id}`).filter(Boolean)
          : [],
      }));

      res.json(enriched);
    } catch (error: any) {
      console.error("Error fetching favela3d registros:", error);
      res.status(500).json({ error: "Failed to fetch registros" });
    }
  });

