  // GET /api/favela3d/stats - Dashboard stats
  app.get("/api/favela3d/stats", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const [totalParticipantes, totalRegistros, visitasDomiciliar, atendimentoIndividual, coletivosRows] = await Promise.all([
        db.select({ count: sql<number>`count(*)` })
          .from(favela3dParticipantes)
          .where(eq(favela3dParticipantes.status, 'ativo')),
        db.select({ count: sql<number>`count(*)` })
          .from(favela3dRegistros),
        db.select({ count: sql<number>`count(*)` })
          .from(favela3dRegistros)
          .where(eq(favela3dRegistros.tipo, 'visita_domiciliar')),
        db.select({ count: sql<number>`count(*)` })
          .from(favela3dRegistros)
          .where(eq(favela3dRegistros.tipo, 'atendimento_individual')),
        pool.query(`
            SELECT
              SUM(CASE WHEN tipo = 'atendimento_coletivo' THEN 1 ELSE 0 END)::int AS total_coletivos,
              SUM(CASE WHEN tipo = 'atendimento_coletivo' AND categoria = 'gerando_lideranca' THEN 1 ELSE 0 END)::int AS gerando_lideranca,
              SUM(CASE WHEN tipo = 'atendimento_coletivo' AND categoria = 'assembleia' THEN 1 ELSE 0 END)::int AS assembleia,
              SUM(CASE WHEN tipo = 'atendimento_coletivo' AND categoria = 'grupo_mulheres' THEN 1 ELSE 0 END)::int AS grupo_mulheres
            FROM favela3d_registros
          `),
      ]);

      const coletivos = coletivosRows.rows[0] || {};

      res.json({
        familias: Number(totalParticipantes[0]?.count || 0),
        registros: Number(totalRegistros[0]?.count || 0),
        visitas: Number(visitasDomiciliar[0]?.count || 0),
        atendimentos: Number(atendimentoIndividual[0]?.count || 0),
        totalColetivos: Number(coletivos.total_coletivos || 0),
        gerandoLideranca: Number(coletivos.gerando_lideranca || 0),
        assembleia: Number(coletivos.assembleia || 0),
        grupoMulheres: Number(coletivos.grupo_mulheres || 0),
      });
    } catch (error: any) {
      console.error("Error fetching favela3d stats:", error);
      res.status(500).json({ error: "Failed to fetch stats" });
    }
  });

  // GET /api/favela3d/categoria/:categoria/detalhes
  app.get("/api/favela3d/categoria/:categoria/detalhes", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const { categoria } = req.params;
      const categorias = ["gerando_lideranca", "assembleia", "grupo_mulheres"];
      if (!categorias.includes(categoria)) {
        return res.status(400).json({ error: "Categoria inválida" });
      }

      // Lista de registros da categoria com participantes
      const registros = await pool.query(`
          SELECT
            r.id, r.titulo, r.data, r.conteudo, r.participantes_ids,
            COALESCE(
              (SELECT json_agg(json_build_object(
                'id', p.id, 'nome', p.nome, 'nascimento', p.data_nascimento,
                'genero', p.genero, 'raca', p.raca, 'igf', p.igf
              ))
              FROM favela3d_participantes p
              WHERE p.id = ANY(r.participantes_ids)
              ), '[]'::json
            ) AS participantes
          FROM favela3d_registros r
          WHERE r.tipo = 'atendimento_coletivo' AND r.categoria = $1
            AND r.status IS DISTINCT FROM 'inativo'
          ORDER BY r.data DESC
        `, [categoria]);

      // Agregados demográficos
      const demograficos = await pool.query(`
          SELECT
            p.genero,
            p.raca,
            p.igf,
            EXTRACT(YEAR FROM AGE(CURRENT_DATE, p.data_nascimento::date))::int AS idade
          FROM favela3d_registros r
          JOIN favela3d_participantes p ON p.id = ANY(r.participantes_ids)
          WHERE r.tipo = 'atendimento_coletivo' AND r.categoria = $1
            AND r.status IS DISTINCT FROM 'inativo'
            AND p.data_nascimento IS NOT NULL
        `, [categoria]);

      // Agregados com nulos (sem nascimento)
      const demSemNasc = await pool.query(`
          SELECT p.genero, p.raca, p.igf
          FROM favela3d_registros r
          JOIN favela3d_participantes p ON p.id = ANY(r.participantes_ids)
          WHERE r.tipo = 'atendimento_coletivo' AND r.categoria = $1
            AND r.status IS DISTINCT FROM 'inativo'
        `, [categoria]);

      const porGenero: Record<string, number> = {};
      const porIgf: Record<string, number> = {};
      const porRaca: Record<string, number> = {};
      const idades: number[] = [];

      for (const row of demograficos.rows) {
        if (row.genero) porGenero[row.genero] = (porGenero[row.genero] || 0) + 1;
        if (row.igf) porIgf[row.igf] = (porIgf[row.igf] || 0) + 1;
        if (row.raca) porRaca[row.raca] = (porRaca[row.raca] || 0) + 1;
        if (row.idade) idades.push(Number(row.idade));
      }
      for (const row of demSemNasc.rows) {
        // já contamos genero/raca/igf acima junto com nascimento — aqui pega quem não tem nascimento
      }
      // Re-compute from full set
      const porGenero2: Record<string, number> = {};
      const porIgf2: Record<string, number> = {};
      const porRaca2: Record<string, number> = {};
      for (const row of demSemNasc.rows) {
        if (row.genero) porGenero2[row.genero] = (porGenero2[row.genero] || 0) + 1;
        if (row.igf) porIgf2[row.igf] = (porIgf2[row.igf] || 0) + 1;
        if (row.raca) porRaca2[row.raca] = (porRaca2[row.raca] || 0) + 1;
      }

      const idadeMedia = idades.length > 0 ? Math.round(idades.reduce((a, b) => a + b, 0) / idades.length) : null;
      const totalPessoas = demSemNasc.rows.length;

      res.json({
        registros: registros.rows,
        totalRegistros: registros.rows.length,
        totalPessoas,
        idadeMedia,
        porGenero: porGenero2,
        porIgf: porIgf2,
        porRaca: porRaca2,
      });
    } catch (error: any) {
      console.error("Error fetching categoria detalhes:", error);
      res.status(500).json({ error: "Failed to fetch categoria detalhes" });
    }
  });

  // ═══════════════════════════════════════════════════════════
  //  FAVELA 3D — GRUPOS (grupo-participantes, grupos, reunioes)
  // ═══════════════════════════════════════════════════════════

  // GET /api/favela3d/grupos-kpi — distinct member counts
  app.get("/api/favela3d/grupos-kpi", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const result = await pool.query(`
          SELECT
            SUM(CASE WHEN g.nome ILIKE '%mulheres%' THEN 1 ELSE 0 END) > 0 AS tem_mulheres,
            COUNT(DISTINCT CASE WHEN g.nome ILIKE '%mulheres%' THEN m.participante_id END)::int AS mulheres_pessoas,
            COUNT(DISTINCT CASE WHEN NOT g.nome ILIKE '%mulheres%' THEN m.participante_id END)::int AS outros_pessoas,
            COALESCE((
              SELECT COUNT(*)::int FROM favela3d_reunioes r2
              INNER JOIN favela3d_grupos g2 ON g2.id = r2.grupo_id
              WHERE g2.nome ILIKE '%mulheres%'
            ), 0) AS mulheres_encontros
          FROM favela3d_grupos g
          LEFT JOIN favela3d_grupo_membros m ON m.grupo_id = g.id
        `);
      res.json(result.rows[0] || { mulheres_pessoas: 0, outros_pessoas: 0, mulheres_encontros: 0 });
    } catch (e: any) {
      console.error("favela3d grupos-kpi:", e);
      res.status(500).json({ error: "Erro" });
    }
  });

