  app.get("/api/favela3d/grupos/:grupoId/reunioes", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const grupoId = parseInt(req.params.grupoId);
      const reunioes = await pool.query(
        "SELECT r.*, COALESCE(json_agg(json_build_object('id', rp.participante_id, 'nome', COALESCE(p.nome, rp.nome_cached)) ORDER BY COALESCE(p.nome, rp.nome_cached)) FILTER (WHERE rp.id IS NOT NULL AND COALESCE(p.nome, rp.nome_cached) IS NOT NULL), '[]') AS presentes FROM favela3d_reunioes r LEFT JOIN favela3d_reuniao_presencas rp ON rp.reuniao_id = r.id LEFT JOIN favela3d_grupo_participantes p ON p.id = rp.participante_id WHERE r.grupo_id = $1 GROUP BY r.id ORDER BY r.data DESC",
        [grupoId]
      );
      res.json(reunioes.rows);
    } catch (e: any) {
      console.error("favela3d reunioes GET:", e);
      res.status(500).json({ error: "Erro ao buscar reuniões" });
    }
  });

  // POST /api/favela3d/grupos/:grupoId/reunioes
  app.post("/api/favela3d/grupos/:grupoId/reunioes", requireAuth, requireFavela3D, async (req, res) => {
    try {
      const grupoId = parseInt(req.params.grupoId);
      const { data, descricao, titulo, participante_ids } = req.body;
      if (!data) return res.status(400).json({ error: "data é obrigatória" });
      const userId = (req as any).user?.id;
      const result = await pool.query(
        "INSERT INTO favela3d_reunioes (grupo_id, data, descricao, criado_por, titulo) VALUES ($1,$2,$3,$4,$5) RETURNING *",
        [grupoId, data, descricao || null, userId || null, titulo || null]
      );
      const reuniao = result.rows[0];
      // Add presencas with cached name for historical preservation
      if (Array.isArray(participante_ids) && participante_ids.length > 0) {
        for (const pid of participante_ids) {
          const pRes = await pool.query("SELECT nome FROM favela3d_grupo_participantes WHERE id=$1", [pid]);
          const nomeCached = pRes.rows[0]?.nome || null;
          await pool.query(
            "INSERT INTO favela3d_reuniao_presencas (reuniao_id, participante_id, nome_cached) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING",
            [reuniao.id, pid, nomeCached]
          );
        }
      }
      res.status(201).json({ ...reuniao, presentes: [] });
    } catch (e: any) {
      console.error("favela3d reunioes POST:", e);
      res.status(500).json({ error: "Erro ao criar reunião" });
    }
  });

