  // Replay de presenças não registradas hoje (retroativo)
  app.post("/api/webhook/replay-hoje", requireAuth, requireRole(["dev", "admin"]), async (req, res) => {
    try {
      const { data, unidade, pin } = req.body;

      // PIN de segurança simples
      if (pin !== process.env.PRESENCA_MANUAL_PIN_INCLUSAO && pin !== process.env.PRESENCA_MANUAL_PIN_PEC) {
        return res.status(403).json({ error: "PIN inválido" });
      }

      const nowBr = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Sao_Paulo" }));
      const targetDate = (data as string) ||
        `${nowBr.getFullYear()}-${String(nowBr.getMonth() + 1).padStart(2, "0")}-${String(nowBr.getDate()).padStart(2, "0")}`;

      // Busca todas as tentativas com resultado "nao_encontrado" do dia
      const query = unidade
        ? `SELECT DISTINCT ON (aluno_id) aluno_id, unidade, sentido, hora, data_evento
           FROM webhook_catraca_log
           WHERE data_evento = $1 AND resultado = 'nao_encontrado' AND unidade = $2
           ORDER BY aluno_id, hora ASC`
        : `SELECT DISTINCT ON (aluno_id) aluno_id, unidade, sentido, hora, data_evento
           FROM webhook_catraca_log
           WHERE data_evento = $1 AND resultado = 'nao_encontrado'
           ORDER BY aluno_id, hora ASC`;

      const params = unidade ? [targetDate, unidade] : [targetDate];
      const falhas = await pool.query(query, params);

      if (falhas.rows.length === 0) {
        return res.json({ ok: true, data: targetDate, total: 0, processados: [], mensagem: "Nenhuma falha encontrada para reprocessar nesta data." });
      }

      const baseUrl = `${req.protocol}://${req.get("host")}`;
      const resultados: any[] = [];

      for (const row of falhas.rows) {
        // Reconstrói o timestamp a partir da data + hora originais
        const [h, m] = (row.hora || "00:00").split(":").map(Number);
        const ts = new Date(`${row.data_evento}T${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:00-03:00`);

        try {
          const resp = await fetch(`${baseUrl}/webhook/presenca`, {
            method: "POST",
            headers: catracaWebhookHeaders(),
            body: JSON.stringify({
              aluno_id: row.aluno_id,
              unidade: row.unidade,
              sentido: row.sentido || "entrada",
              timestamp: ts.getTime(),
            }),
          });
          const body = await resp.json() as any;
          resultados.push({
            aluno_id: row.aluno_id,
            unidade: row.unidade,
            hora_original: row.hora,
            status: resp.status,
            resultado: body.resultado_final || body.status || "desconhecido",
            nome: body.nome || null,
            turma: body.turma || null,
          });
        } catch (fetchErr: any) {
          resultados.push({ aluno_id: row.aluno_id, unidade: row.unidade, hora_original: row.hora, status: 500, resultado: "erro_fetch", detalhe: fetchErr?.message });
        }
      }

      const sucesso = resultados.filter(r => r.resultado === "presente").length;
      const jaPresenteCount = resultados.filter(r => r.resultado === "ja_presente").length;
      const semTurma = resultados.filter(r => ["sem_turma_ativa", "sem_turma_hoje"].includes(r.resultado)).length;
      const aindaFalhou = resultados.filter(r => r.resultado === "nao_encontrado" || r.resultado === "erro_fetch").length;

      return res.json({
        ok: true,
        data: targetDate,
        total_falhas_encontradas: falhas.rows.length,
        presencas_registradas: sucesso,
        ja_presente: jaPresenteCount,
        sem_turma: semTurma,
        ainda_falhou: aindaFalhou,
        detalhes: resultados,
      });
    } catch (error: any) {
      console.error("[REPLAY WEBHOOK] Erro:", error);
      return res.status(500).json({ error: "Erro ao reprocessar presenças", detalhe: error?.message });
    }
  });


  // Registrar presença retroativa por nome (lista do Intelbras)
  app.post("/api/webhook/presenca-por-nome", requireAuth, requireRole(["dev", "admin"]), async (req, res) => {
    try {
      const { alunos, pin } = req.body as { alunos: { nome: string; hora: string; data: string }[]; pin: string };

      if (pin !== process.env.PRESENCA_MANUAL_PIN_INCLUSAO && pin !== process.env.PRESENCA_MANUAL_PIN_PEC) {
        return res.status(403).json({ error: "PIN inválido" });
      }
      if (!Array.isArray(alunos) || alunos.length === 0) {
        return res.status(400).json({ error: "Lista de alunos vazia" });
      }

      const baseUrl = `${req.protocol}://${req.get("host")}`;
      const resultados: any[] = [];

      for (const entrada of alunos) {
        const { nome, hora, data } = entrada;

        // Busca aluno por nome exato ou ILIKE no banco PEC
        const pecRes = await pool.query(
          `SELECT cpf, nome_completo FROM aluno
           WHERE LOWER(nome_completo) = LOWER($1)
              OR LOWER(nome_completo) ILIKE LOWER($2)
           LIMIT 3`,
          [nome, `%${nome}%`]
        );

        if (pecRes.rows.length === 0) {
          // Tenta busca parcial por palavras-chave do nome
          const partes = nome.split(' ').filter((p: string) => p.length > 3);
          const condicoes = partes.map((_: string, idx: number) => `LOWER(nome_completo) ILIKE LOWER($${idx + 1})`).join(' AND ');
          const params = partes.map((p: string) => `%${p}%`);
          const fuzzyRes = params.length > 0
            ? await pool.query(`SELECT cpf, nome_completo FROM aluno WHERE ${condicoes} LIMIT 3`, params)
            : { rows: [] };

          if (fuzzyRes.rows.length === 0) {
            resultados.push({ nome, status: 'nao_encontrado', detalhe: 'Aluno não encontrado no banco PEC' });
            continue;
          }
          if (fuzzyRes.rows.length > 1) {
            resultados.push({ nome, status: 'multiplos_matches', detalhe: `${fuzzyRes.rows.length} resultados: ${fuzzyRes.rows.map((r: any) => r.nome_completo).join(', ')}` });
            continue;
          }
          pecRes.rows.push(...fuzzyRes.rows);
        }

        if (pecRes.rows.length > 1) {
          resultados.push({ nome, status: 'multiplos_matches', detalhe: `${pecRes.rows.length} resultados: ${pecRes.rows.map((r: any) => r.nome_completo).join(', ')}` });
          continue;
        }

        const alunoRow = pecRes.rows[0];
        const cpf = alunoRow.cpf;

        // Reconstrói o timestamp a partir de data + hora do Intelbras
        const [h, m, s] = (hora || "00:00:00").split(":").map(Number);
        const [ano, mes, dia] = (data || "2026-05-05").split("-").map(Number);
        // Cria como horário de Brasília (UTC-3)
        const ts = new Date(Date.UTC(ano, mes - 1, dia, h + 3, m, s || 0));

        // Tenta primeiro via webhook normal
        let webhookResultado: string | null = null;
        let webhookTurma: string | null = null;
        try {
          const resp = await fetch(`${baseUrl}/webhook/presenca`, {
            method: "POST",
            headers: catracaWebhookHeaders(),
            body: JSON.stringify({
              aluno_id: cpf,
              unidade: "CASA_SONHAR",
              sentido: "entrada",
              timestamp: ts.getTime(),
            }),
          });
          const body = await resp.json() as any;
          webhookResultado = body.resultado_final || body.status || "desconhecido";
          webhookTurma = body.turma || null;
        } catch (_) { webhookResultado = "erro_fetch"; }

        // Se já funcionou, registra e segue
        if (webhookResultado === "presente" || webhookResultado === "ja_presente") {
          resultados.push({
            nome, nome_banco: alunoRow.nome_completo,
            cpf: cpf?.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.***.***-$4'),
            hora_original: hora, resultado: webhookResultado, turma: webhookTurma,
          });
          continue;
        }

        // Fallback: busca qualquer turma ativa na segunda-feira para este aluno,
        // ignora janela de horário e registra presença diretamente
        const DIAS_SEMANA_HOJE: Record<number, string> = { 0: 'domingo', 1: 'segunda', 2: 'terca', 3: 'quarta', 4: 'quinta', 5: 'sexta', 6: 'sabado' };
        const [aY, aM, aD] = (data || "2026-05-05").split("-").map(Number);
        const dataObj = new Date(aY, aM - 1, aD);
        const diaSemanaIdx = dataObj.getDay();
        const diaNorm = DIAS_SEMANA_HOJE[diaSemanaIdx] || "segunda";

        const matriculasRes = await pool.query(
          `SELECT ie.activity_instance_id, ai.title, ai.start_time, ai.dias_semana
           FROM instance_enrollments ie
           JOIN activity_instances ai ON ai.id = ie.activity_instance_id
           WHERE ie.student_cpf = $1 AND ie.active = true AND ai.situation != 'encerrada'`,
          [cpf]
        );

        // Filtra turmas que ocorrem no dia da semana correto
        const normDia = (s: string) => String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        const turmasNoDia = matriculasRes.rows.filter((t: any) => {
          const dias: string[] = Array.isArray(t.dias_semana) ? t.dias_semana : [];
          return dias.map(normDia).some((d: string) => d.includes(normDia(diaNorm)));
        });

        if (turmasNoDia.length === 0) {
          resultados.push({ nome, nome_banco: alunoRow.nome_completo, hora_original: hora, resultado: "sem_turma_no_dia", detalhe: `Sem turma em ${diaNorm}` });
          continue;
        }

        // Escolhe a turma (se houver mais de uma, pega a de start_time mais próximo do evento)
        const [eh, em] = hora.split(":").map(Number);
        const eventMin = eh * 60 + em;
        const toMin = (t: string) => { const p = String(t || "").split(":"); return parseInt(p[0] || "0") * 60 + parseInt(p[1] || "0"); };
        turmasNoDia.sort((a: any, b: any) => Math.abs(toMin(a.start_time) - eventMin) - Math.abs(toMin(b.start_time) - eventMin));
        const turmaEscolhida = turmasNoDia[0];
        const instanceId = turmaEscolhida.activity_instance_id;
        const turmaNome = turmaEscolhida.title;

        // Verifica se já tem presença registrada
        const sessaoRes = await pool.query(
          `SELECT * FROM sessions WHERE activity_instance_id = $1 AND date = $2 LIMIT 1`,
          [instanceId, data]
        );

        if (sessaoRes.rows.length > 0) {
          const sessao = sessaoRes.rows[0];
          const att: any[] = sessao.attendance || [];
          if (att.some((a: any) => a.alunoCpf === cpf && a.presente === true)) {
            resultados.push({ nome, nome_banco: alunoRow.nome_completo, hora_original: hora, resultado: "ja_presente", turma: turmaNome });
            continue;
          }
          const updatedAtt = [
            ...att.filter((a: any) => a.alunoCpf !== cpf),
            { alunoCpf: cpf, alunoNome: alunoRow.nome_completo, presente: true, status: "presente", horaEntrada: hora.substring(0, 5), timestampEvento: ts.toISOString(), origemCatraca: true, registroManual: true },
          ];
          await pool.query(`UPDATE sessions SET attendance = $1 WHERE id = $2`, [JSON.stringify(updatedAtt), sessao.id]);
        } else {
          // Cria sessão nova com todos os matriculados
          const todosEnroll = await pool.query(
            `SELECT ie.student_cpf, a.nome_completo FROM instance_enrollments ie
             LEFT JOIN aluno a ON a.cpf = ie.student_cpf
             WHERE ie.activity_instance_id = $1 AND ie.active = true`,
            [instanceId]
          );
          const attList = todosEnroll.rows.map((e: any) => ({
            alunoCpf: e.student_cpf, alunoNome: e.nome_completo || "Sem nome",
            presente: e.student_cpf === cpf,
            status: e.student_cpf === cpf ? "presente" : "ausente",
            horaEntrada: e.student_cpf === cpf ? hora.substring(0, 5) : null,
            timestampEvento: e.student_cpf === cpf ? ts.toISOString() : null,
            origemCatraca: e.student_cpf === cpf,
            registroManual: e.student_cpf === cpf,
          }));
          await pool.query(
            `INSERT INTO sessions (activity_instance_id, date, hours, title, description, status, attendance)
             VALUES ($1, $2, '2.00', $3, 'Presença registrada manualmente via log Intelbras', 'realizado', $4)`,
            [instanceId, data, `Chamada Manual - ${turmaNome}`, JSON.stringify(attList)]
          );
        }

        resultados.push({
          nome, nome_banco: alunoRow.nome_completo,
          cpf: cpf?.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.***.***-$4'),
          hora_original: hora, resultado: "presente", turma: turmaNome,
          detalhe: "registro_manual_fallback_dia",
        });
      }

      const presentes = resultados.filter(r => r.resultado === "presente").length;
      const jaPresente = resultados.filter(r => r.resultado === "ja_presente").length;
      const semTurma = resultados.filter(r => ["sem_turma_ativa", "sem_turma_hoje", "sem_turma_no_dia"].includes(r.resultado)).length;
      const naoEncontrado = resultados.filter(r => ["nao_encontrado", "multiplos_matches"].includes(r.resultado)).length;

      return res.json({
        ok: true,
        total: alunos.length,
        presencas_registradas: presentes,
        ja_presente: jaPresente,
        sem_turma: semTurma,
        nao_encontrado: naoEncontrado,
        detalhes: resultados,
      });
    } catch (error: any) {
      console.error("[PRESENCA POR NOME] Erro:", error);
      return res.status(500).json({ error: "Erro ao registrar presenças por nome", detalhe: error?.message });
    }
  });


