  // GET /api/eventos-grito — lista pública (somente ativos)
  // Helper: converte chave GCS em signed URL acessível publicamente
  async function resolveEventoBannerUrl(bannerUrl: string | null): Promise<string | null> {
    if (!bannerUrl) return null;
    if (bannerUrl.startsWith('http://') || bannerUrl.startsWith('https://')) return bannerUrl;
    try { return await getSignedUrl(bannerUrl, 60 * 24 * 7); } // 7 dias
    catch { return null; }
  }
  async function resolveEventosBannerUrls(rows: any[]): Promise<any[]> {
    return Promise.all(rows.map(async r => ({
      ...r,
      banner_url: await resolveEventoBannerUrl(r.banner_url),
    })));
  }

