  // DELETE /api/nps/pesquisas/:id
  app.delete('/api/nps/pesquisas/:id', async (req, res) => {
    try {
      const id = parseInt(req.params.id);

      // Salvar programa e meses afetados ANTES de deletar
      const pesqRes = await pool.query('SELECT programa FROM nps_pesquisas WHERE id=$1', [id]);
      if (!pesqRes.rows.length) return res.status(404).json({ error: 'Pesquisa não encontrada' });
      const programa = pesqRes.rows[0].programa;

      const mesesRes = await pool.query(
        `SELECT DISTINCT EXTRACT(YEAR FROM criado_em)::int AS ano, EXTRACT(MONTH FROM criado_em)::int AS mes
         FROM nps_respostas WHERE pesquisa_id=$1`, [id]);
      const mesesAfetados: { ano: number; mes: number }[] = mesesRes.rows.map((r: any) => ({ ano: r.ano, mes: r.mes }));

      // Deletar pesquisa (CASCADE apaga respostas e itens)
      await pool.query('DELETE FROM nps_pesquisas WHERE id=$1', [id]);

      // Recalcular nps_scores_mensais para cada mês afetado e o acumulado anual
      const anosAfetados = [...new Set(mesesAfetados.map(m => m.ano))];
      for (const { ano, mes } of mesesAfetados) {
        await recalcularNpsScore(programa, ano, mes);
      }
      for (const ano of anosAfetados) {
        await recalcularNpsScore(programa, ano, null);
      }

      return res.json({ sucesso: true });
    } catch (e: any) { return res.status(500).json({ error: e.message }); }
  });

  // Função auxiliar: recalcular e salvar NPS de um programa/mês
  async function recalcularNpsScore(programa: string, ano: number, mes: number | null) {
    try {
      if (mes === null) {
        const mensais = await pool.query(
          `SELECT nps_score FROM nps_scores_mensais WHERE programa=$1 AND ano=$2 AND mes IS NOT NULL ORDER BY mes`,
          [programa, ano],
        );
        if (!mensais.rows.length) {
          await pool.query(
            'DELETE FROM nps_scores_mensais WHERE programa=$1 AND ano=$2 AND mes IS NULL',
            [programa, ano],
          );
          return;
        }
        const scores = mensais.rows.map((r: { nps_score: number }) => Number(r.nps_score));
        const score = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
        const upd = await pool.query(
          `UPDATE nps_scores_mensais SET nps_score=$3, total_respostas=$4, calculado_em=NOW()
           WHERE programa=$1 AND ano=$2 AND mes IS NULL`,
          [programa, ano, score, scores.length],
        );
        if (upd.rowCount === 0) {
          await pool.query(
            `INSERT INTO nps_scores_mensais (programa, ano, mes, nps_score, total_respostas, promotores, neutros, detratores, calculado_em)
             VALUES ($1, $2, NULL, $3, $4, 0, 0, 0, NOW())`,
            [programa, ano, score, scores.length],
          );
        }
        return;
      }

      const params: any[] = [programa];
      let filter = '';
      if (mes !== null) {
        params.push(ano, mes);
        filter = `AND EXTRACT(YEAR FROM nr.criado_em) = $${params.length - 1} AND EXTRACT(MONTH FROM nr.criado_em) = $${params.length}`;
      } else {
        params.push(ano);
        filter = `AND EXTRACT(YEAR FROM nr.criado_em) = $${params.length}`;
      }
      const q = `
        SELECT ri.valor_numerico
        FROM nps_respostas_itens ri
        JOIN nps_perguntas np ON np.id = ri.pergunta_id
        JOIN nps_pesquisas p ON p.id = np.pesquisa_id
        JOIN nps_respostas nr ON nr.id = ri.resposta_id
        WHERE p.programa = $1 AND np.is_nps_principal = TRUE AND ri.valor_numerico IS NOT NULL
        ${filter}
      `;
      const result = await pool.query(q, params);
      if (result.rows.length === 0) {
        // Sem respostas restantes: remove o score histórico
        await pool.query(
          mes !== null
            ? 'DELETE FROM nps_scores_mensais WHERE programa=$1 AND ano=$2 AND mes=$3'
            : 'DELETE FROM nps_scores_mensais WHERE programa=$1 AND ano=$2 AND mes IS NULL',
          mes !== null ? [programa, ano, mes] : [programa, ano]
        );
        return;
      }
      const vals = result.rows.map((r: any) => Number(r.valor_numerico));
      const tot = vals.length;
      const prom = vals.filter((v: number) => v >= 9).length;
      const neu = vals.filter((v: number) => v >= 7 && v <= 8).length;
      const det = vals.filter((v: number) => v <= 6).length;
      const score = Math.round(((prom - det) / tot) * 100);
      await pool.query(`
        INSERT INTO nps_scores_mensais (programa, ano, mes, nps_score, total_respostas, promotores, neutros, detratores, calculado_em)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW())
        ON CONFLICT (programa, ano, mes) DO UPDATE SET
          nps_score = EXCLUDED.nps_score,
          total_respostas = EXCLUDED.total_respostas,
          promotores = EXCLUDED.promotores,
          neutros = EXCLUDED.neutros,
          detratores = EXCLUDED.detratores,
          calculado_em = NOW()
      `, [programa, ano, mes, score, tot, prom, neu, det]);
    } catch (e: any) {
      console.error('Erro ao recalcular NPS score:', e.message);
    }
  }

  // POST /api/nps/evidencia-upload — aluno sobe evidência de uma pergunta
  app.post('/api/nps/evidencia-upload', requireAlunoPortalAuth, memUpload.single('arquivo'), async (req: any, res) => {
    try {
      if (!req.file) return res.status(400).json({ error: 'Arquivo obrigatório' });
      const { pesquisaId, perguntaId, cpf } = req.body;
      const cpfLimpo = (cpf || "").replace(/\D/g, "");
      const cpfSessao = String(req.user?.cpf || req.user?.id || "").replace(/\D/g, "");
      if (cpfLimpo !== cpfSessao) {
        return res.status(403).json({ error: "CPF não corresponde ao usuario logado" })
      }
      if (!pesquisaId || !perguntaId || !cpf) return res.status(400).json({ error: 'pesquisaId, perguntaId e cpf são obrigatórios' });
      const ext = req.file.originalname.split('.').pop()?.toLowerCase() || 'bin';
      const fileName = `nps/evidencias/${cpf.replace(/\D/g, '')}_p${perguntaId}_${Date.now()}.${ext}`;
      const url = await uploadToGCS(req.file.buffer, fileName, req.file.mimetype);
      return res.json({ url });
    } catch (e: any) { return res.status(500).json({ error: e.message }); }
  });

  // POST /api/nps/respostas — aluno responde pesquisa
  app.post('/api/nps/respostas', async (req, res) => {
    try {
      const { pesquisaId, cpf, respostas } = req.body;
      const cpfLimpo = (cpf || '').replace(/\D/g, '');
      if (!pesquisaId || !cpfLimpo) return res.status(400).json({ error: 'pesquisaId e cpf obrigatórios' });

      const existing = await pool.query('SELECT id FROM nps_respostas WHERE pesquisa_id=$1 AND aluno_cpf=$2', [pesquisaId, cpfLimpo]);
      if (existing.rows.length) return res.status(409).json({ error: 'Você já respondeu esta pesquisa' });

      const respRes = await pool.query(
        'INSERT INTO nps_respostas (pesquisa_id, aluno_cpf) VALUES ($1,$2) RETURNING id',
        [pesquisaId, cpfLimpo]
      );
      const respostaId = respRes.rows[0].id;

      for (const r of (respostas || [])) {
        await pool.query(
          'INSERT INTO nps_respostas_itens (resposta_id, pergunta_id, valor_numerico, valor_texto, evidencia_url) VALUES ($1,$2,$3,$4,$5)',
          [respostaId, r.perguntaId, r.valorNumerico ?? null, r.valorTexto ?? null, r.evidenciaUrl ?? null]
        );
      }

      // Recalcular NPS após nova resposta
      try {
        const pesqInfo = await pool.query('SELECT programa FROM nps_pesquisas WHERE id=$1', [pesquisaId]);
        if (pesqInfo.rows.length) {
          const programa = pesqInfo.rows[0].programa;
          const now = new Date();
          const anoAtual = now.getFullYear();
          const mesAtual = now.getMonth() + 1;
          // Salva o mensal e o acumulado do ano
          await recalcularNpsScore(programa, anoAtual, mesAtual);
          await recalcularNpsScore(programa, anoAtual, null);
        }
      } catch (e: any) {
        console.error('Erro ao atualizar NPS após resposta:', e.message);
      }

      return res.json({ sucesso: true });
    } catch (e: any) { return res.status(500).json({ error: e.message }); }
  });

  // GET /api/nps/scores — histórico de NPS por programa/ano/mês
  app.get('/api/nps/scores', async (req, res) => {
    try {
      const { programa, ano } = req.query;
      let q = 'SELECT * FROM nps_scores_mensais WHERE 1=1';
      const params: any[] = [];
      if (programa) { params.push(programa); q += ` AND programa = $${params.length}`; }
      if (ano) { params.push(Number(ano)); q += ` AND ano = $${params.length}`; }
      q += ' ORDER BY ano DESC, mes NULLS LAST';
      const result = await pool.query(q, params);
      return res.json(result.rows);
    } catch (e: any) { return res.status(500).json({ error: e.message }); }
  });

  // GET /api/aluno-portal/nps-pendente — pesquisas abertas para o aluno
  app.get('/api/aluno-portal/nps-pendente', requireAlunoPortalAuth, async (req, res) => {
    try {
      const cpf = (req as any).alunoCpf as string;
      if (!cpf) return res.status(400).json({ error: 'CPF obrigatório' });

      // Descobre turmas do aluno (PEC e Inclusão)
      const turmasPec = await pool.query(
        "SELECT ie.activity_instance_id as turma_id FROM instance_enrollments ie WHERE REGEXP_REPLACE(ie.student_cpf,'[^0-9]','','g')=$1 AND ie.active=true",
        [cpf]
      );
      const turmasInc = await pool.query(
        "SELECT pt.turma_id FROM participantes_inclusao pi JOIN participantes_turmas pt ON pt.participante_id=pi.id WHERE REGEXP_REPLACE(pi.cpf,'[^0-9]','','g')=$1",
        [cpf]
      );
      const turmaIds = [
        ...turmasPec.rows.map((r: any) => r.turma_id),
        ...turmasInc.rows.map((r: any) => r.turma_id),
      ];

      // Pesquisas abertas para as turmas do aluno + pesquisas para "Todos os alunos" (turma_id=0)
      // turma_id=0 é program-specific: pec só aparece para alunos pec, inclusão só para alunos inclusão
      const isPec = turmasPec.rows.length > 0;
      const isInclusao = turmasInc.rows.length > 0;
      const pesq = await pool.query(
        `SELECT DISTINCT p.id, p.titulo, p.programa
         FROM nps_pesquisas p
         JOIN nps_pesquisa_turmas pt ON pt.pesquisa_id = p.id
         WHERE p.status = 'aberta'
           AND (
             pt.turma_id = ANY($1::int[])
             OR (pt.turma_id = 0 AND p.programa = 'pec' AND $3::boolean)
             OR (pt.turma_id = 0 AND p.programa = 'inclusao' AND $4::boolean)
           )
           AND NOT EXISTS (
             SELECT 1 FROM nps_respostas r WHERE r.pesquisa_id=p.id AND r.aluno_cpf=$2
           )`,
        [turmaIds, cpf, isPec, isInclusao]
      );

      const result = [];
      for (const row of pesq.rows) {
        const pergs = await pool.query('SELECT * FROM nps_perguntas WHERE pesquisa_id=$1 ORDER BY ordem', [row.id]);
        const perguntas = pergs.rows.map((p: any) => ({
          ...p,
          opcoes: p.opcoes ? JSON.parse(p.opcoes) : [],
        }));
        result.push({ ...row, perguntas });
      }
      return res.json(result);
    } catch (e: any) { return res.status(500).json({ error: e.message }); }
  });


  // ==============================
  // PORTAL PÚBLICO — Auth de usuários de eventos
  // ==============================
  // ── Validações portal de eventos ─────────────────────────────────────────
  function _validarCPFPortal(cpf: string): boolean {
    const n = cpf.replace(/\D/g, "");
    if (n.length !== 11 || /^(\d)\1+$/.test(n)) return false;
    let s = 0; for (let i = 0; i < 9; i++) s += parseInt(n[i]) * (10 - i);
    let r = (s * 10) % 11; if (r === 10 || r === 11) r = 0;
    if (r !== parseInt(n[9])) return false;
    s = 0; for (let i = 0; i < 10; i++) s += parseInt(n[i]) * (11 - i);
    r = (s * 10) % 11; if (r === 10 || r === 11) r = 0;
    return r === parseInt(n[10]);
  }
  function _validarEmailPortal(email: string): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.trim());
  }
  function _validarSenhaFortePortal(senha: string): string | null {
    if (senha.length < 8) return "Senha deve ter pelo menos 8 caracteres";
    if (!/[A-Z]/.test(senha)) return "Senha deve ter pelo menos uma letra maiúscula";
    if (!/[a-z]/.test(senha)) return "Senha deve ter pelo menos uma letra minúscula";
    if (!/[0-9]/.test(senha)) return "Senha deve ter pelo menos um número";
    if (!/[!@#$%^&*()_+\-=\[\]{};':\\|,.<>\/?]/.test(senha)) return "Senha deve ter pelo menos um símbolo (!@#$%...)";
    const seqs = ["123456789", "987654321", "12345678", "23456789", "abcdefgh", "qwertyui", "asdfghjk", "zxcvbnm", "qwerty", "asdfgh", "123456", "654321"];
    if (seqs.some(s => senha.toLowerCase().includes(s))) return "Senha não pode conter sequências óbvias (123, abc, qwerty)";
    return null;
  }

  app.post("/api/portal/register", express.json(), async (req: any, res) => {
    try {
      const { nome, cpf, email, senha, dataNascimento, genero, cep, logradouro, numero, complemento, bairro, cidade, estado } = req.body;
      if (!nome || !cpf || !email || !senha) return res.status(400).json({ error: "Nome, CPF, email e senha são obrigatórios" });

      // Validar e-mail
      if (!_validarEmailPortal(email)) return res.status(400).json({ error: "E-mail inválido" });

      // Validar CPF (formato + dígitos verificadores)
      if (!_validarCPFPortal(cpf)) return res.status(400).json({ error: "CPF inválido" });
      const cpfNums = cpf.replace(/\D/g, "");
      const cpfFmt = cpfNums.slice(0, 3) + "." + cpfNums.slice(3, 6) + "." + cpfNums.slice(6, 9) + "-" + cpfNums.slice(9);

      // Validar senha forte
      const erroSenha = _validarSenhaFortePortal(senha);
      if (erroSenha) return res.status(400).json({ error: erroSenha });

      const { usuariosPortal } = await import("../shared/schema.js");
      const existente = await db.select().from(usuariosPortal).where(eq(usuariosPortal.email, email.toLowerCase().trim())).limit(1);
      if (existente.length > 0) return res.status(400).json({ error: "E-mail já cadastrado" });

      // Verificar CPF duplicado
      const existenteCpf = await db.select().from(usuariosPortal).where(eq(usuariosPortal.cpf, cpfFmt)).limit(1);
      if (existenteCpf.length > 0) return res.status(400).json({ error: "CPF já cadastrado" });

      const senhaHash = await bcrypt.hash(senha, 10);
      const [usuario] = await db.insert(usuariosPortal).values({
        nome: nome.trim(),
        cpf: cpfFmt,
        email: email.toLowerCase().trim(),
        senhaHash,
        dataNascimento: dataNascimento || null,
        genero: genero || null,
        cep: cep || null,
        logradouro: logradouro || null,
        numero: numero || null,
        complemento: complemento || null,
        bairro: bairro || null,
        cidade: cidade || null,
        estado: estado || null,
      }).returning();

      const sess = req.session as any;
      if (sess) { sess.portalUserId = usuario.id; }

      const { senhaHash: _, ...usuarioSemSenha } = usuario;
      return res.json({ success: true, usuario: usuarioSemSenha });
    } catch (e: any) {
      console.error("Portal register error:", e);
      return res.status(500).json({ error: "Erro ao cadastrar" });
    }
  });

  app.post("/api/portal/login", express.json(), passwordLoginLimiter, async (req: any, res) => {
    try {
      const { email, senha } = req.body;
      if (!email || !senha) return res.status(400).json({ error: "Email e senha obrigatórios" });

      const { usuariosPortal } = await import("../shared/schema.js");
      const [usuario] = await db.select().from(usuariosPortal).where(eq(usuariosPortal.email, email.toLowerCase().trim())).limit(1);
      if (!usuario) return res.status(401).json({ error: "E-mail ou senha incorretos" });

      const valida = await bcrypt.compare(senha, usuario.senhaHash);
      if (!valida) return res.status(401).json({ error: "E-mail ou senha incorretos" });

      const sess = req.session as any;
      if (sess) { sess.portalUserId = usuario.id; }

      const { senhaHash: _, ...usuarioSemSenha } = usuario;
      return res.json({ success: true, usuario: usuarioSemSenha });
    } catch (e: any) {
      console.error("Portal login error:", e);
      return res.status(500).json({ error: "Erro interno" });
    }
  });

  app.post("/api/portal/logout", async (req: any, res) => {
    try {
      const sess = req.session as any;
      if (sess) { delete sess.portalUserId; }
      return res.json({ success: true });
    } catch (e: any) {
      return res.status(500).json({ error: "Erro ao sair" });
    }
  });

