  // PUT /api/portal/ingressos/:codigo/beneficiario — atribuir ingresso a terceiro
  app.put("/api/portal/ingressos/:codigo/beneficiario", async (req: any, res) => {
    try {
      const sess = req.session as any;
      const portalUserId = sess?.portalUserId;
      if (!portalUserId) return res.status(401).json({ error: "Não autenticado" });

      const { beneficiario_nome, beneficiario_cpf, beneficiario_email, beneficiario_telefone,
        beneficiario_nascimento, beneficiario_genero,
        beneficiario_logradouro, beneficiario_numero, beneficiario_bairro,
        beneficiario_cidade, beneficiario_estado, beneficiario_cep } = req.body;
      if (!beneficiario_nome) return res.status(400).json({ error: "Nome do beneficiário obrigatório" });

      // Busca o ingresso para obter evento_id antes de atualizar
      const { rows: [ingresso] } = await pool.query(
        `SELECT id, evento_id, titular_cpf FROM ingressos_portal WHERE codigo=$1 AND usuario_portal_id=$2`,
        [req.params.codigo, portalUserId]
      );
      if (!ingresso) return res.status(404).json({ error: "Ingresso não encontrado" });

      // Valida unicidade do CPF no evento (mesmo CPF não pode ser portador de outro ingresso)
      if (beneficiario_cpf) {
        const cpfRaw = beneficiario_cpf.replace(/\D/g, "");
        const titularRaw = (ingresso.titular_cpf || "").replace(/\D/g, "");

        // Não pode ser o próprio CPF do comprador
        if (cpfRaw === titularRaw) {
          return res.status(400).json({ error: "O portador não pode ser o mesmo CPF do comprador. Use a transferência de ingresso." });
        }

        // Verifica se este CPF já tem ingresso neste evento (como titular ou beneficiário)
        const { rows: cpfJaExiste } = await pool.query(
          `SELECT id FROM ingressos_portal
           WHERE evento_id=$1 AND status != 'cancelado' AND id != $2
           AND (
             (para_terceiro = false AND titular_cpf = ANY($3::text[]))
             OR (para_terceiro = true AND beneficiario_cpf = ANY($3::text[]))
           )`,
          [ingresso.evento_id, ingresso.id, [cpfRaw, beneficiario_cpf]]
        );
        if (cpfJaExiste.length > 0) {
          return res.status(400).json({ error: "Este CPF já possui um ingresso para este evento." });
        }
      }

      const { rows } = await pool.query(`
        UPDATE ingressos_portal SET
          para_terceiro = true,
          beneficiario_nome = $1, beneficiario_cpf = $2,
          beneficiario_email = $3, beneficiario_telefone = $4,
          beneficiario_nascimento = $5, beneficiario_genero = $6,
          beneficiario_logradouro = $7, beneficiario_numero = $8,
          beneficiario_bairro = $9, beneficiario_cidade = $10,
          beneficiario_estado = $11, beneficiario_cep = $12
        WHERE codigo = $13 AND usuario_portal_id = $14
        RETURNING *
      `, [beneficiario_nome, beneficiario_cpf || null, beneficiario_email || null, beneficiario_telefone || null,
        beneficiario_nascimento || null, beneficiario_genero || null,
        beneficiario_logradouro || null, beneficiario_numero || null,
        beneficiario_bairro || null, beneficiario_cidade || null,
        beneficiario_estado || null, beneficiario_cep || null,
        req.params.codigo, portalUserId]);

      if (!rows[0]) return res.status(404).json({ error: "Ingresso não encontrado" });
      return res.json({ success: true, ingresso: rows[0] });
    } catch (e: any) {
      return res.status(500).json({ error: "Erro interno" });
    }
  });

  // POST /api/portal/ingressos/:codigo/transferir — User 1 inicia transferência
  app.post("/api/portal/ingressos/:codigo/transferir", async (req: any, res) => {
    try {
      const sess = req.session as any;
      const portalUserId = sess?.portalUserId;
      if (!portalUserId) return res.status(401).json({ error: "Não autenticado" });

      const { receptor_email, receptor_nome } = req.body;
      if (!receptor_email || !receptor_nome) return res.status(400).json({ error: "Nome e e-mail do receptor são obrigatórios" });

      const { rows: ingressoRows } = await pool.query(
        `SELECT * FROM ingressos_portal WHERE codigo=$1 AND usuario_portal_id=$2`,
        [req.params.codigo, portalUserId]
      );
      if (!ingressoRows[0]) return res.status(404).json({ error: "Ingresso não encontrado" });
      const ing = ingressoRows[0];
      if (ing.status === 'usado') return res.status(400).json({ error: "Ingresso já utilizado, não pode ser transferido" });
      if (ing.status === 'cancelado') return res.status(400).json({ error: "Ingresso cancelado, não pode ser transferido" });
      if (ing.transferencia_status === 'pendente') return res.status(400).json({ error: "Já existe uma transferência pendente para este ingresso" });

      const { rows: receptorRows } = await pool.query(
        `SELECT id, nome, email FROM usuarios_portal WHERE LOWER(email)=LOWER($1)`,
        [receptor_email]
      );
      if (!receptorRows[0]) return res.status(404).json({ error: "Nenhuma conta encontrada com esse e-mail. O receptor precisa ter uma conta no sistema." });
      if (receptorRows[0].id === portalUserId) return res.status(400).json({ error: "Você não pode transferir um ingresso para si mesmo" });

      await pool.query(
        `UPDATE ingressos_portal SET
          transferencia_status='pendente',
          transferido_para_email=$1,
          transferido_para_nome=$2,
          transferido_para_user_id=$3,
          transferido_de_user_id=$4,
          transferido_em=NOW()
         WHERE codigo=$5`,
        [receptor_email, receptor_nome, receptorRows[0].id, portalUserId, req.params.codigo]
      );
      return res.json({ success: true, receptor: { nome: receptorRows[0].nome, email: receptorRows[0].email } });
    } catch (e: any) {
      console.error("Erro transferir ingresso:", e);
      return res.status(500).json({ error: "Erro interno" });
    }
  });

