  // POST /api/portal/ingressos/:codigo/receber — User 2 aceita transferência usando dados do perfil
  app.post("/api/portal/ingressos/:codigo/receber", async (req: any, res) => {
    try {
      const sess = req.session as any;
      const portalUserId = sess?.portalUserId;
      if (!portalUserId) return res.status(401).json({ error: "Não autenticado" });

      // Verifica que o ingresso tem transferência pendente para esse usuário
      const { rows: ingressoRows } = await pool.query(
        `SELECT * FROM ingressos_portal WHERE codigo=$1 AND transferido_para_user_id=$2 AND transferencia_status='pendente'`,
        [req.params.codigo, portalUserId]
      );
      if (!ingressoRows[0]) return res.status(404).json({ error: "Ingresso de transferência não encontrado" });
      const ing = ingressoRows[0];

      // Busca dados completos do perfil do receptor
      const { rows: userRows } = await pool.query(
        `SELECT * FROM usuarios_portal WHERE id=$1`, [portalUserId]
      );
      const usr = userRows[0] || {};

      // Verifica se o receptor já tem ingresso para esse evento no CPF dele
      let autoTerceiro = false;
      if (usr.cpf && ing.evento_id) {
        const { rows: jaTemRows } = await pool.query(
          `SELECT id FROM ingressos_portal
           WHERE evento_id=$1 AND titular_cpf=$2 AND usuario_portal_id=$3
           AND status != 'cancelado' AND codigo != $4 LIMIT 1`,
          [ing.evento_id, usr.cpf, portalUserId, req.params.codigo]
        );
        if (jaTemRows[0]) autoTerceiro = true;
      }

      // Atualiza o ingresso com dados do perfil do receptor
      await pool.query(
        `UPDATE ingressos_portal SET
          usuario_portal_id=$1,
          titular_nome=$2,
          titular_cpf=$3,
          titular_email=$4,
          titular_telefone=NULL,
          para_terceiro=$5,
          beneficiario_nome=NULL, beneficiario_cpf=NULL, beneficiario_email=NULL, beneficiario_telefone=NULL,
          beneficiario_nascimento=$6, beneficiario_genero=$7,
          beneficiario_logradouro=$8, beneficiario_numero=$9, beneficiario_bairro=$10,
          beneficiario_cidade=$11, beneficiario_estado=$12, beneficiario_cep=$13,
          transferencia_status='aceita', status='resgatado'
         WHERE codigo=$14`,
        [portalUserId, usr.nome, usr.cpf || null, usr.email,
          autoTerceiro,
          usr.data_nascimento || null, usr.genero || null,
          usr.logradouro || null, usr.numero || null, usr.bairro || null,
          usr.cidade || null, usr.estado || null, usr.cep || null,
          req.params.codigo]
      );

      return res.json({ success: true, auto_terceiro: autoTerceiro });
    } catch (e: any) {
      console.error("Erro receber ingresso:", e);
      return res.status(500).json({ error: "Erro interno" });
    }
  });

