  // POST /api/portal/eventos/:id/resgatar — resgatar 1+ ingressos com dados de beneficiário
  app.post("/api/portal/eventos/:id/resgatar", async (req: any, res) => {
    try {
      const sess = req.session as any;
      const portalUserId = sess?.portalUserId;
      if (!portalUserId) return res.status(401).json({ error: "Não autenticado" });

      const eventoId = parseInt(req.params.id);
      // ingressos: [{ para_terceiro: false } | { para_terceiro: true, beneficiario_nome, beneficiario_cpf, ... }]
      const { ingressos: loteIngressos } = req.body as { ingressos: any[] };
      if (!loteIngressos || !Array.isArray(loteIngressos) || loteIngressos.length === 0) {
        return res.status(400).json({ error: "Informe ao menos um ingresso" });
      }
      if (loteIngressos.length > 10) {
        return res.status(400).json({ error: "Máximo de 10 ingressos por operação" });
      }

      // Verificar evento
      const { rows: [evento] } = await pool.query('SELECT * FROM eventos_grito WHERE id=$1', [eventoId]);
      if (!evento) return res.status(404).json({ error: "Evento não encontrado" });
      if (evento.status !== "disponivel") return res.status(400).json({ error: "Evento não disponível" });

      // Buscar dados do usuário portal
      const { rows: [usuarioPortal] } = await pool.query(
        'SELECT * FROM usuarios_portal WHERE id=$1', [portalUserId]
      );
      if (!usuarioPortal) return res.status(401).json({ error: "Usuário não encontrado" });

      // ── Regra: 1 ingresso por CPF por evento ──────────────────────────────────
      const cpfTitular = (usuarioPortal.cpf || "").replace(/\D/g, "");

      // Verificar se o titular já tem ingresso neste evento
      const { rows: jaTemIngresso } = await pool.query(
        `SELECT id FROM ingressos_portal WHERE evento_id=$1 AND usuario_portal_id=$2 AND status != 'cancelado' LIMIT 1`,
        [eventoId, portalUserId]
      );
      const titularJaTem = jaTemIngresso.length > 0;

      // Se o titular já tem ingresso, todos os slots devem ser para_terceiro
      const paraMinhaSlots = loteIngressos.filter((s: any) => !s.para_terceiro);
      if (titularJaTem && paraMinhaSlots.length > 0) {
        return res.status(400).json({ error: "Você já possui um ingresso para este evento. Novos ingressos devem ser vinculados a outra pessoa." });
      }
      // O primeiro slot "para mim" é permitido (apenas 1)
      if (paraMinhaSlots.length > 1) {
        return res.status(400).json({ error: "Você só pode reservar 1 ingresso para si mesmo." });
      }

      // Coletar e validar CPFs dos terceiros
      const cpfsNoPedido: string[] = [];
      for (const slot of loteIngressos) {
        if (slot.para_terceiro) {
          if (!slot.beneficiario_cpf) return res.status(400).json({ error: "CPF do portador é obrigatório para ingressos de terceiros." });
          const cpfNums = slot.beneficiario_cpf.replace(/\D/g, "");
          if (cpfNums.length !== 11) return res.status(400).json({ error: `CPF inválido: ${slot.beneficiario_cpf}` });
          // Não pode ser o mesmo CPF do titular
          if (cpfNums === cpfTitular) return res.status(400).json({ error: "Você não pode vincular um ingresso ao seu próprio CPF." });
          // CPFs duplicados no mesmo pedido
          if (cpfsNoPedido.includes(cpfNums)) return res.status(400).json({ error: `CPF ${slot.beneficiario_cpf} aparece mais de uma vez no pedido.` });
          cpfsNoPedido.push(cpfNums);
        }
      }

      // Verificar se algum CPF de terceiro já tem ingresso neste evento
      if (cpfsNoPedido.length > 0) {
        // Normaliza CPFs para formato xxx.xxx.xxx-xx
        const cpfsFmt = cpfsNoPedido.map(n => `${n.slice(0, 3)}.${n.slice(3, 6)}.${n.slice(6, 9)}-${n.slice(9)}`);
        const { rows: terceirosComIngresso } = await pool.query(
          `SELECT beneficiario_cpf FROM ingressos_portal
           WHERE evento_id=$1 AND status != 'cancelado' AND beneficiario_cpf = ANY($2)`,
          [eventoId, cpfsFmt]
        );
        if (terceirosComIngresso.length > 0) {
          return res.status(400).json({ error: `O CPF ${terceirosComIngresso[0].beneficiario_cpf} já possui um ingresso para este evento.` });
        }
      }

      // Verificar disponibilidade
      const { rows: disponiveisRows } = await pool.query(
        'SELECT id, codigo FROM ingressos_portal WHERE evento_id=$1 AND status=$2 LIMIT $3',
        [eventoId, 'disponivel', loteIngressos.length]
      );
      if (disponiveisRows.length < loteIngressos.length) {
        return res.status(400).json({
          error: `Apenas ${disponiveisRows.length} ingresso(s) disponível(eis)`,
          disponiveis: disponiveisRows.length,
        });
      }

      // Atribuir cada ingresso
      const resgatados: any[] = [];
      for (let idx = 0; idx < loteIngressos.length; idx++) {
        const slot = loteIngressos[idx];
        const ticket = disponiveisRows[idx];
        const paraTerceiro = slot.para_terceiro === true;

        const { rows: [updated] } = await pool.query(`
          UPDATE ingressos_portal SET
            status = 'resgatado',
            usuario_portal_id = $1,
            titular_nome = $2,
            titular_cpf = $3,
            titular_email = $4,
            titular_telefone = $5,
            para_terceiro = $6,
            beneficiario_nome = $7,
            beneficiario_cpf = $8,
            beneficiario_nascimento = $9,
            beneficiario_genero = $10,
            beneficiario_logradouro = $11,
            beneficiario_numero = $12,
            beneficiario_bairro = $13,
            beneficiario_cidade = $14,
            beneficiario_estado = $15,
            beneficiario_cep = $16,
            resgatado_em = NOW()
          WHERE id = $17
          RETURNING *
        `, [
          portalUserId,
          usuarioPortal.nome,
          usuarioPortal.cpf || null,
          usuarioPortal.email || null,
          null,
          paraTerceiro,
          paraTerceiro ? (slot.beneficiario_nome || null) : null,
          paraTerceiro ? (slot.beneficiario_cpf || null) : null,
          paraTerceiro ? (slot.beneficiario_nascimento || null) : null,
          paraTerceiro ? (slot.beneficiario_genero || null) : null,
          paraTerceiro ? (slot.beneficiario_logradouro || null) : null,
          paraTerceiro ? (slot.beneficiario_numero || null) : null,
          paraTerceiro ? (slot.beneficiario_bairro || null) : null,
          paraTerceiro ? (slot.beneficiario_cidade || null) : null,
          paraTerceiro ? (slot.beneficiario_estado || null) : null,
          paraTerceiro ? (slot.beneficiario_cep || null) : null,
          ticket.id,
        ]);
        resgatados.push(updated);
      }

      // Buscar ingressos completos com dados do evento
      const codigos = resgatados.map((r: any) => r.codigo);
      const { rows: completos } = await pool.query(`
        SELECT
          i.*,
          e.titulo as evento_titulo,
          e.data_inicio as evento_data_inicio,
          e.hora_inicio as evento_hora_inicio,
          e.hora_fim as evento_hora_fim,
          e.local as evento_local,
          e.endereco as evento_endereco,
          e.cidade as evento_cidade,
          e.estado as evento_estado,
          e.banner_url as evento_banner_url
        FROM ingressos_portal i
        JOIN eventos_grito e ON e.id = i.evento_id
        WHERE i.codigo = ANY($1)
      `, [codigos]);
      return res.json({ success: true, ingressos: completos });
    } catch (e: any) {
      console.error("Portal resgatar error:", e);
      return res.status(500).json({ error: "Erro ao resgatar ingresso" });
    }
  });


  // POST /api/eventos/ingressos/validar — Scanner: validar ingresso de evento (novo sistema)
  app.post("/api/eventos/ingressos/validar", requireScannerAuth, async (req, res) => {
    try {
      const { codigo } = req.body;
      if (!codigo) return res.status(400).json({ error: "Código obrigatório" });

      const { rows } = await pool.query(`
        SELECT ip.*, eg.titulo as evento_titulo, eg.data_inicio, eg.hora_inicio, eg.local as evento_local
        FROM ingressos_portal ip
        JOIN eventos_grito eg ON eg.id = ip.evento_id
        WHERE ip.codigo = $1
      `, [codigo.trim().toUpperCase()]);

      if (rows.length === 0) {
        return res.status(404).json({ valido: false, error: "Ingresso não encontrado" });
      }

      const ingresso = rows[0];

      if (ingresso.status === 'usado') {
        // Se o checkin aconteceu há menos de 8 segundos, trata como dupla leitura do scanner
        const checkinRecenteUsado = ingresso.checkin_em &&
          (Date.now() - new Date(ingresso.checkin_em).getTime()) < 8000;
        const isThirdUsed = ingresso.para_terceiro;
        if (checkinRecenteUsado) {
          return res.json({
            valido: true,
            ingresso: {
              codigo: ingresso.codigo,
              titular: isThirdUsed ? ingresso.beneficiario_nome : ingresso.titular_nome,
              paraTerceiro: isThirdUsed,
              eventoNome: ingresso.evento_titulo,
              eventoData: ingresso.data_inicio,
              eventoHora: ingresso.hora_inicio,
              eventoLocal: ingresso.evento_local,
            },
            demografico: {
              nome: isThirdUsed ? ingresso.beneficiario_nome : ingresso.titular_nome,
              genero: isThirdUsed ? ingresso.beneficiario_genero : null,
              nascimento: isThirdUsed ? ingresso.beneficiario_nascimento : null,
            }
          });
        }
        return res.json({
          valido: false,
          jaUsado: true,
          error: "Ingresso já foi utilizado",
          usadoEm: ingresso.checkin_em,
          ingresso: {
            codigo: ingresso.codigo,
            titular: isThirdUsed ? ingresso.beneficiario_nome : ingresso.titular_nome,
            eventoNome: ingresso.evento_titulo,
            eventoData: ingresso.data_inicio,
            eventoHora: ingresso.hora_inicio,
            eventoLocal: ingresso.evento_local,
          },
          demografico: {
            nome: isThirdUsed ? ingresso.beneficiario_nome : ingresso.titular_nome,
            nascimento: isThirdUsed ? ingresso.beneficiario_nascimento : null,
            genero: isThirdUsed ? ingresso.beneficiario_genero : null,
          }
        });
      }

      if (ingresso.status === 'disponivel') {
        return res.status(400).json({ valido: false, error: "Ingresso não foi retirado pelo participante" });
      }

      if (ingresso.status === 'cancelado') {
        return res.status(400).json({ valido: false, error: "Ingresso cancelado" });
      }

      // status === 'resgatado' — marcar como usado (AND status garante idempotência contra race condition)
      const { rows: updateRows } = await pool.query(`
        UPDATE ingressos_portal
        SET status = 'usado', checkin_em = NOW()
        WHERE id = $1 AND status = 'resgatado'
        RETURNING *
      `, [ingresso.id]);

      if (updateRows.length === 0) {
        // Outro request já marcou como usado (race condition) — busca dados atuais
        const { rows: [current] } = await pool.query(
          `SELECT ip.*, eg.titulo as evento_titulo, eg.data_inicio, eg.hora_inicio, eg.local as evento_local
           FROM ingressos_portal ip JOIN eventos_grito eg ON eg.id = ip.evento_id WHERE ip.id = $1`,
          [ingresso.id]
        );
        // Se o checkin aconteceu há menos de 5 segundos, é a mesma leitura disparada duas vezes pelo scanner
        const checkinRecente = current?.checkin_em &&
          (Date.now() - new Date(current.checkin_em).getTime()) < 5000;
        if (checkinRecente) {
          const isThirdRace = ingresso.para_terceiro;
          return res.json({
            valido: true,
            ingresso: {
              codigo: ingresso.codigo,
              titular: isThirdRace ? ingresso.beneficiario_nome : ingresso.titular_nome,
              paraTerceiro: isThirdRace,
              eventoNome: ingresso.evento_titulo,
              eventoData: ingresso.data_inicio,
              eventoHora: ingresso.hora_inicio,
              eventoLocal: ingresso.evento_local,
            },
            demografico: {
              nome: isThirdRace ? ingresso.beneficiario_nome : ingresso.titular_nome,
              genero: isThirdRace ? ingresso.beneficiario_genero : null,
              nascimento: isThirdRace ? ingresso.beneficiario_nascimento : null,
            }
          });
        }
        return res.json({
          valido: false,
          jaUsado: true,
          error: "Ingresso já foi utilizado",
          usadoEm: current?.checkin_em,
          ingresso: {
            codigo: ingresso.codigo,
            titular: ingresso.para_terceiro ? ingresso.beneficiario_nome : ingresso.titular_nome,
            eventoNome: ingresso.evento_titulo,
            eventoData: ingresso.data_inicio,
            eventoHora: ingresso.hora_inicio,
            eventoLocal: ingresso.evento_local,
          },
          demografico: {
            nome: ingresso.para_terceiro ? ingresso.beneficiario_nome : ingresso.titular_nome,
          }
        });
      }

      const isThird = ingresso.para_terceiro;
      return res.json({
        valido: true,
        ingresso: {
          codigo: ingresso.codigo,
          titular: isThird ? ingresso.beneficiario_nome : ingresso.titular_nome,
          paraTerceiro: isThird,
          beneficiarioNome: ingresso.beneficiario_nome,
          eventoNome: ingresso.evento_titulo,
          eventoData: ingresso.data_inicio,
          eventoHora: ingresso.hora_inicio,
          eventoLocal: ingresso.evento_local,
        },
        demografico: {
          nome: isThird ? ingresso.beneficiario_nome : ingresso.titular_nome,
          nascimento: isThird ? ingresso.beneficiario_nascimento : null,
          genero: isThird ? ingresso.beneficiario_genero : null,
          logradouro: isThird ? ingresso.beneficiario_logradouro : null,
          numero: isThird ? ingresso.beneficiario_numero : null,
          bairro: isThird ? ingresso.beneficiario_bairro : null,
          cidade: isThird ? ingresso.beneficiario_cidade : null,
          estado: isThird ? ingresso.beneficiario_estado : null,
          cep: isThird ? ingresso.beneficiario_cep : null,
          email: isThird ? ingresso.beneficiario_email : ingresso.titular_email,
        }
      });
    } catch (e: any) {
      console.error("Erro ao validar ingresso:", e);
      res.status(500).json({ error: "Erro interno ao validar ingresso" });
    }
  });

