  // POST /api/push/test — notificação teste (apenas dispositivo do usuário logado ou token explícito)
  app.post("/api/push/test", ...pushAdminAuth, async (req, res) => {
    try {
      const title = (req.body?.title || "Teste — Clube do Grito").toString().trim().slice(0, 120);
      const body = (req.body?.body || "Notificação de teste enviada com sucesso.").toString().trim().slice(0, 500);
      const url = typeof req.body?.url === "string" ? req.body.url.trim() : undefined;
      const explicitToken = typeof req.body?.token === "string" ? req.body.token.trim() : "";

      let tokens: string[] = [];
      let tokenMeta: { token: string; user_key: string; user_type: string }[] = [];
      if (explicitToken) {
        if (explicitToken.length < 20) {
          return res.status(400).json({ error: "token inválido" });
        }
        tokens = [explicitToken];
        tokenMeta = [{ token: explicitToken, user_key: String((req as any).user?.id ?? ""), user_type: "test" }];
      } else {
        const userId = String((req as any).user?.id ?? "");
        if (!userId) return res.status(400).json({ error: "Usuário não identificado" });
        const result = await pool.query(
          "SELECT token, user_key, user_type FROM fcm_tokens WHERE ativo = true AND user_key = $1",
          [userId]
        );
        tokenMeta = result.rows;
        tokens = tokenMeta.map((r: any) => r.token);
      }

      if (tokens.length === 0) {
        return res.status(404).json({
          success: false,
          error: "Nenhum dispositivo registrado para este usuário. Use 'Registrar este navegador' antes do teste.",
        });
      }

      const destinatarios: { token: string; accepted: boolean; messageId?: string; errorCode?: string }[] = [];
      let enviados = 0;
      let falhas = 0;
      let tokensInvalidosRemovidos = 0;

      const disparadoPor = (req as any).user?.id ? Number((req as any).user.id) : null;

      for (const token of tokens) {
        const r = await sendFcmToSingleToken(token, { title, body, url }, PUSH_ICON_URL, PUSH_BADGE_URL);
        const meta = tokenMeta.find((m) => m.token === token);
        destinatarios.push({
          token: maskFcmToken(token),
          accepted: r.accepted,
          messageId: r.messageId,
          errorCode: r.errorCode,
        });
        await insertPushLog(pool, {
          gatilho: "push_test",
          destinatarioKey: meta?.user_key ?? null,
          destinatarioRole: meta?.user_type ?? "test",
          status: r.accepted ? "success" : "error",
          erro: r.errorMessage ?? r.errorCode ?? null,
          tituloRenderizado: title,
          mensagemRenderizado: body,
          payload: { url: url ?? null },
          origem: "teste",
          disparadoPorUserId: disparadoPor,
        }).catch(() => { });
        if (r.accepted) {
          enviados++;
        } else {
          falhas++;
          if (r.errorCode && ["messaging/registration-token-not-registered", "messaging/invalid-registration-token"].includes(r.errorCode)) {
            await pool.query(
              "UPDATE fcm_tokens SET ativo = false, falhou_em = NOW(), updated_at = NOW() WHERE token = $1",
              [token]
            );
            rejectedPushTokens.add(token);
            tokensInvalidosRemovidos++;
          }
        }
      }

      res.json({
        success: enviados > 0,
        totalTokens: tokens.length,
        enviados,
        falhas,
        tokensInvalidosRemovidos,
        destinatarios,
        firebaseAccepted: enviados > 0,
      });
    } catch (err: any) {
      console.error("[Push] Erro test:", err.message);
      res.status(500).json({ error: "Erro ao enviar notificação de teste" });
    }
  });

